"""Rubric-generation domain models, rendering, and lineage validation."""

from __future__ import annotations

import json
import re
import unicodedata
from dataclasses import dataclass
from enum import Enum

from rubric_gen.artifacts.hashing import sha256_text
from rubric_gen.submission_revision.autorubric import (
    AutoRubricAdapterError,
    parse_autorubric_rubric,
)


_SHA256_PATTERN = re.compile(r"[0-9a-f]{64}")
_SCORING_PROTOCOL_PREFIX = "Scoring protocol: "
_ELICITED_CLAIM_SCOPE = (
    "Apply this penalty only when the submission claims or relies on this "
    "property. Do not penalize an unclaimed optional feature. "
)
_ELICITED_PASS_SCOPE = "No covered claim is made, or the check passes: "
_ELICITED_FAILURE_SCOPE = (
    "The submission claims or relies on the property, but the check fails: "
)


def require_nonnegative_int(value: object, field_name: str) -> int:
    if type(value) is not int or value < 0:
        raise ValueError(f"{field_name} must be a non-negative integer")
    return value


def require_sha256(value: object, field_name: str) -> str:
    if type(value) is not str or _SHA256_PATTERN.fullmatch(value) is None:
        raise ValueError(f"{field_name} must be a lowercase SHA-256 digest")
    return value


def _scoring_protocol(rubric_text: str) -> str | None:
    values = [
        line.removeprefix(_SCORING_PROTOCOL_PREFIX)
        for line in rubric_text.splitlines()
        if line.startswith(_SCORING_PROTOCOL_PREFIX)
    ]
    if not values:
        return None
    if len(values) != 1 or not values[0] or values[0] != values[0].strip():
        raise ValueError("rubric has an invalid scoring protocol directive")
    return values[0]


def _validate_complete_rubric(rubric_text: str) -> tuple[str | None, int]:
    """Validate the current complete-rubric grammar and score contract."""

    try:
        parsed = parse_autorubric_rubric(rubric_text)
    except AutoRubricAdapterError as exc:
        raise ValueError(f"rubric is not structurally complete: {exc}") from exc
    criterion_ids = [criterion.criterion_id for criterion in parsed.criteria]
    if criterion_ids != [
        f"criterion_{index}" for index in range(1, len(criterion_ids) + 1)
    ]:
        raise ValueError("complete rubric criterion numbers must be contiguous")
    titles = [" ".join(criterion.title.lower().split()) for criterion in parsed.criteria]
    if len(set(titles)) != len(titles):
        raise ValueError("complete rubric contains duplicate criterion titles")

    protocol = _scoring_protocol(rubric_text)
    expected_maximum = parsed.normalization_maximum or 100
    total_maximum = 0
    for criterion in parsed.criteria:
        labels = [level.label for level in criterion.levels]
        expected_labels = [
            chr(ord("A") + index) for index in range(len(labels))
        ]
        if labels != (["A", "B"] if protocol is not None else expected_labels):
            raise ValueError(
                f"{criterion.criterion_id} has invalid ordered level labels"
            )
        if protocol is None and len(labels) < 3:
            raise ValueError(
                f"{criterion.criterion_id} must contain at least three levels"
            )
        points = [level.points for level in criterion.levels]
        if (
            any(left <= right for left, right in zip(points, points[1:]))
            or points[0] < 0
            or points.count(0) != 1
        ):
            raise ValueError(
                f"{criterion.criterion_id} has invalid ordered level points"
            )
        total_maximum += points[0]
    if total_maximum != expected_maximum:
        raise ValueError(
            "complete rubric top-level points do not match its score maximum"
        )
    return protocol, expected_maximum


class RubricPolicy(str, Enum):
    """Define how an experiment changes its active rubric."""

    FIXED = "fixed"
    OFFLINE_ELICITATION = "offline_elicitation"
    ONLINE_ELICITATION = "online_elicitation"
    RED_TEAM_ARTIFACT = "red_team_artifact"
    RED_TEAM_TRACE = "red_team_trace"

    @property
    def uses_online_evidence(self) -> bool:
        return self in {
            self.ONLINE_ELICITATION,
            self.RED_TEAM_ARTIFACT,
            self.RED_TEAM_TRACE,
        }

    @property
    def uses_red_team(self) -> bool:
        return self in {self.RED_TEAM_ARTIFACT, self.RED_TEAM_TRACE}

    @property
    def uses_red_team_trace(self) -> bool:
        return self is self.RED_TEAM_TRACE


@dataclass(frozen=True)
class CompleteRubric:
    """Store one complete rubric and its verified content hash."""

    content: str
    content_sha256: str

    def __post_init__(self) -> None:
        if type(self.content) is not str or not self.content.strip():
            raise ValueError("rubric content must be a non-empty string")
        require_sha256(self.content_sha256, "content_sha256")
        if sha256_text(self.content) != self.content_sha256:
            raise ValueError("content_sha256 does not match rubric content")
        _validate_complete_rubric(self.content)

    @classmethod
    def from_content(cls, content: str) -> CompleteRubric:
        """Create a rubric with the hash of its exact UTF-8 content."""

        if type(content) is not str:
            raise ValueError("rubric content must be a string")
        return cls(content=content, content_sha256=sha256_text(content))


def is_valid_single_line_text(
    value: object,
    *,
    max_chars: int | None = None,
) -> bool:
    """Return true for canonical printable text with no hidden line break."""

    return bool(
        type(value) is str
        and value
        and value == value.strip()
        and (max_chars is None or len(value) <= max_chars)
        and len(value.splitlines()) == 1
        and not any(
            unicodedata.category(character).startswith("C")
            for character in value
        )
    )


def _require_criterion_text(
    value: object,
    field_name: str,
) -> str:
    if not is_valid_single_line_text(value):
        raise ValueError(f"{field_name} must be printable single-line text")
    assert isinstance(value, str)
    return value


@dataclass(frozen=True)
class ElicitedCriterion:
    """Store one general criterion induced from a blinded artifact history."""

    criterion_id: str
    title: str
    requirement: str
    levels: tuple[tuple[str, int, str], ...]
    provenance_pair_ids: tuple[str, ...]
    source_generation: int

    def __post_init__(self) -> None:
        if (
            type(self.criterion_id) is not str
            or re.fullmatch(r"elicited_[0-9a-f]{16}", self.criterion_id) is None
        ):
            raise ValueError("elicited criterion has an invalid ID")
        _require_criterion_text(
            self.title,
            "elicited criterion title",
        )
        _require_criterion_text(
            self.requirement,
            "elicited criterion requirement",
        )
        if (
            type(self.levels) is not tuple
            or len(self.levels) < 2
            or any(
                type(item) is not tuple
                or len(item) != 3
                or type(item[0]) is not str
                or len(item[0]) != 1
                or not item[0].isupper()
                or type(item[1]) is not int
                or not is_valid_single_line_text(item[2])
                for item in self.levels
            )
        ):
            raise ValueError("elicited criterion levels are invalid")
        labels = tuple(label for label, _, _ in self.levels)
        if labels != tuple(
            chr(ord("A") + index) for index in range(len(labels))
        ):
            raise ValueError("elicited criterion level labels are not contiguous")
        points = tuple(point for _, point, _ in self.levels)
        if (
            points[0] != 0
            or any(left <= right for left, right in zip(points, points[1:]))
        ):
            raise ValueError(
                "elicited criterion points must start at zero and strictly decrease"
            )
        if (
            type(self.provenance_pair_ids) is not tuple
            or len(set(self.provenance_pair_ids)) != len(self.provenance_pair_ids)
            or any(
                type(pair_id) is not str
                or re.fullmatch(r"pair_[0-9a-f]{16}", pair_id) is None
                for pair_id in self.provenance_pair_ids
            )
        ):
            raise ValueError("elicited criterion provenance is invalid")
        require_nonnegative_int(self.source_generation, "source_generation")
        expected_id = "elicited_" + sha256_text(json.dumps(
            {
                "title": self.title,
                "requirement": self.requirement,
                "levels": self.levels,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ))[:16]
        if self.criterion_id != expected_id:
            raise ValueError("elicited criterion ID does not match its content")

    @classmethod
    def create(
        cls,
        *,
        title: str,
        requirement: str,
        levels: tuple[tuple[str, int, str], ...],
        provenance_pair_ids: tuple[str, ...],
        source_generation: int,
    ) -> "ElicitedCriterion":
        payload = json.dumps(
            {
                "title": title,
                "requirement": requirement,
                "levels": levels,
            },
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        return cls(
            criterion_id="elicited_" + sha256_text(payload)[:16],
            title=title,
            requirement=requirement,
            levels=levels,
            provenance_pair_ids=provenance_pair_ids,
            source_generation=source_generation,
        )

    def as_dict(self) -> dict[str, object]:
        return {
            "criterion_id": self.criterion_id,
            "title": self.title,
            "requirement": self.requirement,
            "levels": [
                {"label": label, "points": points, "description": description}
                for label, points, description in self.levels
            ],
            "provenance_pair_ids": list(self.provenance_pair_ids),
            "source_generation": self.source_generation,
        }


def parse_elicited_criterion(value: object) -> ElicitedCriterion:
    if not isinstance(value, dict) or set(value) != {
        "criterion_id",
        "title",
        "requirement",
        "levels",
        "provenance_pair_ids",
        "source_generation",
    }:
        raise ValueError("elicited criterion has invalid fields")
    raw_levels = value.get("levels")
    if not isinstance(raw_levels, list):
        raise ValueError("elicited criterion levels must be a list")
    levels: list[tuple[str, int, str]] = []
    for level in raw_levels:
        if not isinstance(level, dict) or set(level) != {
            "label",
            "points",
            "description",
        }:
            raise ValueError("elicited criterion level has invalid fields")
        levels.append((  # type: ignore[arg-type]
            level["label"],
            level["points"],
            level["description"],
        ))
    raw_provenance = value.get("provenance_pair_ids")
    if not isinstance(raw_provenance, list):
        raise ValueError("elicited criterion provenance must be a list")
    return ElicitedCriterion(
        criterion_id=value.get("criterion_id"),  # type: ignore[arg-type]
        title=value.get("title"),  # type: ignore[arg-type]
        requirement=value.get("requirement"),  # type: ignore[arg-type]
        levels=tuple(levels),
        provenance_pair_ids=tuple(raw_provenance),  # type: ignore[arg-type]
        source_generation=value.get("source_generation"),  # type: ignore[arg-type]
    )


def _criterion_specific_requirement(
    criterion: object,
) -> str:
    criterion_id = getattr(criterion, "criterion_id")
    title = getattr(criterion, "title")
    number = criterion_id.removeprefix("criterion_")
    marker = f"Criterion {number}: {title}"
    requirement = getattr(criterion, "requirement")
    if requirement.startswith(marker):
        suffix = requirement[len(marker):]
    else:
        separator = f"\n\n{marker}"
        marker_offset = requirement.find(separator)
        if marker_offset < 0:
            raise ValueError(
                f"{criterion_id} lacks its canonical requirement marker"
            )
        suffix = requirement[marker_offset + len(separator):]
    if suffix.startswith("\n\n"):
        suffix = suffix[2:]
    elif suffix:
        raise ValueError(f"{criterion_id} lacks its canonical requirement marker")
    return suffix.strip()


def _context_with_normalization_maximum(
    context: str,
    *,
    new_maximum: int,
) -> str:
    """Return context with one authoritative percentage denominator."""

    lines = context.splitlines()
    normalization_prefix = "Score normalization maximum:"
    normalization_pattern = re.compile(
        r"^[ \t]*Score normalization maximum:[ \t]*[1-9]\d*[ \t]*$"
    )
    total_points_pattern = re.compile(r"^[ \t]*Total Points:[ \t]*\d+[ \t]*$")
    output: list[str] = []
    found_normalization = False
    for line in lines:
        if normalization_pattern.fullmatch(line):
            if found_normalization:
                raise ValueError("rubric has duplicate normalization directives")
            output.append(f"{normalization_prefix} {new_maximum}")
            found_normalization = True
        elif total_points_pattern.fullmatch(line):
            output.append(f"Total Points: {new_maximum}")
        else:
            output.append(line)
    if not found_normalization:
        if output and output[-1]:
            output.append("")
        output.append(f"{normalization_prefix} {new_maximum}")
    return "\n".join(output)


def render_augmented_rubric(
    original_rubric: CompleteRubric,
    elicited_criteria: tuple[ElicitedCriterion, ...],
) -> CompleteRubric:
    """Render one rubric with fixed original text and normalized penalties."""

    if not isinstance(original_rubric, CompleteRubric):
        raise ValueError("original_rubric must be a CompleteRubric")
    if (
        type(elicited_criteria) is not tuple
        or any(not isinstance(item, ElicitedCriterion) for item in elicited_criteria)
    ):
        raise ValueError("elicited_criteria has an invalid value")
    if len({item.criterion_id for item in elicited_criteria}) != len(
        elicited_criteria
    ):
        raise ValueError("elicited criteria repeat a content identity")
    if not elicited_criteria:
        return original_rubric

    parsed = parse_autorubric_rubric(original_rubric.content)
    protocol = _scoring_protocol(original_rubric.content)
    required_labels = ("A", "B") if protocol is not None else ("A", "B", "C")
    original_maximum = parsed.normalization_maximum or 100
    for criterion in elicited_criteria:
        if tuple(label for label, _, _ in criterion.levels) != required_labels:
            raise ValueError(
                "elicited criterion levels do not match the rubric scoring protocol"
            )
    titles = [" ".join(item.title.casefold().split()) for item in elicited_criteria]
    original_titles = {
        " ".join(criterion.title.casefold().split()) for criterion in parsed.criteria
    }
    if len(set(titles)) != len(titles) or set(titles) & original_titles:
        raise ValueError("elicited criteria contain duplicate criterion titles")

    lines: list[str] = []
    if parsed.context:
        lines.extend((
            _context_with_normalization_maximum(
                parsed.context,
                new_maximum=original_maximum,
            ),
            "",
        ))
    else:
        lines.extend((
            f"Score normalization maximum: {original_maximum}",
            "",
        ))
    for index, criterion in enumerate(parsed.criteria, start=1):
        lines.append(f"Criterion {index}: {criterion.title}")
        specific = _criterion_specific_requirement(criterion)
        if specific:
            lines.append(specific)
        lines.append(
            "Levels: " + " ".join(
                f"{level.label}={level.points}"
                for level in criterion.levels
            )
        )
        lines.extend(
            f"[{level.label}]: {level.description}"
            for level in criterion.levels
        )
        lines.append("")

    offset = len(parsed.criteria)
    for index, criterion in enumerate(elicited_criteria, start=1):
        number = offset + index
        lines.extend((
            f"Criterion {number}: {criterion.title}",
            _ELICITED_CLAIM_SCOPE + criterion.requirement,
            f"Elicited criterion ID: {criterion.criterion_id}",
            "Levels: " + " ".join(
                f"{label}={point}"
                for label, point, _ in criterion.levels
            ),
        ))
        lines.extend(
            f"[{label}]: "
            + (
                _ELICITED_PASS_SCOPE
                if label == "A"
                else _ELICITED_FAILURE_SCOPE
            )
            + description
            for label, _, description in criterion.levels
        )
        lines.append("")
    return CompleteRubric.from_content("\n".join(lines).rstrip() + "\n")


@dataclass(frozen=True)
class RubricGeneration:
    """Store one complete active rubric and its current elicited criteria."""

    generation_round: int
    source_checkpoint: int | None
    rubric: CompleteRubric
    elicited_criteria: tuple[ElicitedCriterion, ...]
    proposer_call_budget: int

    def __post_init__(self) -> None:
        generation_round = require_nonnegative_int(
            self.generation_round,
            "generation_round",
        )
        require_nonnegative_int(self.proposer_call_budget, "proposer_call_budget")
        if self.source_checkpoint is not None:
            source_checkpoint = require_nonnegative_int(
                self.source_checkpoint,
                "source_checkpoint",
            )
            if generation_round < 2 or source_checkpoint != generation_round - 1:
                raise ValueError(
                    "live source checkpoint must precede its rubric generation"
                )
        if generation_round <= 1 and self.source_checkpoint is not None:
            raise ValueError(
                "initial and pre-treatment rubrics cannot have a source checkpoint"
            )
        if not isinstance(self.rubric, CompleteRubric):
            raise ValueError("rubric must be a CompleteRubric")
        if (
            type(self.elicited_criteria) is not tuple
            or any(
                not isinstance(criterion, ElicitedCriterion)
                for criterion in self.elicited_criteria
            )
        ):
            raise ValueError("elicited_criteria has an invalid value")
        if len({
            criterion.criterion_id for criterion in self.elicited_criteria
        }) != len(self.elicited_criteria):
            raise ValueError("elicited_criteria contains duplicate criteria")
        if generation_round == 0 and self.elicited_criteria:
            raise ValueError("the initial rubric cannot contain elicited criteria")
        if any(
            criterion.source_generation > generation_round
            for criterion in self.elicited_criteria
        ):
            raise ValueError("elicited criterion comes from a later generation")

    @property
    def generation_sha256(self) -> str:
        """Return the identity of the complete generation content."""

        payload = json.dumps(
            {
                "generation_round": self.generation_round,
                "source_checkpoint": self.source_checkpoint,
                "rubric_sha256": self.rubric.content_sha256,
                "elicited_criteria": [
                    criterion.as_dict() for criterion in self.elicited_criteria
                ],
                "proposer_call_budget": self.proposer_call_budget,
            },
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        return sha256_text(payload)

    @property
    def scoring_protocol(self) -> str | None:
        protocol, _ = _validate_complete_rubric(self.rubric.content)
        return protocol

    @property
    def normalization_maximum(self) -> int:
        _, maximum = _validate_complete_rubric(self.rubric.content)
        return maximum

    def validate_successor(self, prior: RubricGeneration) -> None:
        """Require a consecutive generation on the same original score scale."""

        if not isinstance(prior, RubricGeneration):
            raise ValueError("prior must be a RubricGeneration")
        if self.generation_round != prior.generation_round + 1:
            raise ValueError("rubric generations must be consecutive")
        if self.scoring_protocol != prior.scoring_protocol:
            raise ValueError("a rubric generation cannot change scoring protocol")
        if self.normalization_maximum != prior.normalization_maximum:
            raise ValueError("a rubric generation cannot change score normalization")

src/rubric_gen/submission_revision/pretr:
"""Explicit reuse of sealed current-format starting rubrics across studies.

The source's experiment identity and blinding scope are preserved. No source
record is rewritten and no missing source rubric is generated implicitly.
"""
from pathlib import Path
import shutil

from rubric_gen.runtime.yaml import load_yaml_strict
from rubric_gen.submission_revision.artifacts import read_json_object
from rubric_gen.submission_revision.experiment import Experiment, load_experiment


def scope_id(experiment: Experiment) -> str:
    source = experiment.pretreatment_source
    return source['experiment_id'] if source else experiment.experiment_id


def source_pool(experiment: Experiment) -> Path | None:
    source = experiment.pretreatment_source
    if source is None:
        return None
    path = Path(source['experiment'])
    raw = load_yaml_strict(path.read_text())
    if not isinstance(raw, dict) or 'pretreatment_source' in raw:
        raise ValueError('nested pre-treatment reuse is not supported')
    original = load_experiment(path)
    if original.experiment_id != source['experiment_id']:
        raise ValueError('pre-treatment source experiment identity mismatch')
    for key in ('benchmark', 'tasks_dir', 'seed_generator', 'rubric_paraphrases'):
        if original.payload[key] != experiment.payload[key]:
            raise ValueError(f'pre-treatment source differs: {key}')
    if not set(experiment.task_ids) <= set(original.task_ids):
        raise ValueError('pre-treatment source is missing tasks')
    for key in ('prompt', 'rubric_name', 'rubric_proposer_model', 'rubric_proposer_max_retries'):
        if original.protocol[key] != experiment.protocol[key]:
            raise ValueError(f'pre-treatment source protocol differs: {key}')
    for stage in ('seed', 'paraphrase'):
        if original.dag[stage]['output_dir'] != experiment.dag[stage]['output_dir']:
            raise ValueError(f'pre-treatment source input path differs: {stage}')
    root = Path(source['study_dir'])
    if root.is_symlink() or not root.is_dir():
        raise ValueError('pre-treatment source study is not a regular directory')
    ledger = read_json_object(root / 'study.json', 'pre-treatment source study')
    if ledger.get('experiment_id') != original.experiment_id or ledger.get('status') != 'completed':
        raise ValueError('pre-treatment source study is not completed with the expected identity')
    pool = root / 'pretreatment-rubrics'
    if pool.is_symlink() or not pool.is_dir():
        raise ValueError('pre-treatment source pool is missing or symlinked')
    return pool


def copy_pool_entry(source: Path, destination: Path) -> None:
    """Copy a prevalidated entry without overwriting; caller validates destination."""
    if source.is_symlink() or not source.is_dir():
        raise ValueError('pre-treatment source entry is missing or symlinked')
    for path in source.rglob('*'):
        if path.is_symlink():
            raise ValueError(f'symlink in pre-treatment source: {path}')
    if destination.exists():
        return
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(source, destination)

src/rubric_gen/submission_revision/store:
"""Durable state, manifest, rubric, and event persistence for revisions."""

from __future__ import annotations

import json
import os
from pathlib import Path

from .artifacts import (
    read_json_object,
)
from rubric_gen.artifacts.serialization import write_json_atomic
from .judge import SCORING_IDENTITY_KEYS
from .models import RevisionState
from .rubric_generation import RubricGeneration, RubricPolicy
from .rubric_generation_store import (
    load_rubric_generation,
    persist_rubric_generation,
)


SEED_SCORING_CONTRACT_KEYS = (
    "scoring_implementation_sha256",
    "effective_judge_model",
    "benchmark",
    "grading_engine",
    "review_mode",
    "max_review_chars",
    "rubric_source",
    "rubric_set_id",
    "rubric_id",
    "structured_rubric_sha256",
    "rendered_rubric_sha256",
    "manifest_sha256",
)

JUDGE_EXECUTION_CONTRACT_KEYS = (
    "scoring_implementation_sha256",
    "effective_judge_model",
    "benchmark",
    "grading_engine",
    "review_mode",
    "max_review_chars",
)


def extract_scoring_identity(
    payload: dict[str, object],
    *,
    context: str,
) -> dict[str, object]:
    missing = [key for key in SCORING_IDENTITY_KEYS if key not in payload]
    if missing:
        raise RuntimeError(f"{context} lacks scoring identity: {', '.join(missing)}")
    return {key: payload[key] for key in SCORING_IDENTITY_KEYS}


def extract_seed_scoring_contract(
    payload: dict[str, object],
    *,
    context: str,
) -> dict[str, object]:
    """Return the exact current scoring contract for a reusable seed."""

    identity = extract_scoring_identity(payload, context=context)
    return {key: identity[key] for key in SEED_SCORING_CONTRACT_KEYS}


def extract_judge_execution_contract(
    payload: dict[str, object],
    *,
    context: str,
) -> dict[str, object]:
    """Return the exact non-rubric judge execution identity."""

    identity = extract_scoring_identity(payload, context=context)
    return {key: identity[key] for key in JUDGE_EXECUTION_CONTRACT_KEYS}


class RevisionStore:
    """Persist and verify one revision experiment's durable control state."""

    def __init__(
        self,
        experiment_dir: Path,
        *,
        initial_generation: RubricGeneration,
        rubric_policy: RubricPolicy,
        scoring_identity: dict[str, object],
    ) -> None:
        self.experiment_dir = experiment_dir
        self.initial_generation = initial_generation
        self.rubric_policy = rubric_policy
        self.scoring_identity = dict(scoring_identity)

    @property
    def manifest_path(self) -> Path:
        return self.experiment_dir / "manifest.json"

    @property
    def state_path(self) -> Path:
        return self.experiment_dir / "state.json"

    def persist_initial_generation(self) -> None:
        persist_rubric_generation(
            self.experiment_dir,
            self.initial_generation,
            self.rubric_policy,
        )

    def verify_initial_generation(self) -> None:
        persisted = load_rubric_generation(
            self.experiment_dir,
            0,
            expected_policy=self.rubric_policy,
        )
        if persisted != self.initial_generation:
            raise RuntimeError("persisted initial rubric generation changed")

    def write_state(self, state: RevisionState) -> None:
        write_json_atomic(self.state_path, state.as_json())

    def read_state(self) -> RevisionState:
        return RevisionState.from_json(
            read_json_object(self.state_path, "revision state")
        )

    def update_manifest(self, updates: dict[str, object]) -> None:
        manifest = read_json_object(self.manifest_path, "revision manifest")
        manifest.update(updates)
        write_json_atomic(self.manifest_path, manifest)

    def record_session_id(self, session_id: str) -> None:
        if type(session_id) is not str or not session_id.strip():
            raise RuntimeError("solver did not return a persistent session ID")
        manifest = read_json_object(self.manifest_path, "revision manifest")
        previous = manifest.get("session_id")
        if previous not in {None, session_id}:
            raise RuntimeError("solver changed provider session ID")
        self.update_manifest({"session_id": session_id})

    def record_effective_solver_model(
        self,
        state: RevisionState,
        model: str,
    ) -> None:
        if type(model) is not str or not model.strip():
            raise RuntimeError("solver did not report an effective model")
        if state.effective_solver_model not in {None, model}:
            raise RuntimeError("solver changed model during the revision loop")
        state.effective_solver_model = model
        self.update_manifest({"effective_solver_model": model})
        self.write_state(state)

    def verify_scoring_identity(self, validation_path: Path) -> None:
        validation = read_json_object(
            validation_path, "optimizer score validation"
        )
        identity = extract_scoring_identity(
            validation,
            context="optimizer score validation",
        )
        manifest = read_json_object(self.manifest_path, "revision manifest")
        if manifest.get("initial_scoring_identity") != self.scoring_identity:
            raise RuntimeError("optimizer scoring identity changed in the manifest")
        if identity != self.scoring_identity:
            raise RuntimeError("optimizer scoring identity changed during revision")

    def append_event(self, payload: dict[str, object]) -> None:
        events = self.experiment_dir / "events.jsonl"
        with events.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(payload, sort_keys=True, separators=(",", ":")))
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())

src/rubric_gen/submission_revision/evolu:
"""Isolated criterion application calls and deterministic response aggregation."""
from __future__ import annotations

import json
from collections.abc import Callable
from dataclasses import dataclass

from rubric_gen.submission_revision.evolution_protocol import (
    CriterionCandidate, validated_validation_response, validation_schema,
)
from rubric_gen.submission_revision.evolution_serialization import canonical_json


@dataclass(frozen=True)
class ValidationStageResult:
    raw_text: str
    value: object
    attempt_count: int
    fallback_reason: str | None = None
    calls: tuple[dict[str, object], ...] = ()


def validate_independently(
    *,
    stage: Callable[..., ValidationStageResult],
    candidates: tuple[CriterionCandidate, ...],
    artifact_ids: tuple[str, ...],
    evidence: str,
    fallback_text: str,
) -> ValidationStageResult:
    """Keep other artifacts out of each application judgment's context."""
    payload = json.loads(evidence)
    artifacts = {item["artifact_id"]: item for item in payload["artifacts"]}
    if set(artifacts) != set(artifact_ids):
        raise ValueError("validation evidence artifact coverage differs")
    fallback = json.loads(fallback_text)
    parts: list[ValidationStageResult] = []
    for artifact_id in artifact_ids:
        one_fallback = json.loads(fallback_text)
        for item in one_fallback["validations"]:
            item["artifact_applications"] = [
                application for application in item["artifact_applications"]
                if application["artifact_id"] == artifact_id
            ]
        parts.append(stage(
            stage="validation",
            evidence=canonical_json({**payload, "artifacts": [artifacts[artifact_id]]}),
            response_schema=validation_schema(candidates, (artifact_id,)),
            validator=lambda text, aid=artifact_id: validated_validation_response(
                text, candidates=candidates, artifact_ids=(aid,),
            ),
            fallback_text=canonical_json(one_fallback),
        ))
    return combine_validation_results(
        candidates=candidates, artifact_ids=artifact_ids,
        parts=parts, fallback_text=fallback_text,
    )

def combine_validation_results(
    *, candidates: tuple[CriterionCandidate, ...],
    artifact_ids: tuple[str, ...], parts: list[ValidationStageResult], fallback_text: str,
) -> ValidationStageResult:
    calls = tuple({
        "artifact_id": aid, "raw_text": part.raw_text,
        "attempt_count": part.attempt_count, "fallback_reason": part.fallback_reason,
    } for aid, part in zip(artifact_ids, parts, strict=True))
    fallback = json.loads(fallback_text)
    attempts = sum(part.attempt_count for part in parts)
    failures = [part.fallback_reason for part in parts if part.fallback_reason]
    if failures:
        # A partly validated candidate must never be admitted.
        return ValidationStageResult(
            fallback_text,
            validated_validation_response(fallback_text, candidates=candidates,
                                          artifact_ids=artifact_ids),
            attempts, " ".join(failures), calls,
        )
    records = [json.loads(part.raw_text)["validations"] for part in parts]
    for index, item in enumerate(fallback["validations"]):
        judgments = [part[index] for part in records]
        item["observable"] = all(j["observable"] for j in judgments)
        item["nonredundant"] = all(j["nonredundant"] for j in judgments)
        item["artifact_applications"] = [
            j["artifact_applications"][0] for j in judgments
        ]
        item["reason"] = " ".join(dict.fromkeys(j["reason"] for j in judgments))
    text = canonical_json(fallback)
    return ValidationStageResult(
        text, validated_validation_response(text, candidates=candidates,
                                            artifact_ids=artifact_ids), attempts, calls=calls,
    )

src/rubric_gen/submission_revision/contr:
"""Build deterministic blinded artifact histories for criterion elicitation."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from rubric_gen.artifacts.hashing import sha256_text
from rubric_gen.benchmarks import SubmissionBenchmark
from rubric_gen.runtime.agents.models import AgentRunConfig
from rubric_gen.submission_revision.prompts import PromptProfile
from rubric_gen.submission_revision.evolution_artifacts import (
    ArtifactHistory,
    ArtifactPair,
    BlindedArtifact,
    RedTeamEvidence,
)
from rubric_gen.submission_revision.red_team import (
    load_red_team_artifact,
)
from rubric_gen.submission_revision.rubric_generation import RubricPolicy
from rubric_gen.submission_revision.seeds import resolve_seed


RED_TEAM_TRACE_EXCERPT_MAX_BYTES = 32 * 1024
ELICITATION_SEED_REPLICATES = 3
_TRACE_OMISSION = "\n<trajectory_middle_omitted />\n"


@dataclass(frozen=True)
class _Artifact:
    source_id: str
    text: str
    pair_keys: tuple[str, ...] = ()

    @property
    def sha256(self) -> str:
        return sha256_text(self.text)


def _sealed_seed_artifacts(
    *,
    seed_set: Path,
    task_dir: Path,
    benchmark: SubmissionBenchmark,
    seed_generator: AgentRunConfig,
    prompt_profile: PromptProfile | str,
    seed_replicates: int,
) -> tuple[_Artifact, ...]:
    if (
        type(seed_replicates) is not int
        or seed_replicates != ELICITATION_SEED_REPLICATES
    ):
        raise ValueError("elicitation requires exactly three seed replicates")
    ordinary: list[_Artifact] = []
    adversarial: list[_Artifact] = []
    for replicate in range(1, seed_replicates + 1):
        seed = resolve_seed(
            seed_set,
            task_dir,
            replicate,
            seed_generator=seed_generator,
            prompt_profile=prompt_profile,
            benchmark=benchmark.benchmark,
        )
        for role, workspace in seed.elicitation_artifacts:
            if role not in {"clean", "adversarial"}:
                raise RuntimeError("seed artifact has an invalid elicitation role")
            artifact = _Artifact(
                source_id=f"sealed-seed:rep-{replicate:03d}:{role}",
                text=benchmark.render_user_review(workspace),
            )
            (ordinary if role == "clean" else adversarial).append(artifact)
    if len(ordinary) != seed_replicates:
        raise RuntimeError("each seed replicate must supply one ordinary artifact")
    pair_keys = tuple(
        f"seed-bank-{index:03d}" for index in range(1, len(ordinary) + 1)
    )
    matched_ordinary = tuple(
        _Artifact(
            source_id=artifact.source_id,
            text=artifact.text,
            pair_keys=(pair_key,),
        )
        for artifact, pair_key in zip(ordinary, pair_keys, strict=True)
    )
    if not adversarial:
        return matched_ordinary
    shared_adversarial = adversarial[0]
    return (*matched_ordinary, _Artifact(
        source_id=shared_adversarial.source_id,
        text=shared_adversarial.text,
        pair_keys=pair_keys,
    ))


def _artifact_history(
    *,
    blinding_scope: str,
    artifacts: tuple[_Artifact, ...],
) -> ArtifactHistory:
    if type(blinding_scope) is not str or not blinding_scope.strip():
        raise ValueError("elicitation blinding scope must be nonempty")
    unique_by_hash: dict[str, _Artifact] = {}
    for artifact in artifacts:
        unique_by_hash.setdefault(artifact.sha256, artifact)
    blinded = tuple(sorted(
        (
            BlindedArtifact(
                artifact_id="artifact_" + sha256_text(
                    f"{blinding_scope}\0{digest}"
                )[:16],
                source_id=artifact.source_id,
                content_sha256=digest,
                content=artifact.text,
            )
            for digest, artifact in unique_by_hash.items()
        ),
        key=lambda item: item.artifact_id,
    ))
    artifact_id_by_hash = {
        item.content_sha256: item.artifact_id for item in blinded
    }
    pair_members: dict[str, list[str]] = {}
    for artifact in artifacts:
        artifact_id = artifact_id_by_hash[artifact.sha256]
        for pair_key in artifact.pair_keys:
            members = pair_members.setdefault(pair_key, [])
            if artifact_id not in members:
                members.append(artifact_id)
    pairs: list[ArtifactPair] = []
    for pair_key, members in pair_members.items():
        if len(members) == 1:
            continue
        if len(members) != 2:
            raise RuntimeError(f"matched pair has {len(members)} artifacts: {pair_key}")
        pairs.append(ArtifactPair.create(*members))
    unique_pairs = {pair.pair_id: pair for pair in pairs}
    return ArtifactHistory(
        artifacts=blinded,
        pairs=tuple(sorted(unique_pairs.values(), key=lambda item: item.artifact_ids)),
        red_team_evidence=(),
    )


def _trace_excerpt(path: Path) -> tuple[str, bool]:
    if path.is_symlink() or not path.is_file():
        raise RuntimeError("red-team trajectory is missing")
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise RuntimeError("red-team trajectory is invalid UTF-8") from exc
    if not text:
        raise RuntimeError("red-team trajectory is empty")
    raw = text.encode("utf-8")
    if len(raw) <= RED_TEAM_TRACE_EXCERPT_MAX_BYTES:
        return text, False
    marker = _TRACE_OMISSION.encode("utf-8")
    available = RED_TEAM_TRACE_EXCERPT_MAX_BYTES - len(marker)
    prefix = raw[: available // 2].decode("utf-8", errors="ignore")
    suffix = raw[-(available - available // 2):].decode(
        "utf-8",
        errors="ignore",
    )
    excerpt = prefix + _TRACE_OMISSION + suffix
    if len(excerpt.encode("utf-8")) > RED_TEAM_TRACE_EXCERPT_MAX_BYTES:
        raise AssertionError("red-team trajectory excerpt exceeds its byte limit")
    return excerpt, True


def build_offline_artifact_history(
    *,
    seed_set: Path,
    task_dir: Path,
    benchmark: SubmissionBenchmark,
    seed_generator: AgentRunConfig,
    prompt_profile: PromptProfile | str,
    seed_replicates: int,
    blinding_scope: str,
) -> ArtifactHistory:
    """Return matched sealed pre-treatment artifact pairs."""

    return _artifact_history(
        blinding_scope=blinding_scope,
        artifacts=_sealed_seed_artifacts(
            seed_set=seed_set,
            task_dir=task_dir,
            benchmark=benchmark,
            seed_generator=seed_generator,
            prompt_profile=prompt_profile,
            seed_replicates=seed_replicates,
        ),
    )


def build_online_artifact_history(
    *,
    seed_set: Path,
    task_dir: Path,
    experiment_dir: Path,
    benchmark: SubmissionBenchmark,
    seed_generator: AgentRunConfig,
    prompt_profile: PromptProfile | str,
    seed_replicates: int,
    blinding_scope: str,
    source_checkpoint: int,
    red_team_policy: RubricPolicy | None = None,
    red_team_generator_identity: dict[str, object] | None = None,
) -> ArtifactHistory:
    """Return matched seed, revision, and optional sidecar pairs."""

    if type(source_checkpoint) is not int or source_checkpoint < 1:
        raise ValueError("source_checkpoint must be a positive integer")
    submissions = experiment_dir / "submissions"
    if red_team_policy not in {
        None,
        RubricPolicy.RED_TEAM_ARTIFACT,
        RubricPolicy.RED_TEAM_TRACE,
    }:
        raise ValueError("online history has an invalid red-team policy")
    include_red_team = red_team_policy is not None
    if include_red_team != (red_team_generator_identity is not None):
        raise ValueError(
            "red-team identity is required exactly when sidecars are included"
        )
    live: list[_Artifact] = []
    red_team_sources: list[tuple[_Artifact, _Artifact, Path]] = []
    for index in range(source_checkpoint + 1):
        submission_id = f"s{index:03d}"
        workspace = submissions / submission_id / "workspace"
        if workspace.is_symlink() or not workspace.is_dir():
            raise RuntimeError(f"online elicitation source is missing: {submission_id}")
        pair_keys: list[str] = []
        if index > 0:
            pair_keys.append(f"revision-{index - 1:03d}-{index:03d}")
        if index < source_checkpoint:
            pair_keys.append(f"revision-{index:03d}-{index + 1:03d}")
        if (
            source_checkpoint > 1
            and index in {0, source_checkpoint}
        ):
            pair_keys.append(f"initial-current-{source_checkpoint:03d}")
        if include_red_team and index >= 1:
            pair_keys.append(f"red-team-{index:03d}")
        observed = _Artifact(
            source_id=f"live:{submission_id}",
            text=benchmark.render_user_review(workspace),
            pair_keys=tuple(pair_keys),
        )
        live.append(observed)
        if include_red_team and index >= 1:
            sidecar = load_red_team_artifact(
                experiment_dir,
                index,
                expected_generator=red_team_generator_identity,
                expected_source_artifact_sha256=sha256_text(
                    benchmark.render_user_review(workspace)
                ),
            )
            if sidecar.included:
                adversarial = _Artifact(
                    source_id=f"red-team:{submission_id}",
                    text=benchmark.render_user_review(sidecar.root / "workspace"),
                    pair_keys=(f"red-team-{index:03d}",),
                )
                live.append(adversarial)
                red_team_sources.append((
                    observed,
                    adversarial,
                    sidecar.root / "trajectory.stream.jsonl",
                ))
    seeds = _sealed_seed_artifacts(
        seed_set=seed_set,
        task_dir=task_dir,
        benchmark=benchmark,
        seed_generator=seed_generator,
        prompt_profile=prompt_profile,
        seed_replicates=seed_replicates,
    )
    history = _artifact_history(
        blinding_scope=blinding_scope,
        artifacts=(*seeds, *live),
    )
    artifact_id_by_hash = {
        item.content_sha256: item.artifact_id for item in history.artifacts
    }
    pair_ids = {item.pair_id for item in history.pairs}
    evidence: list[RedTeamEvidence] = []
    for observed, adversarial, trajectory_path in red_team_sources:
        if observed.sha256 == adversarial.sha256:
            continue
        pair = ArtifactPair.create(
            artifact_id_by_hash[observed.sha256],
            artifact_id_by_hash[adversarial.sha256],
        )
        if pair.pair_id not in pair_ids:
            raise RuntimeError("red-team evidence has no matched artifact pair")
        full_trajectory = trajectory_path.read_text(encoding="utf-8")
        excerpt, truncated = _trace_excerpt(trajectory_path)
        evidence.append(RedTeamEvidence(
            pair_id=pair.pair_id,
            observed_artifact_id=artifact_id_by_hash[observed.sha256],
            adversarial_artifact_id=artifact_id_by_hash[adversarial.sha256],
            trajectory_sha256=sha256_text(full_trajectory),
            trajectory_excerpt_sha256=sha256_text(excerpt),
            trajectory_excerpt=excerpt,
            trajectory_truncated=truncated,
        ))
    return ArtifactHistory(
        artifacts=history.artifacts,
        pairs=history.pairs,
        red_team_evidence=tuple(sorted(evidence, key=lambda item: item.pair_id)),
    )


def build_elicitation_artifact_history(
    *,
    online: bool,
    seed_set: Path,
    task_dir: Path,
    experiment_dir: Path,
    benchmark: SubmissionBenchmark,
    seed_generator: AgentRunConfig,
    prompt_profile: PromptProfile | str,
    seed_replicates: int,
    blinding_scope: str,
    source_checkpoint: int | None,
    red_team_policy: RubricPolicy | None = None,
    red_team_generator_identity: dict[str, object] | None = None,
) -> ArtifactHistory:
    """Route one policy to its matched blinded artifact history."""

    if type(online) is not bool:
        raise ValueError("online must be a boolean")
    arguments = {
        "seed_set": seed_set,
        "task_dir": task_dir,
        "benchmark": benchmark,
        "seed_generator": seed_generator,
        "prompt_profile": prompt_profile,
        "seed_replicates": seed_replicates,
        "blinding_scope": blinding_scope,
    }
    if online:
        if source_checkpoint is None:
            raise ValueError("online elicitation requires a source checkpoint")
        return build_online_artifact_history(
            experiment_dir=experiment_dir,
            source_checkpoint=source_checkpoint,
            red_team_policy=red_team_policy,
            red_team_generator_identity=red_team_generator_identity,
            **arguments,
        )
    if red_team_policy is not None or red_team_generator_identity is not None:
        raise ValueError("offline artifact history cannot include online sidecars")
    if source_checkpoint is not None:
        raise ValueError("pre-treatment elicitation cannot use a live checkpoint")
    return build_offline_artifact_history(**arguments)

