"""Input validation for one rubric-evolution generation."""

from __future__ import annotations

from rubric_gen.submission_revision.rubric_generation import (
    CompleteRubric,
    RubricGeneration,
    RubricPolicy,
    render_augmented_rubric,
)


def validate_evolution_request(
    *,
    instruction: str,
    original_rubric: CompleteRubric,
    development_rubric: CompleteRubric,
    current_generation: RubricGeneration,
    policy: RubricPolicy,
    generation_round: int,
    source_checkpoint: int | None,
) -> None:
    """Reject an invalid request before model dispatch or filesystem mutation."""

    if type(instruction) is not str or not instruction.strip():
        raise ValueError("task instruction must be nonempty")
    if not isinstance(original_rubric, CompleteRubric):
        raise ValueError("original_rubric must be a CompleteRubric")
    if not isinstance(development_rubric, CompleteRubric):
        raise ValueError("development_rubric must be a CompleteRubric")
    if development_rubric.content_sha256 == original_rubric.content_sha256:
        raise ValueError("development rubric must differ from the selected rubric")
    if not isinstance(current_generation, RubricGeneration):
        raise ValueError("current_generation must be a RubricGeneration")

    development_generation = RubricGeneration(
        generation_round=current_generation.generation_round,
        source_checkpoint=current_generation.source_checkpoint,
        rubric=render_augmented_rubric(
            development_rubric,
            current_generation.elicited_criteria,
        ),
        elicited_criteria=current_generation.elicited_criteria,
        proposer_call_budget=current_generation.proposer_call_budget,
    )
    if (
        development_generation.normalization_maximum
        != current_generation.normalization_maximum
        or development_generation.scoring_protocol
        != current_generation.scoring_protocol
    ):
        raise ValueError(
            "development and selected rubrics must use the same score scale"
        )

    if type(policy) is not RubricPolicy or policy not in {
        RubricPolicy.OFFLINE_ELICITATION,
        RubricPolicy.ONLINE_ELICITATION,
        RubricPolicy.RED_TEAM_ARTIFACT,
        RubricPolicy.RED_TEAM_TRACE,
    }:
        raise ValueError("criterion elicitation requires an elicitation policy")
    if type(generation_round) is not int:
        raise ValueError("generation_round must be an integer")
    if generation_round != current_generation.generation_round + 1:
        raise ValueError("rubric generations must be consecutive")
    if policy is RubricPolicy.OFFLINE_ELICITATION:
        if generation_round != 1:
            raise ValueError("offline elicitation has one pre-treatment generation")
        if source_checkpoint is not None:
            raise ValueError("offline elicitation cannot use a live checkpoint")
    elif generation_round == 1:
        if source_checkpoint is not None:
            raise ValueError(
                "the pre-treatment online rubric cannot use live evidence"
            )
    elif (
        type(source_checkpoint) is not int
        or source_checkpoint != generation_round - 1
    ):
        raise ValueError("online elicitation needs the preceding live checkpoint")

"""Structured provider interface for rubric evolution."""

from __future__ import annotations

import math
import os
from collections.abc import Callable
from dataclasses import dataclass
from numbers import Real

from rubric_gen.runtime.agents.costs import RunCost
from rubric_gen.submission_revision.evolution_serialization import (
    canonical_json,
)


PROPOSER_MAX_OUTPUT_TOKENS = 32_768
PROPOSER_MAX_REQUEST_BYTES = 1024 * 1024
_REQUEST_TIMEOUT_SECONDS = 300.0
_REASONING_EFFORT = "low"
_TEXT_VERBOSITY = "low"
_COST_KEYS = frozenset({"cost_usd", "estimated_cost_usd", "cost_source"})
_GENERATION_KEYS = frozenset({
    "provider",
    "requested_model",
    "effective_model",
    "response_id",
    "request_parameters",
    "usage",
})


@dataclass(frozen=True)
class StructuredProviderOutput:
    """Store one structured response and its provider metadata."""

    response_text: str
    cost: dict[str, float | str | None]
    generation: dict[str, object]


ProviderOperation = Callable[..., StructuredProviderOutput]


class RubricProposerProviderError(RuntimeError):
    """A proposer invocation failed without producing a usable provider response."""


@dataclass(frozen=True)
class ProviderContract:
    """Define and enforce one structured model-provider interface."""

    model: str
    max_output_tokens: int
    max_request_bytes: int
    service_tier: str | None

    def __post_init__(self) -> None:
        if type(self.model) is not str or not self.model.strip():
            raise ValueError("provider model must be nonempty")
        if type(self.max_output_tokens) is not int or self.max_output_tokens < 1:
            raise ValueError("provider output-token limit must be positive")
        if type(self.max_request_bytes) is not int or self.max_request_bytes < 1:
            raise ValueError("provider request-byte limit must be positive")
        if self.service_tier is not None and (
            type(self.service_tier) is not str or not self.service_tier.strip()
        ):
            raise ValueError("provider service tier must be nonempty")

    @property
    def provider(self) -> str:
        return "openai"

    def record(self) -> dict[str, object]:
        return {
            "provider": self.provider,
            "model": self.model,
            "reasoning_effort": _REASONING_EFFORT,
            "text_verbosity": _TEXT_VERBOSITY,
            "max_output_tokens": self.max_output_tokens,
            "max_request_bytes": self.max_request_bytes,
            "client_timeout_seconds": _REQUEST_TIMEOUT_SECONDS,
            "service_tier": self.service_tier,
        }

    def validate_output(self, output: StructuredProviderOutput) -> None:
        if not isinstance(output, StructuredProviderOutput):
            raise RuntimeError("provider returned the wrong output type")
        if type(output.response_text) is not str or not output.response_text.strip():
            raise RuntimeError("provider returned empty structured output")
        if not _valid_cost(output.cost) or not _valid_generation(output.generation):
            raise RuntimeError("provider returned invalid usage metadata")
        if (
            output.generation["provider"] != self.provider
            or output.generation["requested_model"] != self.model
            or output.generation["effective_model"] != self.model
        ):
            raise RuntimeError("provider response differs from its configured model")

    def generate(
        self,
        *,
        instructions: str,
        evidence: str,
        response_schema: dict[str, object],
        request_context: str,
        schema_name: str,
    ) -> StructuredProviderOutput:
        return generate_structured(
            model=self.model,
            service_tier=self.service_tier,
            instructions=instructions,
            evidence=evidence,
            response_schema=response_schema,
            max_output_tokens=self.max_output_tokens,
            max_request_bytes=self.max_request_bytes,
            request_context=request_context,
            schema_name=schema_name,
        )


def request_bytes(
    instructions: str,
    evidence: str,
    response_schema: dict[str, object],
) -> int:
    return len(
        (instructions + "\0" + evidence + "\0" + canonical_json(response_schema))
        .encode("utf-8")
    )


def _valid_cost(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != _COST_KEYS:
        return False
    for key in ("cost_usd", "estimated_cost_usd"):
        item = value[key]
        if item is not None and (
            isinstance(item, bool)
            or not isinstance(item, Real)
            or not math.isfinite(float(item))
            or float(item) < 0
        ):
            return False
    source = value["cost_source"]
    return (
        source is None
        and value["cost_usd"] is None
        and value["estimated_cost_usd"] is None
    ) or (type(source) is str and bool(source.strip()))


def _valid_generation(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != _GENERATION_KEYS:
        return False
    return (
        all(
            type(value[key]) is str and bool(value[key].strip())
            for key in (
                "provider", "requested_model", "effective_model", "response_id"
            )
        )
        and isinstance(value["request_parameters"], dict)
        and bool(value["request_parameters"])
        and (value["usage"] is None or isinstance(value["usage"], dict))
    )


def generate_structured(
    *,
    model: str,
    service_tier: str | None,
    instructions: str,
    evidence: str,
    response_schema: dict[str, object],
    max_output_tokens: int,
    max_request_bytes: int,
    request_context: str,
    schema_name: str,
) -> StructuredProviderOutput:
    size = request_bytes(instructions, evidence, response_schema)
    if size > max_request_bytes:
        raise ValueError(
            f"{request_context} request is {size} UTF-8 bytes; "
            f"limit is {max_request_bytes}"
        )
    from openai import OpenAI

    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError(f"OPENAI_API_KEY must be set for the {request_context}")
    arguments: dict[str, object] = {
        "model": model,
        "input": [
            {"role": "developer", "content": instructions},
            {"role": "user", "content": evidence},
        ],
        "max_output_tokens": max_output_tokens,
        "reasoning": {"effort": _REASONING_EFFORT},
        "text": {
            "verbosity": _TEXT_VERBOSITY,
            "format": {
                "type": "json_schema",
                "name": schema_name,
                "strict": True,
                "schema": response_schema,
            },
        },
        "truncation": "disabled",
        "store": False,
    }
    if service_tier is not None:
        arguments["service_tier"] = service_tier
    response = OpenAI(
        api_key=api_key,
        timeout=_REQUEST_TIMEOUT_SECONDS,
        max_retries=0,
    ).responses.create(**arguments)
    status = getattr(response, "status", None)
    if status == "incomplete":
        details = getattr(response, "incomplete_details", None)
        reason = getattr(details, "reason", None) or "unknown"
        raise RuntimeError(f"OpenAI returned an incomplete response: {reason}")
    if status not in {None, "completed"}:
        raise RuntimeError(f"OpenAI structured response failed with status {status}")
    text = response.output_text or ""
    if not text:
        raise RuntimeError("OpenAI returned an empty structured response")
    effective_model = getattr(response, "model", None)
    response_id = getattr(response, "id", None)
    if type(effective_model) is not str or not effective_model.strip():
        raise RuntimeError("OpenAI response has no effective model")
    if type(response_id) is not str or not response_id.strip():
        raise RuntimeError("OpenAI response has no response ID")
    usage = _jsonable(getattr(response, "usage", None))
    return StructuredProviderOutput(
        response_text=text,
        cost=_cost_from_usage(usage, model=model, service_tier=service_tier),
        generation={
            "provider": "openai",
            "requested_model": model,
            "effective_model": effective_model,
            "response_id": response_id,
            "request_parameters": {
                key: value for key, value in arguments.items()
                if key not in {"input", "model"}
            },
            "usage": usage,
        },
    )


def _cost_from_usage(
    usage: object,
    *,
    model: str,
    service_tier: str | None,
) -> dict[str, float | str | None]:
    if not isinstance(usage, dict):
        return RunCost().fields()
    input_tokens = usage.get("input_tokens", usage.get("prompt_tokens"))
    output_tokens = usage.get("output_tokens", usage.get("completion_tokens"))
    details = usage.get("input_tokens_details")
    cached = details.get("cached_tokens") if isinstance(details, dict) else 0
    return RunCost.from_event(
        {"usage": {
            "input_tokens": input_tokens,
            "output_tokens": output_tokens,
            "cached_input_tokens": cached or 0,
        }},
        model=model,
        service_tier=service_tier,
    ).fields()


def _jsonable(value: object) -> object:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(key): _jsonable(child) for key, child in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable(child) for child in value]
    model_dump = getattr(value, "model_dump", None)
    if callable(model_dump):
        return _jsonable(model_dump())
    return str(value)

