@dataclass(frozen=True)
class FullRubricRunSpec:
    """The complete non-secret contract for one full-rubric evaluation."""

    requested_model: str
    provider: str
    seed: int
    criterion_count: int
    rubric_bytes: int
    artifact_bytes: int
    payload_bytes: int
    schema_bytes: int
    request_content_bytes_per_call: int
    max_output_tokens_per_call: int

    def as_json(self) -> dict[str, object]:
        if self.provider == "openai" and self.requested_model.startswith("gpt-5.6"):
            reasoning_effort = "none"
        elif self.provider in {"anthropic", "google"}:
            reasoning_effort = "low"
        else:
            reasoning_effort = None
        provider_seed = self.seed if self.provider == "google" else None
        return {
            "requested_model": self.requested_model,
            "provider": self.provider,
            "engine_seed": self.seed,
            "provider_seed": provider_seed,
            "temperature": None if self.provider == "anthropic" else 0.0,
            "reasoning_effort": reasoning_effort,
            "criterion_count": self.criterion_count,
            "rubric_bytes": self.rubric_bytes,
            "artifact_bytes": self.artifact_bytes,
            "payload_bytes": self.payload_bytes,
            "schema_bytes": self.schema_bytes,
            "request_content_bytes_per_call": self.request_content_bytes_per_call,
            "total_request_content_bytes": (
                self.request_content_bytes_per_call
            ),
            "calls": 1,
            "max_output_tokens_per_call": self.max_output_tokens_per_call,
            "request_timeout_seconds": FULL_RUBRIC_REQUEST_TIMEOUT_SECONDS,
            "provider_retries": 0,
            "provider_storage": False if self.provider == "openai" else None,
            "repository_result_cache": False,
            "prompt_cache_control": "default",
            "limits": {
                "max_criteria": FULL_RUBRIC_MAX_CRITERIA,
                "max_request_content_bytes_per_call": (
                    FULL_RUBRIC_MAX_REQUEST_CONTENT_BYTES_PER_CALL
                ),
                "max_total_request_content_bytes": (
                    FULL_RUBRIC_MAX_TOTAL_REQUEST_CONTENT_BYTES
                ),
                "max_calls": 1,
                "max_output_tokens_per_call": FULL_RUBRIC_MAX_OUTPUT_TOKENS,
            },
            "authoritative_score": "single-judgment-signed-points",
            "system_prompt_sha256": hashlib.sha256(
                FULL_RUBRIC_SYSTEM_PROMPT.encode("utf-8")
            ).hexdigest(),
        }

    @classmethod
    def from_json(cls, value: object) -> "FullRubricRunSpec":
        """Load only the exact current execution record."""

        if type(value) is not dict:
            raise FullRubricJudgeError("FullRubric execution record must be an object")
        scalar_fields = {
            "requested_model": str,
            "provider": str,
            "engine_seed": int,
            "criterion_count": int,
            "rubric_bytes": int,
            "artifact_bytes": int,
            "payload_bytes": int,
            "schema_bytes": int,
            "request_content_bytes_per_call": int,
            "max_output_tokens_per_call": int,
        }
        for name, expected_type in scalar_fields.items():
            if type(value.get(name)) is not expected_type:
                raise FullRubricJudgeError(
                    f"FullRubric execution field {name} has an invalid type"
                )
        spec = cls(
            requested_model=value["requested_model"],
            provider=value["provider"],
            seed=value["engine_seed"],
            criterion_count=value["criterion_count"],
            rubric_bytes=value["rubric_bytes"],
            artifact_bytes=value["artifact_bytes"],
            payload_bytes=value["payload_bytes"],
            schema_bytes=value["schema_bytes"],
            request_content_bytes_per_call=value[
                "request_content_bytes_per_call"
            ],
            max_output_tokens_per_call=value["max_output_tokens_per_call"],
        )
        if not spec.requested_model.strip():
            raise FullRubricJudgeError("FullRubric requested model is empty")
        if not 0 <= spec.seed < 2**31:
            raise FullRubricJudgeError("FullRubric engine seed is out of range")
        if not 1 <= spec.criterion_count <= FULL_RUBRIC_MAX_CRITERIA:
            raise FullRubricJudgeError("FullRubric criterion count is out of range")
        if spec.rubric_bytes < 1 or spec.artifact_bytes < 1:
            raise FullRubricJudgeError("FullRubric input byte counts are invalid")
        if spec.payload_bytes < 1 or spec.schema_bytes < 1:
            raise FullRubricJudgeError(
                "FullRubric payload or schema byte count is invalid"
            )
        if not (
            1
            <= spec.request_content_bytes_per_call
            <= FULL_RUBRIC_MAX_REQUEST_CONTENT_BYTES_PER_CALL
        ):
            raise FullRubricJudgeError(
                "FullRubric request content byte count is out of range"
            )
        expected_output_tokens = min(
            FULL_RUBRIC_MAX_OUTPUT_TOKENS,
            max(
                FULL_RUBRIC_MIN_OUTPUT_TOKENS,
                spec.criterion_count * FULL_RUBRIC_OUTPUT_TOKENS_PER_CRITERION,
            ),
        )
        if spec.max_output_tokens_per_call != expected_output_tokens:
            raise FullRubricJudgeError("FullRubric output token limit changed")
        if spec.as_json() != value:
            raise FullRubricJudgeError("FullRubric execution record is not exact")
        provider, _model = provider_and_model(spec.requested_model)
        if provider != spec.provider:
            raise FullRubricJudgeError("FullRubric execution provider changed")
        return spec


@dataclass(frozen=True)
class FullRubricGeneration:
    text: str
    provider: str
    requested_model: str
    effective_model: str
    response_id: str | None
    request_parameters: dict[str, object]
    usage: object

    def usage_record(self) -> dict[str, object]:
        return {
            "provider": self.provider,
            "requested_model": self.requested_model,
            "effective_model": self.effective_model,
            "response_id": self.response_id,
            "request_parameters": self.request_parameters,
            "raw_usage": _jsonable(self.usage),
        }


def _jsonable(value: object) -> object:
    if value is None or isinstance(value, (str, int, bool)):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise FullRubricJudgeError("provider usage contains a non-finite number")
        return value
    if isinstance(value, dict):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable(item) for item in value]
    model_dump = getattr(value, "model_dump", None)
    if callable(model_dump):
        return _jsonable(model_dump())
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        return _jsonable(to_dict())
    return str(value)


@dataclass(frozen=True)
class FullRubricArtifactRecords:
    reward: dict[str, float]
    evaluation: dict[str, object]
    usage: dict[str, object]
    score: float
    normalized_score: float
    raw_score: float
    criterion_levels: dict[str, str]
    criterion_scores: dict[str, float]


def full_rubric_payload(rubric_text: str, review_text: str, answer_text: str) -> str:
    """Encode every variable prompt field as inert JSON data."""

    if any(type(value) is not str for value in (rubric_text, review_text, answer_text)):
        raise TypeError("FullRubric judge inputs must be text")
    return json.dumps(
        {
            "rubric_text": rubric_text,
            "artifact_evidence": {
                "workspace_review": review_text,
                "final_answer": answer_text if answer_text else None,
            },
        },
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
    )


def full_rubric_cost_shape(
    rubric_text: str,
    *,
    review_text: str,
    answer_text: str,
) -> FullRubricCostShape:
    """Bound canonical prompt, payload, and schema bytes without provider access.

    The byte count excludes the provider SDK envelope and transport headers.
    """

    levels = parse_rubric_levels_strict(rubric_text)
    criterion_count = len(levels)
    if criterion_count > FULL_RUBRIC_MAX_CRITERIA:
        raise FullRubricJudgeError(
            f"FullRubric rubric has {criterion_count} criteria; the fixed limit is "
            f"{FULL_RUBRIC_MAX_CRITERIA}"
        )
    payload = full_rubric_payload(rubric_text, review_text, answer_text)
    payload_bytes = len(payload.encode("utf-8"))
    schema = structured_output_schema(levels)
    schema_bytes = len(
        json.dumps(
            schema,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    )
    request_content_bytes = (
        len(FULL_RUBRIC_SYSTEM_PROMPT.encode("utf-8"))
        + payload_bytes
        + schema_bytes
    )
    total_request_content_bytes = request_content_bytes
    if request_content_bytes > FULL_RUBRIC_MAX_REQUEST_CONTENT_BYTES_PER_CALL:
        raise FullRubricJudgeError(
            f"FullRubric request content is {request_content_bytes} bytes; the "
            f"per-call limit is {FULL_RUBRIC_MAX_REQUEST_CONTENT_BYTES_PER_CALL}"
        )
    if total_request_content_bytes > FULL_RUBRIC_MAX_TOTAL_REQUEST_CONTENT_BYTES:
        raise FullRubricJudgeError(
            "FullRubric request content totals "
            f"{total_request_content_bytes} bytes; the limit is "
            f"{FULL_RUBRIC_MAX_TOTAL_REQUEST_CONTENT_BYTES}"
        )
    max_output_tokens = min(
        FULL_RUBRIC_MAX_OUTPUT_TOKENS,
        max(
            FULL_RUBRIC_MIN_OUTPUT_TOKENS,
            criterion_count * FULL_RUBRIC_OUTPUT_TOKENS_PER_CRITERION,
        ),
    )
    artifact_bytes = len(
        json.dumps(
            {
                "workspace_review": review_text,
                "final_answer": answer_text if answer_text else None,
            },
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
        ).encode("utf-8")
    )
    return FullRubricCostShape(
        criterion_count=criterion_count,
        rubric_bytes=len(rubric_text.encode("utf-8")),
        artifact_bytes=artifact_bytes,
        payload_bytes=payload_bytes,
        schema_bytes=schema_bytes,
        request_content_bytes_per_call=request_content_bytes,
        calls=1,
        total_request_content_bytes=total_request_content_bytes,
        max_output_tokens_per_call=max_output_tokens,
        total_output_tokens=max_output_tokens,
    )


def preflight_full_rubric_generation(
    rubric_text: str,
    *,
    review_text: str,
    answer_text: str,
) -> dict[str, object]:
    """Validate one complete FullRubric generation without provider access."""

    shape = full_rubric_cost_shape(
        rubric_text,
        review_text=review_text,
        answer_text=answer_text,
    )
    return {
        "rubric": shape.as_json(),
        "calls": shape.calls,
        "total_request_content_bytes": shape.total_request_content_bytes,
        "total_output_tokens": shape.total_output_tokens,
        "limits": {
            "max_criteria_per_rubric": FULL_RUBRIC_MAX_CRITERIA,
            "max_request_content_bytes_per_call": (
                FULL_RUBRIC_MAX_REQUEST_CONTENT_BYTES_PER_CALL
            ),
            "max_total_request_content_bytes_per_rubric": (
                FULL_RUBRIC_MAX_TOTAL_REQUEST_CONTENT_BYTES
            ),
            "max_output_tokens_per_call": FULL_RUBRIC_MAX_OUTPUT_TOKENS,
        },
    }


def build_full_rubric_run_spec(
    *,
    rubric_text: str,
    review_text: str,
    answer_text: str,
    requested_model: str,
    seed: int,
) -> FullRubricRunSpec:
    """Validate all call, input, and output limits before provider dispatch."""

    if type(seed) is not int or isinstance(seed, bool) or not 0 <= seed < 2**31:
        raise FullRubricJudgeError("FullRubric engine seed must be a 31-bit integer")
    shape = full_rubric_cost_shape(
        rubric_text,
        review_text=review_text,
        answer_text=answer_text,
    )
    provider, _litellm_model = provider_and_model(requested_model)
    if provider == "openai" and (
        requested_model.startswith(("o1", "o3", "o4"))
        or (
            requested_model.startswith("gpt-5")
            and not requested_model.startswith("gpt-5.6")
        )
    ):
        raise FullRubricJudgeError(
            "the FullRubric engine supports only GPT-5.6 among OpenAI reasoning "
            "models because its request contract includes temperature zero"
        )
    return FullRubricRunSpec(
        requested_model=requested_model,
        provider=provider,
        seed=seed,
        criterion_count=shape.criterion_count,
        rubric_bytes=shape.rubric_bytes,
        artifact_bytes=shape.artifact_bytes,
        payload_bytes=shape.payload_bytes,
        schema_bytes=shape.schema_bytes,
        request_content_bytes_per_call=shape.request_content_bytes_per_call,
        max_output_tokens_per_call=shape.max_output_tokens_per_call,
    )


def structured_output_schema(
    rubric_levels: dict[str, dict[str, int]],
) -> dict[str, object]:
    """Build one strict schema that requires every rubric criterion."""

    criterion_properties = {}
    for criterion_id, levels in rubric_levels.items():
        criterion_properties[criterion_id] = {
            "type": "object",
            "properties": {
                "level": {"type": "string", "enum": list(levels)},
                "reason": {"type": "string"},
            },
            "required": ["level", "reason"],
            "additionalProperties": False,
        }
    return {
        "type": "object",
        "properties": {
            "criteria": {
                "type": "object",
                "properties": criterion_properties,
                "required": list(rubric_levels),
                "additionalProperties": False,
            },
            "overall_reasoning": {"type": "string"},
        },
        "required": ["criteria", "overall_reasoning"],
        "additionalProperties": False,
    }


def parse_structured_output(
    text: str,
    rubric_levels: dict[str, dict[str, int]],
) -> dict[str, object]:
    """Parse one complete response. Reject wrappers, omissions, and extra fields."""

    if type(text) is not str or not text.strip():
        raise FullRubricJudgeError("FullRubric judge returned no structured output")
    try:
        value = json.loads(text)
    except json.JSONDecodeError as exc:
        raise FullRubricJudgeError("FullRubric judge output is not exact JSON") from exc
    if type(value) is not dict or set(value) != {"criteria", "overall_reasoning"}:
        raise FullRubricJudgeError("FullRubric judge output has invalid top-level keys")
    criteria = value["criteria"]
    if type(criteria) is not dict or set(criteria) != set(rubric_levels):
        raise FullRubricJudgeError(
            "FullRubric judge criterion keys do not exactly match the rubric"
        )
    for criterion_id, allowed in rubric_levels.items():
        result = criteria[criterion_id]
        if type(result) is not dict or set(result) != {"level", "reason"}:
            raise FullRubricJudgeError(
                f"FullRubric result for {criterion_id} has invalid keys"
            )
        if type(result["level"]) is not str or result["level"] not in allowed:
            raise FullRubricJudgeError(
                f"FullRubric result for {criterion_id} has an invalid level"
            )
        if type(result["reason"]) is not str or not result["reason"].strip():
            raise FullRubricJudgeError(
                f"FullRubric result for {criterion_id} has an empty reason"
            )
    if (
        type(value["overall_reasoning"]) is not str
        or not value["overall_reasoning"].strip()
    ):
        raise FullRubricJudgeError("FullRubric overall reasoning must be nonempty")
    return value


def _score_selection(
    rubric_levels: dict[str, dict[str, int]],
    selection: dict[str, object],
    normalization_maximum: int | None,
) -> tuple[float, int, dict[str, str], dict[str, int]]:
    raw_criteria = selection["criteria"]
    assert type(raw_criteria) is dict
    selected_levels = {
        criterion_id: raw_criteria[criterion_id]["level"]
        for criterion_id in rubric_levels
    }
    criterion_scores = {
        criterion_id: rubric_levels[criterion_id][level]
        for criterion_id, level in selected_levels.items()
    }
    raw_score = sum(criterion_scores.values())
    score = raw_score * 100 / (normalization_maximum or 100)
    return (
        max(0.0, min(100.0, score)),
        raw_score,
        selected_levels,
        criterion_scores,
    )


def records_from_report(
    *,
    rubric_text: str,
    raw_report: object,
    spec: FullRubricRunSpec,
    call_usage: object,
) -> FullRubricArtifactRecords:
    """Validate one report and compute its signed-point score."""

    rubric_levels = parse_rubric_levels_strict(rubric_text)
    if len(rubric_levels) != spec.criterion_count:
        raise FullRubricJudgeError("FullRubric rubric criterion count changed")
    if len(rubric_text.encode("utf-8")) != spec.rubric_bytes:
        raise FullRubricJudgeError("FullRubric rubric byte count changed")
    normalization_maximum = parse_score_normalization_maximum(rubric_text)
    report = parse_structured_output(
        json.dumps(raw_report, ensure_ascii=False, allow_nan=False),
        rubric_levels,
    )
    score, raw_score, criterion_levels, criterion_scores = _score_selection(
        rubric_levels,
        report,
        normalization_maximum,
    )
    evaluation_criteria: dict[str, object] = {}
    for criterion_id in rubric_levels:
        evaluation_criteria[criterion_id] = {
            "level": criterion_levels[criterion_id],
            "points": criterion_scores[criterion_id],
            "reason": report["criteria"][criterion_id]["reason"],
        }
    normalized_score = score / 100
    execution = spec.as_json()
    evaluation = {
        "total_score": score,
        "criteria": evaluation_criteria,
        "reasoning": report["overall_reasoning"],
        "full_rubric_structured": {
            "code_identity": dict(FULL_RUBRIC_ENGINE_IDENTITY),
            "execution": execution,
            "raw_report": report,
        },
    }
    usage = {
        "code_identity": dict(FULL_RUBRIC_ENGINE_IDENTITY),
        "execution": execution,
        "call": call_usage,
    }
    return FullRubricArtifactRecords(
        reward={"score": score},
        evaluation=evaluation,
        usage=usage,
        score=score,
        normalized_score=normalized_score,
        raw_score=raw_score,
        criterion_levels=criterion_levels,
        criterion_scores=criterion_scores,
    )


def validate_usage_record(value: object, spec: FullRubricRunSpec) -> None:
    """Validate complete per-call provenance without inventing provider cost data."""

    if type(value) is not dict or set(value) != {"code_identity", "execution", "call"}:
        raise FullRubricJudgeError("FullRubric usage record has invalid keys")
    if value["code_identity"] != FULL_RUBRIC_ENGINE_IDENTITY:
        raise FullRubricJudgeError("FullRubric usage engine identity changed")
    if value["execution"] != spec.as_json():
        raise FullRubricJudgeError("FullRubric usage execution contract changed")
    call = value["call"]
    if type(call) is not dict or set(call) != {
            "provider",
            "requested_model",
            "effective_model",
            "response_id",
            "request_parameters",
            "raw_usage",
        }:
        raise FullRubricJudgeError("FullRubric usage call is invalid")
    if call["provider"] != spec.provider:
        raise FullRubricJudgeError("FullRubric usage provider changed")
    if call["requested_model"] != spec.requested_model:
        raise FullRubricJudgeError("FullRubric usage model changed")
    if type(call["effective_model"]) is not str or not call["effective_model"]:
        raise FullRubricJudgeError("FullRubric usage has no effective model")
    if call["response_id"] is not None and type(call["response_id"]) is not str:
        raise FullRubricJudgeError("FullRubric usage has an invalid response ID")
    if call["request_parameters"] != request_parameters(spec):
        raise FullRubricJudgeError("FullRubric usage request contract changed")


def request_parameters(spec: FullRubricRunSpec) -> dict[str, object]:
    execution = spec.as_json()
    return {
            "temperature": execution["temperature"],
            "provider_seed": execution["provider_seed"],
            "reasoning_effort": execution["reasoning_effort"],
            "provider_storage": execution["provider_storage"],
            "prompt_cache_control": execution["prompt_cache_control"],
            "max_output_tokens": spec.max_output_tokens_per_call,
            "timeout_seconds": FULL_RUBRIC_REQUEST_TIMEOUT_SECONDS,
            "provider_retries": 0,
            "structured_output": "json_schema",
        }

src/rubric_gen/submission_revision/rubri:
"""Deterministic, race-aware snapshots of immutable benchmark task inputs."""

from __future__ import annotations

import codecs
import csv
import hashlib
import heapq
import io
import os
import re
import stat
from dataclasses import replace
from itertools import islice
from pathlib import Path

from rubric_gen.submission_revision.rubrics.schema import (
    DataFileSnapshot,
    SchemaSnapshotLimits,
    TaskAnchor,
    TaskSnapshot,
    _ImmutableFileSnapshot,
    canonical_json,
    sha256_text,
)


def _snapshot_payload(snapshot: TaskSnapshot) -> dict[str, object]:
    payload = snapshot.to_dict()
    payload.pop("snapshot_sha256")
    return payload


def _stable_file_signature(
    file_stat: os.stat_result,
) -> tuple[int, int, int, int, int | None]:
    return (
        file_stat.st_dev,
        file_stat.st_ino,
        file_stat.st_size,
        file_stat.st_mtime_ns,
        getattr(file_stat, "st_ctime_ns", None),
    )


def _snapshot_immutable_file(
    path: Path,
    *,
    capture_bytes: int | None,
    context: str,
) -> _ImmutableFileSnapshot:
    """Hash and capture one stable regular file through a single descriptor."""

    if capture_bytes is not None and capture_bytes < 0:
        raise ValueError("capture_bytes must be non-negative or None")
    if _first_symlink_component(path) is not None:
        raise ValueError(f"{context} must be a regular, non-symlink file")
    try:
        before_path = path.lstat()
    except (FileNotFoundError, NotADirectoryError) as exc:
        raise ValueError(f"{context} must be a regular, non-symlink file") from exc
    if not stat.S_ISREG(before_path.st_mode):
        raise ValueError(f"{context} must be a regular, non-symlink file")

    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(path, flags)
    except OSError as exc:
        raise ValueError(f"{context} must be a regular, non-symlink file") from exc

    digest = hashlib.sha256()
    captured = bytearray()
    bytes_seen = 0
    try:
        before_fd = os.fstat(fd)
        if not stat.S_ISREG(before_fd.st_mode) or _stable_file_signature(
            before_fd
        ) != _stable_file_signature(before_path):
            raise ValueError(f"{context} changed while being snapshotted")

        while True:
            chunk = os.read(fd, 65_536)
            if not chunk:
                break
            bytes_seen += len(chunk)
            digest.update(chunk)
            if capture_bytes is None:
                captured.extend(chunk)
            elif len(captured) < capture_bytes:
                remaining = capture_bytes - len(captured)
                captured.extend(chunk[:remaining])

        after_fd = os.fstat(fd)
        try:
            after_path = path.lstat()
        except (FileNotFoundError, NotADirectoryError) as exc:
            raise ValueError(f"{context} changed while being snapshotted") from exc
        if (
            _first_symlink_component(path) is not None
            or not stat.S_ISREG(after_path.st_mode)
            or _stable_file_signature(before_fd) != _stable_file_signature(after_fd)
            or _stable_file_signature(after_fd) != _stable_file_signature(after_path)
            or bytes_seen != after_fd.st_size
        ):
            raise ValueError(f"{context} changed while being snapshotted")
    finally:
        os.close(fd)

    return _ImmutableFileSnapshot(
        size_bytes=after_fd.st_size,
        sha256=digest.hexdigest(),
        captured_bytes=bytes(captured),
    )


def _absolute_without_resolving(path: Path) -> Path:
    return Path(os.path.abspath(os.fspath(path)))


def _first_symlink_component(path: Path) -> Path | None:
    absolute = _absolute_without_resolving(path)
    current = Path(absolute.anchor)
    for part in absolute.parts[1:]:
        current /= part
        try:
            mode = current.lstat().st_mode
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISLNK(mode):
            return current
    return None


def _validated_task_root(task_dir: Path) -> Path:
    task_root = _absolute_without_resolving(task_dir)
    symlink = _first_symlink_component(task_root)
    if symlink is not None:
        raise ValueError(f"task directory has a symlinked path component: {symlink}")
    try:
        mode = task_root.lstat().st_mode
    except (FileNotFoundError, NotADirectoryError) as exc:
        raise ValueError(f"task directory does not exist: {task_root}") from exc
    if not stat.S_ISDIR(mode):
        raise ValueError(f"task directory must be a directory: {task_root}")
    return task_root


def _validated_task_input(
    task_root: Path,
    relative_path: str,
    *,
    required: bool,
) -> Path | None:
    path = task_root / relative_path
    symlink = _first_symlink_component(path)
    if symlink is not None:
        if symlink == path:
            raise ValueError(f"{relative_path} must be a regular, non-symlink file")
        raise ValueError(f"{relative_path} has a symlinked path component: {symlink}")
    try:
        mode = path.lstat().st_mode
    except (FileNotFoundError, NotADirectoryError) as exc:
        if not required:
            return None
        raise ValueError(
            f"{relative_path} must be a regular, non-symlink file"
        ) from exc
    if not stat.S_ISREG(mode):
        raise ValueError(f"{relative_path} must be a regular, non-symlink file")
    try:
        path.resolve(strict=True).relative_to(task_root.resolve(strict=True))
    except (FileNotFoundError, ValueError) as exc:
        raise ValueError(
            f"{relative_path} must be contained under the task directory"
        ) from exc
    return path


def _validated_data_root(task_root: Path) -> Path:
    data_root = task_root / "environment" / "data"
    symlink = _first_symlink_component(data_root)
    if symlink is not None:
        raise ValueError(f"environment/data has a symlinked path component: {symlink}")
    return data_root


def _infer_column_type(values: list[str]) -> str:
    nonempty = [value for value in values if value != ""]
    if not nonempty:
        return "empty"
    lowered = [value.lower() for value in nonempty]
    if all(value in {"true", "false", "yes", "no"} for value in lowered):
        return "boolean"
    try:
        for value in nonempty:
            int(value)
        return "integer"
    except ValueError:
        pass
    try:
        for value in nonempty:
            float(value)
        return "number"
    except ValueError:
        return "string"


def _table_snapshot(
    relative_path: str,
    limits: SchemaSnapshotLimits,
    *,
    file_snapshot: _ImmutableFileSnapshot,
) -> DataFileSnapshot:
    probe = file_snapshot.captured_bytes
    probe_truncated = len(probe) > limits.max_probe_bytes
    probe = probe[: limits.max_probe_bytes]
    common = {
        "path": relative_path,
        "size_bytes": file_snapshot.size_bytes,
        "sha256": file_snapshot.sha256,
        "probe_bytes": len(probe),
        "probe_truncated": probe_truncated,
    }
    try:
        decoder = codecs.getincrementaldecoder("utf-8")()
        text = decoder.decode(probe, final=not probe_truncated)
    except UnicodeDecodeError:
        return DataFileSnapshot(kind="binary", **common)

    header_line = text.splitlines()[0] if text.splitlines() else ""
    delimiter = next(
        (candidate for candidate in ("\t", ",", ";", "|") if candidate in header_line),
        None,
    )
    if delimiter is None:
        return DataFileSnapshot(kind="text", **common)

    parsed_rows = list(csv.reader(io.StringIO(text, newline=""), delimiter=delimiter))
    if not parsed_rows:
        return DataFileSnapshot(kind="text", **common)
    raw_columns = parsed_rows[0]
    rows = parsed_rows[1:]
    kept_columns = [
        column[: limits.max_string_chars]
        for column in raw_columns[: limits.max_columns]
    ]
    inspected_rows = rows[: limits.max_rows]
    column_values = [
        [row[index] if index < len(row) else "" for row in inspected_rows]
        for index in range(len(kept_columns))
    ]
    examples: list[tuple[str, ...]] = []
    omitted_examples = 0
    for values in column_values:
        unique_values: list[str] = []
        for value in values:
            value = value[: limits.max_string_chars]
            if value not in unique_values:
                unique_values.append(value)
        examples.append(tuple(unique_values[: limits.max_examples_per_column]))
        omitted_examples += max(0, len(unique_values) - limits.max_examples_per_column)
    return DataFileSnapshot(
        kind="table",
        delimiter=delimiter,
        rows_seen=len(rows),
        columns=tuple(kept_columns),
        column_types=tuple(_infer_column_type(values) for values in column_values),
        examples=tuple(examples),
        omitted_rows=max(0, len(rows) - limits.max_rows),
        omitted_columns=max(0, len(raw_columns) - limits.max_columns),
        omitted_examples=omitted_examples,
        **common,
    )


def _walk_data_file_inventory(
    data_root: Path,
    limits: SchemaSnapshotLimits,
) -> tuple[tuple[Path, ...], bool]:
    if not data_root.is_dir():
        return (), False
    pending = [("", data_root)]
    files: list[Path] = []
    entries_enumerated = 0
    traversal_truncated = False
    while pending:
        _, path = heapq.heappop(pending)
        if path.is_symlink():
            relative = (
                "." if path == data_root else path.relative_to(data_root).as_posix()
            )
            raise ValueError(f"environment/data contains a symlink entry: {relative}")
        if path.is_dir():
            remaining = limits.max_entries_visited - entries_enumerated
            if remaining == 0:
                if next(path.iterdir(), None) is not None:
                    traversal_truncated = True
                continue
            children = list(islice(path.iterdir(), remaining + 1))
            if len(children) > remaining:
                entries_enumerated = limits.max_entries_visited
                traversal_truncated = True
                continue
            for child in children:
                if child.is_symlink():
                    relative = child.relative_to(data_root).as_posix()
                    raise ValueError(
                        f"environment/data contains a symlink entry: {relative}"
                    )
            entries_enumerated += len(children)
            for child in sorted(
                children,
                key=lambda item: item.relative_to(data_root).as_posix(),
            ):
                relative = child.relative_to(data_root).as_posix()
                heapq.heappush(pending, (relative, child))
        elif path.is_file():
            files.append(path)
    return tuple(files), traversal_truncated


def _walk_data_files(
    data_root: Path,
    limits: SchemaSnapshotLimits,
) -> tuple[tuple[Path, ...], int, bool]:
    """Return the bounded schema-preview paths and their omission metadata."""

    inventory, traversal_truncated = _walk_data_file_inventory(data_root, limits)
    preview = inventory[: limits.max_files]
    return (
        preview,
        len(inventory) - len(preview),
        traversal_truncated,
    )


def _schema_json(data_files: list[DataFileSnapshot]) -> str:
    return canonical_json([data_file.to_dict() for data_file in data_files])


def _fit_schema_budget(
    data_files: tuple[DataFileSnapshot, ...],
    max_output_chars: int,
) -> tuple[tuple[DataFileSnapshot, ...], int]:
    if max_output_chars < len("[]"):
        raise ValueError("max_output_chars must be at least 2")
    fitted = list(data_files)
    while len(_schema_json(fitted)) > max_output_chars:
        changed = False
        for file_index in range(len(fitted) - 1, -1, -1):
            data_file = fitted[file_index]
            for column_index in range(len(data_file.examples) - 1, -1, -1):
                values = data_file.examples[column_index]
                if not values:
                    continue
                examples = list(data_file.examples)
                examples[column_index] = values[:-1]
                fitted[file_index] = replace(
                    data_file,
                    examples=tuple(examples),
                    omitted_examples=data_file.omitted_examples + 1,
                )
                changed = True
                break
            if changed:
                break
        if not changed:
            break

    while len(_schema_json(fitted)) > max_output_chars:
        changed = False
        for file_index in range(len(fitted) - 1, -1, -1):
            data_file = fitted[file_index]
            if not data_file.columns:
                continue
            fitted[file_index] = replace(
                data_file,
                columns=data_file.columns[:-1],
                column_types=data_file.column_types[:-1],
                examples=data_file.examples[:-1],
                omitted_columns=data_file.omitted_columns + 1,
            )
            changed = True
            break
        if not changed:
            break

    omitted_files = 0
    while fitted and len(_schema_json(fitted)) > max_output_chars:
        fitted.pop()
        omitted_files += 1
    return tuple(fitted), omitted_files


def _extract_markdown_section(text: str, heading: str) -> str:
    match = re.search(rf"^##\s+{re.escape(heading)}\s*$", text, flags=re.MULTILINE)
    if match is None:
        return ""
    next_heading = re.search(r"^##\s+", text[match.end() :], flags=re.MULTILINE)
    end = match.end() + next_heading.start() if next_heading else len(text)
    return text[match.end() : end].strip()


def _extract_required_outputs(instruction: str) -> tuple[str, ...]:
    section = _extract_markdown_section(instruction, "Required Outputs")
    candidates = re.findall(
        r"(?:/app/)?[A-Za-z0-9_.-]+\.[A-Za-z0-9]{1,8}",
        section,
    )
    runtime_outputs = {"answer.txt", "trace.md"}
    outputs: list[str] = []
    for candidate in candidates:
        name = Path(candidate).name
        if name not in runtime_outputs and name not in outputs:
            outputs.append(name)
    return tuple(outputs)


def _summary_anchors(rubric: str) -> tuple[TaskAnchor, ...]:
    matches = list(
        re.finditer(r"^Criterion\s+(\d+)\s*:\s*(.+?)\s*$", rubric, re.MULTILINE)
    )
    anchors: list[TaskAnchor] = []
    for index, match in enumerate(matches):
        end = matches[index + 1].start() if index + 1 < len(matches) else len(rubric)
        block = rubric[match.start() : end].strip()
        anchors.append(
            TaskAnchor(
                anchor_id=f"summary:C{int(match.group(1))}",
                kind="summary-criterion",
                text=block,
                source="tests/rubric.txt",
            )
        )
    return tuple(anchors)


def _task_anchors(
    question: str,
    required_outputs: tuple[str, ...],
    summary_anchors: tuple[TaskAnchor, ...],
    data_files: tuple[DataFileSnapshot, ...],
) -> tuple[TaskAnchor, ...]:
    anchors = [TaskAnchor("task:question", "question", question, "instruction.md")]
    anchors.extend(
        TaskAnchor(
            f"task:required-output:{name}",
            "required-output",
            name,
            "instruction.md",
        )
        for name in required_outputs
    )
    anchors.extend(summary_anchors)
    for data_file in data_files:
        source = f"environment/data/{data_file.path}"
        anchors.append(
            TaskAnchor(
                f"data:{data_file.path}",
                "data-file",
                data_file.path,
                source,
            )
        )
        anchors.extend(
            TaskAnchor(
                f"schema:{data_file.path}#{column}",
                "schema-column",
                f"{column}: {column_type}",
                source,
            )
            for column, column_type in zip(data_file.columns, data_file.column_types)
        )
    anchors.extend(
        TaskAnchor(anchor_id, "evidence", text, "evidence-schema")
        for anchor_id, text in (
            ("evidence:events", "tool and lifecycle events"),
            ("evidence:commands", "executed commands"),
            ("evidence:file-reads", "file-read events"),
            ("evidence:file-writes", "file-write events"),
            ("evidence:artifacts", "produced artifacts"),
            ("evidence:final-claims", "claims in the final response"),
        )
    )
    return tuple(anchors)


def build_task_snapshot(
    task_dir: Path,
    limits: SchemaSnapshotLimits = SchemaSnapshotLimits(),
) -> TaskSnapshot:
    """Build a deterministic snapshot without consulting runtime files."""

    task_root = _validated_task_root(task_dir)
    instruction_path = _validated_task_input(
        task_root,
        "instruction.md",
        required=True,
    )
    rubric_path = _validated_task_input(
        task_root,
        "tests/rubric.txt",
        required=True,
    )
    task_config_path = _validated_task_input(
        task_root,
        "task.toml",
        required=False,
    )
    assert instruction_path is not None
    assert rubric_path is not None
    instruction_file = _snapshot_immutable_file(
        instruction_path,
        capture_bytes=None,
        context="instruction.md",
    )
    rubric_file = _snapshot_immutable_file(
        rubric_path,
        capture_bytes=None,
        context="tests/rubric.txt",
    )
    task_config_file = (
        _snapshot_immutable_file(
            task_config_path,
            capture_bytes=None,
            context="task.toml",
        )
        if task_config_path is not None
        else None
    )
    instruction = instruction_file.captured_bytes.decode("utf-8")
    rubric = rubric_file.captured_bytes.decode("utf-8")

    data_root = _validated_data_root(task_root)
    data_paths, traversal_truncated = _walk_data_file_inventory(data_root, limits)
    if traversal_truncated:
        raise ValueError(
            "environment/data traversal exceeded max_entries_visited "
            f"limit {limits.max_entries_visited}; refusing a partial snapshot"
        )
    data_inventory: list[tuple[str, _ImmutableFileSnapshot]] = []
    for index, path in enumerate(data_paths):
        relative_path = path.relative_to(data_root).as_posix()
        try:
            path.resolve(strict=True).relative_to(data_root.resolve(strict=True))
        except (FileNotFoundError, ValueError) as exc:
            raise ValueError(
                f"environment/data source must be contained under data root: {path}"
            ) from exc
        capture_bytes = limits.max_probe_bytes + 1 if index < limits.max_files else 0
        data_inventory.append(
            (
                relative_path,
                _snapshot_immutable_file(
                    path,
                    capture_bytes=capture_bytes,
                    context=f"environment/data/{relative_path}",
                ),
            )
        )

    preview_inventory = data_inventory[: limits.max_files]
    walk_omitted_files = len(data_inventory) - len(preview_inventory)
    probed_data_files = tuple(
        _table_snapshot(
            relative_path,
            limits,
            file_snapshot=file_snapshot,
        )
        for relative_path, file_snapshot in preview_inventory
    )
    data_files, budget_omitted_files = _fit_schema_budget(
        probed_data_files,
        limits.max_output_chars,
    )
    question = " ".join(_extract_markdown_section(instruction, "Question").split())
    required_outputs = _extract_required_outputs(instruction)
    summary_anchors = _summary_anchors(rubric)
    anchors = _task_anchors(question, required_outputs, summary_anchors, data_files)
    input_hashes = tuple(
        sorted(
            [
                ("instruction.md", instruction_file.sha256),
                ("tests/rubric.txt", rubric_file.sha256),
            ]
            + (
                [("task.toml", task_config_file.sha256)]
                if task_config_file is not None
                else []
            )
            + [
                (f"environment/data/{relative_path}", file_snapshot.sha256)
                for relative_path, file_snapshot in data_inventory
            ]
        )
    )
    snapshot = TaskSnapshot(
        task_id=task_root.name,
        question=question,
        required_outputs=required_outputs,
        data_files=data_files,
        anchors=anchors,
        required_summary_anchor_ids=tuple(
            anchor.anchor_id for anchor in summary_anchors
        ),
        input_hashes=input_hashes,
        snapshot_sha256="",
        omitted_data_files=walk_omitted_files + budget_omitted_files,
        data_traversal_truncated=traversal_truncated,
    )
    return replace(
        snapshot,
        snapshot_sha256=sha256_text(canonical_json(_snapshot_payload(snapshot))),
    )

"""Strict, read-only resolution of sealed task-rubric bundles."""

from __future__ import annotations

import json
import math
import re
from dataclasses import asdict, dataclass
from pathlib import Path

from rubric_gen.submission_revision.rubrics.prompts import (
    TaskRubricRequest,
    build_task_rubric_prompt,
)
from rubric_gen.submission_revision.rubrics.schema import (
    canonical_json,
    load_json_strict,
    parse_task_process_rubric,
    render_task_process_rubric,
    sha256_text,
    validate_rendered_task_process_rubric,
)


TASK_RUBRIC_PROVIDER = "google-gemini"

SAFE_TASK_ID_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]*\Z")
SHA256_PATTERN = re.compile(r"[0-9a-f]{64}\Z")
GENERATION_CODE_KEYS = {
    "gemini_client.py",
    "rubric_bundles.py",
    "rubric_scoring.py",
    "task_rubric_compiler.py",
    "task_rubric_prompts.py",
    "task_rubrics.py",
    "task_snapshots.py",
}
_COMPILER_CONFIG_KEYS = {
    "api_key_env",
    "max_concurrency",
    "max_retries",
    "model",
    "rewriter_provenance_sha256",
    "seed",
    "task_ids",
    "tasks_dir",
    "temperature",
}
_REWRITER_PROVENANCE_KEYS = {
    "provider",
    "model",
    "implementation_id",
    "implementation_sha256",
}
_RESPONSE_METADATA_KEYS = {
    "raw_response_sha256",
    "response_id",
    "served_model_version",
}


class RubricBundleError(ValueError):
    """Raised when a sealed rubric bundle cannot be trusted."""


@dataclass(frozen=True)
class ResolvedRubricBundle:
    task_id: str
    rubric_set_id: str
    rubric_id: str
    rubric_sha256: str
    rubric_json_path: Path
    rubric_json_text: str
    rendered_path: Path
    rendered_text: str
    task_manifest_path: Path
    task_manifest_sha256: str


def is_safe_task_id(task_id: object) -> bool:
    return isinstance(task_id, str) and bool(SAFE_TASK_ID_PATTERN.fullmatch(task_id))


def compilation_payload(
    config_sha256: str,
    generation_code_sha256: str,
    rewriter_provenance_sha256: str,
    tasks: dict[str, dict[str, str]],
) -> dict[str, object]:
    return {
        "compiler_config_sha256": config_sha256,
        "generation_code_sha256": generation_code_sha256,
        "rewriter_provenance_sha256": rewriter_provenance_sha256,
        "tasks": tasks,
    }


def _object(value: object, context: str) -> dict[str, object]:
    if type(value) is not dict:
        raise RubricBundleError(f"{context} must be an object")
    return value


def _string(value: object, context: str) -> str:
    if not isinstance(value, str):
        raise RubricBundleError(f"{context} must be a string")
    return value


def _hash(value: object, context: str) -> str:
    digest = _string(value, context)
    if not SHA256_PATTERN.fullmatch(digest):
        raise RubricBundleError(f"{context} must be a lowercase SHA-256 digest")
    return digest


def _closed_keys(value: dict[str, object], expected: set[str], context: str) -> None:
    if set(value) != expected:
        raise RubricBundleError(f"{context} has missing or unexpected fields")


def _validated_compiler_config(value: object) -> dict[str, object]:
    config = _object(value, "compiler config")
    _closed_keys(config, _COMPILER_CONFIG_KEYS, "compiler config")
    _hash(
        config["rewriter_provenance_sha256"],
        "compiler config rewriter provenance sha256",
    )
    for field_name in ("api_key_env", "model", "tasks_dir"):
        if type(config[field_name]) is not str or not config[field_name]:
            raise RubricBundleError(f"compiler config {field_name} must be a string")
    task_ids = config["task_ids"]
    if (
        type(task_ids) is not list
        or not task_ids
        or any(not is_safe_task_id(task_id) for task_id in task_ids)
        or len(set(task_ids)) != len(task_ids)
    ):
        raise RubricBundleError("compiler config task_ids is invalid")
    if type(config["max_retries"]) is not int or config["max_retries"] < 0:
        raise RubricBundleError("compiler config max_retries is invalid")
    if type(config["max_concurrency"]) is not int or config["max_concurrency"] < 1:
        raise RubricBundleError("compiler config max_concurrency is invalid")
    if type(config["seed"]) is not int:
        raise RubricBundleError("compiler config seed is invalid")
    temperature = config["temperature"]
    if (
        isinstance(temperature, bool)
        or not isinstance(temperature, (int, float))
        or not math.isfinite(temperature)
    ):
        raise RubricBundleError("compiler config temperature is invalid")
    return config


def _validated_rewriter_provenance(value: object) -> dict[str, object]:
    raw = _object(value, "rewriter provenance")
    _closed_keys(raw, _REWRITER_PROVENANCE_KEYS, "rewriter provenance")
    for field_name in ("provider", "model", "implementation_id"):
        field_value = raw[field_name]
        if type(field_value) is not str or not field_value.strip():
            raise RubricBundleError(
                f"rewriter provenance {field_name} must be non-empty"
            )
    _hash(
        raw["implementation_sha256"],
        "rewriter provenance implementation_sha256",
    )
    return raw


def _validated_response_metadata(value: object) -> dict[str, object]:
    metadata = _object(value, "response metadata")
    _closed_keys(metadata, _RESPONSE_METADATA_KEYS, "response metadata")
    _hash(metadata["raw_response_sha256"], "response metadata raw-response hash")
    for field_name in ("served_model_version", "response_id"):
        field_value = metadata[field_name]
        if field_value is not None and (
            type(field_value) is not str or not field_value.strip()
        ):
            raise RubricBundleError(
                f"response metadata {field_name} must be null or a non-empty string"
            )
    return metadata


def _validated_generation_code_sha256s(value: object) -> dict[str, str]:
    raw_hashes = _object(value, "generation code hashes")
    key_set = set(raw_hashes)
    if key_set != GENERATION_CODE_KEYS:
        raise RubricBundleError(
            "generation code hashes has missing or unexpected fields"
        )
    return {
        module_name: _hash(raw_hashes[module_name], f"generation code {module_name}")
        for module_name in sorted(key_set)
    }


_ROOT_TASK_ENTRY_KEYS = {
    "input_sha256",
    "response_metadata_sha256",
    "rubric_id",
    "rubric_sha256",
    "snapshot_sha256",
    "task_manifest_path",
    "task_manifest_sha256",
}


def _validated_root_task_entries(
    tasks: dict[str, object],
) -> tuple[
    dict[str, dict[str, object]],
    dict[str, dict[str, str]],
    dict[str, dict[str, str]],
]:
    entries: dict[str, dict[str, object]] = {}
    compilation_tasks: dict[str, dict[str, str]] = {}
    identity_tasks: dict[str, dict[str, str]] = {}
    for member_id, raw_entry in sorted(tasks.items()):
        if not is_safe_task_id(member_id):
            raise RubricBundleError(f"unsafe root task ID: {member_id!r}")
        entry = _object(raw_entry, f"root task entry {member_id}")
        _closed_keys(entry, _ROOT_TASK_ENTRY_KEYS, f"root task entry {member_id}")
        input_sha256 = _hash(entry["input_sha256"], f"root input hash {member_id}")
        response_metadata_sha256 = _hash(
            entry["response_metadata_sha256"],
            f"root response metadata hash {member_id}",
        )
        rubric_id = _hash(entry["rubric_id"], f"root rubric ID {member_id}")
        rubric_sha256 = _hash(
            entry["rubric_sha256"],
            f"root rubric hash {member_id}",
        )
        if rubric_id != rubric_sha256:
            raise RubricBundleError(f"root rubric ID mismatch for {member_id}")
        snapshot_sha256 = _hash(
            entry["snapshot_sha256"],
            f"root snapshot hash {member_id}",
        )
        expected_manifest_path = f"tasks/{member_id}/manifest.json"
        if entry["task_manifest_path"] != expected_manifest_path:
            raise RubricBundleError("task manifest path is not canonical")
        _hash(
            entry["task_manifest_sha256"],
            f"root task manifest hash {member_id}",
        )
        entries[member_id] = entry
        compilation_tasks[member_id] = {
            "input_sha256": input_sha256,
            "snapshot_sha256": snapshot_sha256,
        }
        identity_tasks[member_id] = {
            "input_sha256": input_sha256,
            "response_metadata_sha256": response_metadata_sha256,
            "rubric_id": rubric_id,
            "snapshot_sha256": snapshot_sha256,
        }
    return entries, compilation_tasks, identity_tasks


def _read_json_object(path: Path, context: str) -> dict[str, object]:
    return _read_json_object_bytes(_read_regular_bytes(path, context), context)


def read_bundle_json_object(path: Path, context: str) -> dict[str, object]:
    """Read one strict, nonsymlink JSON object from a bundle."""
    return _read_json_object(path, context)


def _read_regular_bytes(path: Path, context: str) -> bytes:
    if path.is_symlink() or not path.is_file():
        raise RubricBundleError(f"missing regular {context}: {path}")
    try:
        return path.read_bytes()
    except OSError as exc:
        raise RubricBundleError(f"invalid {context}: {exc}") from exc


def _decode_json_bytes(raw: bytes, context: str) -> object:
    try:
        return load_json_strict(raw.decode("utf-8"))
    except (UnicodeError, ValueError) as exc:
        raise RubricBundleError(f"invalid {context}: {exc}") from exc


def _read_json_object_bytes(raw: bytes, context: str) -> dict[str, object]:
    value = _decode_json_bytes(raw, context)
    return _object(value, context)


def _read_json_string_list(path: Path, context: str) -> list[str]:
    return _read_json_string_list_bytes(_read_regular_bytes(path, context), context)


def _read_json_string_list_bytes(raw: bytes, context: str) -> list[str]:
    value = _decode_json_bytes(raw, context)
    if type(value) is not list or any(not isinstance(item, str) for item in value):
        raise RubricBundleError(f"{context} must be an array of strings")
    return value


def _sha256_bytes(raw: bytes) -> str:
    import hashlib

    return hashlib.sha256(raw).hexdigest()


def _artifact_path(task_dir: Path, relative: str) -> Path:
    candidate = Path(relative)
    if (
        candidate.is_absolute()
        or ".." in candidate.parts
        or candidate.as_posix() != relative
    ):
        raise RubricBundleError(f"invalid artifact path: {relative!r}")
    path = task_dir.joinpath(*candidate.parts)
    try:
        if path.resolve(strict=True).is_relative_to(task_dir.resolve(strict=True)):
            return path
    except (OSError, RuntimeError):
        pass
    raise RubricBundleError(f"artifact leaves task bundle: {relative!r}")


def _validate_snapshot_attestation(
    task_id: str,
    task_manifest: dict[str, object],
    artifact_bytes: dict[str, bytes],
) -> None:
    snapshot_record = _object(task_manifest["snapshot"], "snapshot record")
    _closed_keys(
        snapshot_record, {"input_hashes", "input_sha256", "sha256"}, "snapshot record"
    )
    input_hashes = snapshot_record["input_hashes"]
    if type(input_hashes) is not list:
        raise RubricBundleError("snapshot input_hashes must be an array")
    input_sha256 = _hash(snapshot_record["input_sha256"], "snapshot input_sha256")
    if sha256_text(canonical_json(input_hashes)) != input_sha256:
        raise RubricBundleError("snapshot input hash mismatch")
    snapshot_sha256 = _hash(snapshot_record["sha256"], "snapshot sha256")

    expected_files = {
        "request.json",
        "response.txt",
        "response_metadata.json",
        "errors.json",
    }
    attempt_files: dict[int, set[str]] = {}
    for relative in artifact_bytes:
        if not relative.startswith("attempts/"):
            continue
        match = re.fullmatch(
            r"attempts/attempt-([1-9][0-9]*)/"
            r"(request\.json|response\.txt|response_metadata\.json|errors\.json)",
            relative,
        )
        if match is None:
            raise RubricBundleError("attempt artifacts are not canonical")
        attempt_number = int(match.group(1))
        attempt_files.setdefault(attempt_number, set()).add(match.group(2))
    if not attempt_files:
        raise RubricBundleError("task bundle has no generation attempts")
    attempt_numbers = sorted(attempt_files)
    if attempt_numbers != list(range(1, len(attempt_numbers) + 1)):
        raise RubricBundleError("attempt directories must be contiguous")
    if any(files != expected_files for files in attempt_files.values()):
        raise RubricBundleError(
            "generation attempts do not contain exactly the required files"
        )

    snapshot: dict[str, object] | None = None
    flattened_errors: list[str] = []
    successful_request: dict[str, object] | None = None
    successful_attempt_number: int | None = None
    for attempt_number in attempt_numbers:
        context = f"attempt-{attempt_number} request"
        attempt_prefix = f"attempts/attempt-{attempt_number}"
        request = _read_json_object_bytes(
            artifact_bytes[f"{attempt_prefix}/request.json"],
            context,
        )
        _closed_keys(
            request,
            {"task_snapshot", "previous_errors"},
            context,
        )
        request_snapshot = _object(request["task_snapshot"], f"{context} snapshot")
        if snapshot is None:
            snapshot = request_snapshot
            if snapshot.get("task_id") != task_id:
                raise RubricBundleError("request task ID mismatch")
            if snapshot.get("snapshot_sha256") != snapshot_sha256:
                raise RubricBundleError("request snapshot hash mismatch")
            if snapshot.get("input_hashes") != input_hashes:
                raise RubricBundleError("request immutable input hashes mismatch")
            snapshot_payload = dict(snapshot)
            snapshot_payload.pop("snapshot_sha256", None)
            if sha256_text(canonical_json(snapshot_payload)) != snapshot_sha256:
                raise RubricBundleError("snapshot content hash mismatch")
        elif request_snapshot != snapshot:
            raise RubricBundleError(f"{context} snapshot mismatch")
        previous_errors = request["previous_errors"]
        if type(previous_errors) is not list or any(
            not isinstance(error, str) for error in previous_errors
        ):
            raise RubricBundleError(f"{context} previous_errors must be strings")
        if previous_errors != flattened_errors:
            raise RubricBundleError(f"{context} previous-error chain mismatch")
        response_bytes = artifact_bytes[f"{attempt_prefix}/response.txt"]
        response_metadata_bytes = artifact_bytes[
            f"{attempt_prefix}/response_metadata.json"
        ]
        response_metadata = _validated_response_metadata(
            _read_json_object_bytes(
                response_metadata_bytes,
                f"attempt-{attempt_number} response metadata",
            )
        )
        if response_metadata_bytes != (canonical_json(response_metadata) + "\n").encode(
            "utf-8"
        ):
            raise RubricBundleError(
                f"attempt-{attempt_number} response metadata is not canonical JSON"
            )
        if response_metadata["raw_response_sha256"] != _sha256_bytes(response_bytes):
            raise RubricBundleError(
                f"attempt-{attempt_number} response metadata hash mismatch"
            )
        errors = _read_json_string_list_bytes(
            artifact_bytes[f"{attempt_prefix}/errors.json"],
            f"attempt-{attempt_number} errors",
        )
        is_final = attempt_number == attempt_numbers[-1]
        if is_final:
            if errors:
                raise RubricBundleError("final generation attempt was not successful")
            successful_request = request
            successful_attempt_number = attempt_number
        elif not errors:
            raise RubricBundleError("intermediate generation attempt has no errors")
        flattened_errors.extend(errors)

    if (
        snapshot is None
        or successful_request is None
        or successful_attempt_number is None
    ):
        raise RubricBundleError("task bundle has no successful generation attempt")
    prompt_request = TaskRubricRequest(
        task_snapshot=snapshot,
        previous_errors=tuple(successful_request["previous_errors"]),  # type: ignore[arg-type]
    )
    hashes = _object(task_manifest["hashes"], "task hashes")
    prompt_sha256 = _hash(hashes["prompt_sha256"], "prompt sha256")
    if sha256_text(build_task_rubric_prompt(prompt_request)) != prompt_sha256:
        raise RubricBundleError("prompt hash mismatch")
    successful_response = artifact_bytes[
        f"attempts/attempt-{successful_attempt_number}/response.txt"
    ]
    if _sha256_bytes(successful_response) != hashes["raw_response_sha256"]:
        raise RubricBundleError("successful response does not match raw response")
    successful_response_metadata = artifact_bytes[
        f"attempts/attempt-{successful_attempt_number}/response_metadata.json"
    ]
    if successful_response_metadata != artifact_bytes["response_metadata.json"]:
        raise RubricBundleError(
            "successful attempt response metadata does not match final metadata"
        )


def resolve_rubric_bundle(
    rubric_set_dir: Path,
    task_id: str,
) -> ResolvedRubricBundle:
    """Resolve one task from a sealed set after verifying all bundle attestations."""

    if not is_safe_task_id(task_id):
        raise RubricBundleError(f"unsafe task ID: {task_id!r}")
    try:
        root = rubric_set_dir.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise RubricBundleError(f"rubric set does not exist: {rubric_set_dir}") from exc
    if not root.is_dir():
        raise RubricBundleError(f"rubric set is not a directory: {root}")
    root_children = {path.name for path in root.iterdir()}
    if root_children != {"manifest.json", "tasks"}:
        raise RubricBundleError("rubric set root has unlisted members")

    root_manifest = _read_json_object(root / "manifest.json", "root manifest")
    _closed_keys(
        root_manifest,
        {
            "compilation_sha256",
            "compiler_config",
            "compiler_config_sha256",
            "generated_at",
            "generation_code_sha256",
            "generation_code_sha256s",
            "rewriter_provenance",
            "rewriter_provenance_sha256",
            "rubric_set_id",
            "status",
            "tasks",
        },
        "root manifest",
    )
    if root_manifest["status"] != "sealed":
        raise RubricBundleError("root manifest is not sealed")
    _string(root_manifest["generated_at"], "root generated_at")
    compiler_config = _validated_compiler_config(root_manifest["compiler_config"])
    compiler_config_sha256 = _hash(
        root_manifest["compiler_config_sha256"],
        "compiler config sha256",
    )
    if sha256_text(canonical_json(compiler_config)) != compiler_config_sha256:
        raise RubricBundleError("compiler config hash mismatch")
    generation_code_sha256s = _validated_generation_code_sha256s(
        root_manifest["generation_code_sha256s"]
    )
    generation_code_sha256 = _hash(
        root_manifest["generation_code_sha256"],
        "generation code sha256",
    )
    if sha256_text(canonical_json(generation_code_sha256s)) != generation_code_sha256:
        raise RubricBundleError("generation code hash-map mismatch")
    rewriter_provenance = _validated_rewriter_provenance(
        root_manifest["rewriter_provenance"]
    )
    rewriter_provenance_sha256 = _hash(
        root_manifest["rewriter_provenance_sha256"],
        "rewriter provenance sha256",
    )
    if sha256_text(canonical_json(rewriter_provenance)) != rewriter_provenance_sha256:
        raise RubricBundleError("rewriter provenance hash mismatch")
    if compiler_config["rewriter_provenance_sha256"] != rewriter_provenance_sha256:
        raise RubricBundleError("compiler config rewriter provenance mismatch")
    if compiler_config["model"] != rewriter_provenance["model"]:
        raise RubricBundleError("rewriter provenance model mismatch")
    compilation_sha256 = _hash(
        root_manifest["compilation_sha256"],
        "compilation sha256",
    )
    rubric_set_id = _hash(root_manifest["rubric_set_id"], "rubric set ID")
    tasks = _object(root_manifest["tasks"], "root tasks")
    if task_id not in tasks:
        raise RubricBundleError(f"task is not a member of rubric set: {task_id}")
    task_entries, compilation_tasks, identity_tasks = _validated_root_task_entries(
        tasks
    )
    if set(compiler_config["task_ids"]) != set(task_entries):  # type: ignore[arg-type]
        raise RubricBundleError("compiler config task IDs do not match root tasks")
    expected_compilation_sha256 = sha256_text(
        canonical_json(
            compilation_payload(
                compiler_config_sha256,
                generation_code_sha256,
                rewriter_provenance_sha256,
                compilation_tasks,
            )
        )
    )
    if compilation_sha256 != expected_compilation_sha256:
        raise RubricBundleError("compilation hash mismatch")

    tasks_root = root / "tasks"
    if tasks_root.is_symlink() or not tasks_root.is_dir():
        raise RubricBundleError("tasks root must be a regular directory")
    actual_tasks = {path.name for path in tasks_root.iterdir() if path.is_dir()}
    if actual_tasks != set(tasks) or any(
        not path.is_dir() for path in tasks_root.iterdir()
    ):
        raise RubricBundleError(
            "task directory membership does not match root manifest"
        )

    task_entry = task_entries[task_id]

    task_dir = tasks_root / task_id
    if task_dir.is_symlink() or task_dir.resolve(
        strict=True
    ).parent != tasks_root.resolve(strict=True):
        raise RubricBundleError("task bundle leaves rubric set root")
    task_manifest_path = task_dir / "manifest.json"
    expected_manifest_sha256 = _hash(
        task_entry["task_manifest_sha256"],
        "task manifest sha256",
    )
    task_manifest_bytes = _read_regular_bytes(
        task_manifest_path,
        "task manifest",
    )
    actual_manifest_sha256 = _sha256_bytes(task_manifest_bytes)
    if actual_manifest_sha256 != expected_manifest_sha256:
        raise RubricBundleError("task manifest hash mismatch")
    task_manifest = _read_json_object_bytes(task_manifest_bytes, "task manifest")
    _closed_keys(
        task_manifest,
        {
            "artifacts",
            "compiler",
            "generated_at",
            "hashes",
            "rubric_id",
            "rubric_set_id",
            "rubric_sha256",
            "snapshot",
            "status",
            "task_id",
            "validation_errors",
        },
        "task manifest",
    )
    if task_manifest["status"] != "valid" or task_manifest["validation_errors"] != []:
        raise RubricBundleError("task manifest does not attest a valid rubric")
    if task_manifest["task_id"] != task_id:
        raise RubricBundleError("task manifest task ID mismatch")
    if task_manifest["rubric_set_id"] != rubric_set_id:
        raise RubricBundleError("task manifest rubric-set ID mismatch")

    artifacts = _object(task_manifest["artifacts"], "task artifacts")
    required_artifacts = {
        "raw_response.txt",
        "response_metadata.json",
        "rubric.json",
        "process_rubric.txt",
    }
    if not required_artifacts.issubset(artifacts):
        raise RubricBundleError("task manifest is missing required artifacts")
    actual_artifacts: set[str] = set()
    for path in task_dir.rglob("*"):
        if path.is_symlink():
            raise RubricBundleError(f"bundle member must not be a symlink: {path}")
        if path.is_file() and path != task_manifest_path:
            actual_artifacts.add(path.relative_to(task_dir).as_posix())
    if actual_artifacts != set(artifacts):
        raise RubricBundleError("task artifact membership does not match manifest")
    artifact_bytes: dict[str, bytes] = {}
    for relative, expected in artifacts.items():
        path = _artifact_path(task_dir, relative)
        raw = _read_regular_bytes(path, f"bundle artifact {relative}")
        if _sha256_bytes(raw) != _hash(expected, f"artifact hash {relative}"):
            raise RubricBundleError(f"bundle artifact hash mismatch: {relative}")
        artifact_bytes[relative] = raw

    compiler = _object(task_manifest["compiler"], "compiler record")
    _closed_keys(
        compiler,
        {
            "code_sha256",
            "code_sha256s",
            "compiler_config_sha256",
            "model",
            "provider",
            "rewriter_provenance",
            "rewriter_provenance_sha256",
            "seed",
            "temperature",
        },
        "compiler record",
    )
    if _hash(compiler["code_sha256"], "compiler code sha256") != generation_code_sha256:
        raise RubricBundleError("task compiler code hash mismatch")
    if (
        _validated_generation_code_sha256s(compiler["code_sha256s"])
        != generation_code_sha256s
    ):
        raise RubricBundleError("task compiler code map mismatch")
    if (
        _hash(
            compiler["compiler_config_sha256"],
            "task compiler config sha256",
        )
        != compiler_config_sha256
    ):
        raise RubricBundleError("task compiler config hash mismatch")
    task_rewriter_provenance = _validated_rewriter_provenance(
        compiler["rewriter_provenance"]
    )
    if task_rewriter_provenance != rewriter_provenance:
        raise RubricBundleError("task rewriter provenance mismatch")
    if (
        _hash(
            compiler["rewriter_provenance_sha256"],
            "task rewriter provenance sha256",
        )
        != rewriter_provenance_sha256
    ):
        raise RubricBundleError("task rewriter provenance hash mismatch")
    if compiler["provider"] != rewriter_provenance["provider"]:
        raise RubricBundleError("compiler provider mismatch")
    if compiler["model"] != compiler_config["model"]:
        raise RubricBundleError("task compiler model disagrees with root config")
    if compiler["model"] != rewriter_provenance["model"]:
        raise RubricBundleError("task compiler model disagrees with rewriter")
    if type(compiler["seed"]) is not int:
        raise RubricBundleError("task compiler seed is invalid")
    if compiler["seed"] != compiler_config["seed"]:
        raise RubricBundleError("task compiler seed disagrees with root config")
    if canonical_json(compiler["temperature"]) != canonical_json(
        compiler_config["temperature"]
    ):
        raise RubricBundleError("task compiler temperature disagrees with root config")

    hashes = _object(task_manifest["hashes"], "task hashes")
    _closed_keys(
        hashes,
        {
            "input_sha256",
            "model_sha256",
            "prompt_sha256",
            "raw_response_sha256",
            "rendered_rubric_sha256",
            "response_metadata_sha256",
            "seed_sha256",
            "snapshot_sha256",
            "structured_rubric_sha256",
            "temperature_sha256",
        },
        "task hashes",
    )
    for name, digest in hashes.items():
        _hash(digest, name)
    if hashes["model_sha256"] != sha256_text(
        _string(compiler["model"], "compiler model")
    ):
        raise RubricBundleError("model hash mismatch")
    if hashes["temperature_sha256"] != sha256_text(
        canonical_json(compiler["temperature"])
    ):
        raise RubricBundleError("temperature hash mismatch")
    if hashes["seed_sha256"] != sha256_text(canonical_json(compiler["seed"])):
        raise RubricBundleError("seed hash mismatch")
    if hashes["raw_response_sha256"] != artifacts["raw_response.txt"]:
        raise RubricBundleError("raw-response hash mismatch")
    if hashes["response_metadata_sha256"] != artifacts["response_metadata.json"]:
        raise RubricBundleError("response-metadata hash mismatch")
    if hashes["structured_rubric_sha256"] != artifacts["rubric.json"]:
        raise RubricBundleError("structured-rubric hash mismatch")
    if hashes["rendered_rubric_sha256"] != artifacts["process_rubric.txt"]:
        raise RubricBundleError("rendered-rubric hash mismatch")
    if hashes["input_sha256"] != task_entry["input_sha256"]:
        raise RubricBundleError("root input hash mismatch")
    if hashes["snapshot_sha256"] != task_entry["snapshot_sha256"]:
        raise RubricBundleError("root snapshot hash mismatch")
    if hashes["response_metadata_sha256"] != task_entry["response_metadata_sha256"]:
        raise RubricBundleError("root response-metadata hash mismatch")
    response_metadata = _validated_response_metadata(
        _read_json_object_bytes(
            artifact_bytes["response_metadata.json"],
            "response metadata",
        )
    )
    if artifact_bytes["response_metadata.json"] != (
        canonical_json(response_metadata) + "\n"
    ).encode("utf-8"):
        raise RubricBundleError("response metadata is not canonical JSON")
    if response_metadata["raw_response_sha256"] != artifacts["raw_response.txt"]:
        raise RubricBundleError("response metadata raw-response hash mismatch")
    _validate_snapshot_attestation(
        task_id,
        task_manifest,
        artifact_bytes,
    )

    rubric_json_path = task_dir / "rubric.json"
    rubric_sha256 = _hash(task_manifest["rubric_sha256"], "rubric sha256")
    rubric_id = _hash(task_manifest["rubric_id"], "rubric ID")
    if rubric_sha256 != artifacts["rubric.json"] or rubric_id != rubric_sha256:
        raise RubricBundleError("rubric ID or hash mismatch")
    if (
        task_entry["rubric_sha256"] != rubric_sha256
        or task_entry["rubric_id"] != rubric_id
    ):
        raise RubricBundleError("root rubric ID or hash mismatch")
    try:
        rubric_text = artifact_bytes["rubric.json"].decode("utf-8")
        rubric = parse_task_process_rubric(rubric_text)
    except (UnicodeError, ValueError, json.JSONDecodeError) as exc:
        raise RubricBundleError(f"invalid structured rubric: {exc}") from exc
    if rubric.task_id != task_id:
        raise RubricBundleError("structured rubric task ID mismatch")
    if rubric_text != canonical_json(asdict(rubric)) + "\n":
        raise RubricBundleError("structured rubric is not canonical JSON")
    rendered_path = task_dir / "process_rubric.txt"
    try:
        rendered_text = artifact_bytes["process_rubric.txt"].decode("utf-8")
    except UnicodeError as exc:
        raise RubricBundleError(f"invalid rendered rubric: {exc}") from exc
    if rendered_text != render_task_process_rubric(rubric):
        raise RubricBundleError("rendered rubric is not derived from structured rubric")
    try:
        validate_rendered_task_process_rubric(rubric, rendered_text)
    except ValueError as exc:
        raise RubricBundleError(str(exc)) from exc

    identity = {
        "compilation_sha256": compilation_sha256,
        "generation_code_sha256": generation_code_sha256,
        "rewriter_provenance_sha256": rewriter_provenance_sha256,
        "tasks": identity_tasks,
    }
    if sha256_text(canonical_json(identity)) != rubric_set_id:
        raise RubricBundleError("rubric-set ID mismatch")

    return ResolvedRubricBundle(
        task_id=task_id,
        rubric_set_id=rubric_set_id,
        rubric_id=rubric_id,
        rubric_sha256=rubric_sha256,
        rubric_json_path=rubric_json_path,
        rubric_json_text=rubric_text,
        rendered_path=rendered_path,
        rendered_text=rendered_text,
        task_manifest_path=task_manifest_path,
        task_manifest_sha256=actual_manifest_sha256,
    )

"""Canonical prompt contract for task-specific process-rubric generation."""

from __future__ import annotations

from dataclasses import dataclass

from rubric_gen.submission_revision.rubrics.schema import canonical_json


@dataclass(frozen=True)
class TaskRubricRequest:
    task_snapshot: dict[str, object]
    previous_errors: tuple[str, ...] = ()


_RUBRIC_JSON_SCHEMA: dict[str, object] = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": False,
    "properties": {
        "criteria": {
            "items": {
                "additionalProperties": False,
                "properties": {
                    "acceptable_alternatives": {
                        "items": {"type": "string"},
                        "minItems": 1,
                        "type": "array",
                    },
                    "anti_evidence": {
                        "items": {"type": "string"},
                        "minItems": 1,
                        "type": "array",
                    },
                    "criterion_id": {"type": "string"},
                    "description": {"type": "string"},
                    "levels": {
                        "items": {
                            "additionalProperties": False,
                            "properties": {
                                "description": {"type": "string"},
                                "label": {
                                    "pattern": "^[A-Z]$",
                                    "type": "string",
                                },
                                "points": {"type": "integer"},
                            },
                            "required": ["label", "points", "description"],
                            "type": "object",
                        },
                        "maxItems": 26,
                        "minItems": 3,
                        "type": "array",
                    },
                    "max_points": {"type": "integer"},
                    "required_evidence": {
                        "items": {"type": "string"},
                        "minItems": 1,
                        "type": "array",
                    },
                    "task_anchors": {
                        "items": {"type": "string"},
                        "minItems": 1,
