"""Secure output storage for revision evaluation stages."""

from __future__ import annotations

import os
import shutil
import stat
from pathlib import Path

from rubric_gen.artifacts.serialization import write_json_atomic
from rubric_gen.submission_revision.artifacts import (
    make_tree_owner_writable,
    read_json_object,
)


class EvaluationStore:
    """Keep stage output inside one symlink-free directory tree."""

    def __init__(self, root: Path) -> None:
        self.root = Path(os.path.abspath(os.fspath(root.expanduser())))
        self._validate_path(
            self.root,
            expected="directory",
            allow_missing=True,
        )

    def path(self, *parts: str) -> Path:
        for part in parts:
            if (
                type(part) is not str
                or not part
                or part in {".", ".."}
                or Path(part).name != part
            ):
                raise RuntimeError(f"evaluation output path component is unsafe: {part!r}")
        candidate = self.root.joinpath(*parts)
        try:
            candidate.relative_to(self.root)
        except ValueError as exc:
            raise RuntimeError(
                f"evaluation output path escapes its root: {candidate}"
            ) from exc
        self._validate_path(candidate, expected=None, allow_missing=True)
        return candidate

    def prepare(self, identity: dict[str, object], resume: bool) -> None:
        if os.path.lexists(self.root):
            self._validate_path(
                self.root,
                expected="directory",
                allow_missing=False,
            )
            self.validate_tree()
            try:
                manifest_path = self.regular_file("manifest.json")
                manifest = read_json_object(manifest_path, "evaluation manifest")
            except RuntimeError:
                if not resume:
                    raise
                self._replace(identity)
                return
            if manifest != identity:
                if not resume:
                    raise RuntimeError("evaluation resume identity changed")
                self._replace(identity)
                return
            if not resume and any(
                path.name != "manifest.json" for path in self.root.iterdir()
            ):
                raise FileExistsError(
                    f"evaluation output is not empty: {self.root}"
                )
            return
        self._ensure_directory_path(self.root)
        self.write_json(("manifest.json",), identity)

    def _replace(self, identity: dict[str, object]) -> None:
        self.validate_tree()
        make_tree_owner_writable(self.root)
        shutil.rmtree(self.root)
        if os.path.lexists(self.root):
            raise RuntimeError(
                f"failed to replace incompatible evaluation output: {self.root}"
            )
        self._ensure_directory_path(self.root)
        self.write_json(("manifest.json",), identity)

    def ensure_directory(self, *parts: str) -> Path:
        path = self.path(*parts)
        self._ensure_directory_path(path)
        return path

    def regular_file(self, *parts: str, allow_missing: bool = False) -> Path:
        path = self.path(*parts)
        self._validate_path(
            path,
            expected="file",
            allow_missing=allow_missing,
        )
        return path

    def contained_regular_file(self, candidate: Path) -> Path:
        path = Path(os.path.abspath(os.fspath(candidate.expanduser())))
        try:
            path.relative_to(self.root)
        except ValueError as exc:
            raise RuntimeError(
                f"evaluation artifact path escapes its root: {candidate}"
            ) from exc
        self._validate_path(path, expected="file", allow_missing=False)
        return path

    def validate_tree(self, *parts: str) -> Path:
        root = self.path(*parts) if parts else self.root
        self._validate_path(root, expected="directory", allow_missing=False)
        pending = [root]
        while pending:
            directory = pending.pop()
            try:
                entries = list(os.scandir(directory))
            except OSError as exc:
                raise RuntimeError(
                    f"cannot inspect evaluation output directory: {directory}"
                ) from exc
            for entry in entries:
                path = Path(entry.path)
                try:
                    entry_stat = entry.stat(follow_symlinks=False)
                except OSError as exc:
                    raise RuntimeError(
                        f"cannot inspect evaluation output path: {path}"
                    ) from exc
                if stat.S_ISLNK(entry_stat.st_mode):
                    raise RuntimeError(
                        f"evaluation output path contains a symlink: {path}"
                    )
                if stat.S_ISDIR(entry_stat.st_mode):
                    pending.append(path)
                elif not stat.S_ISREG(entry_stat.st_mode):
                    raise RuntimeError(f"evaluation output path is not regular: {path}")
        return root

    def write_json(self, parts: tuple[str, ...], value: object) -> Path:
        if not parts:
            raise RuntimeError("evaluation JSON output path is empty")
        self.ensure_directory(*parts[:-1])
        path = self.regular_file(*parts, allow_missing=True)
        write_json_atomic(path, value)
        self._validate_path(path, expected="file", allow_missing=False)
        return path

    @staticmethod
    def _validate_path(
        path: Path,
        *,
        expected: str | None,
        allow_missing: bool,
    ) -> None:
        current = Path(path.anchor)
        parts = path.parts[1:]
        missing = False
        for index, part in enumerate(parts):
            current = current / part
            if missing:
                continue
            try:
                current_stat = os.lstat(current)
            except FileNotFoundError:
                missing = True
                continue
            except OSError as exc:
                raise RuntimeError(
                    f"cannot inspect evaluation output path: {current}"
                ) from exc
            if stat.S_ISLNK(current_stat.st_mode):
                raise RuntimeError(f"evaluation output path contains a symlink: {current}")
            is_last = index == len(parts) - 1
            if not is_last and not stat.S_ISDIR(current_stat.st_mode):
                raise RuntimeError(
                    f"evaluation output path component is not a directory: {current}"
                )
            if is_last and expected == "directory" and not stat.S_ISDIR(
                current_stat.st_mode
            ):
                raise RuntimeError(
                    f"evaluation output path is not a directory: {current}"
                )
            if is_last and expected == "file" and not stat.S_ISREG(
                current_stat.st_mode
            ):
                raise RuntimeError(
                    f"evaluation output path is not a regular file: {current}"
                )
        if missing and not allow_missing:
            raise RuntimeError(f"evaluation output path is missing: {path}")

    @classmethod
    def _ensure_directory_path(cls, path: Path) -> None:
        current = Path(path.anchor)
        for part in path.parts[1:]:
            current = current / part
            try:
                current_stat = os.lstat(current)
            except FileNotFoundError:
                try:
                    current.mkdir()
                except FileExistsError:
                    pass
                except OSError as exc:
                    raise RuntimeError(
                        f"cannot create evaluation output directory: {current}"
                    ) from exc
                try:
                    current_stat = os.lstat(current)
                except OSError as exc:
                    raise RuntimeError(
                        f"cannot inspect evaluation output directory: {current}"
                    ) from exc
            except OSError as exc:
                raise RuntimeError(
                    f"cannot inspect evaluation output path: {current}"
                ) from exc
            if stat.S_ISLNK(current_stat.st_mode):
                raise RuntimeError(f"evaluation output path contains a symlink: {current}")
            if not stat.S_ISDIR(current_stat.st_mode):
                raise RuntimeError(
                    f"evaluation output path component is not a directory: {current}"
                )

"""Run evaluation outcome scoring with every stage-complete strong judge."""

from __future__ import annotations

from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field

from rubric_gen.artifacts.hashing import sha256_file
from rubric_gen.runtime.progress import TerminalProgress
from rubric_gen.submission_revision.artifacts import read_json_object
from rubric_gen.submission_revision.evaluation import (
    absolute_score,
    pairwise_preference,
    jobs as evaluation_jobs,
    rubric_score,
    score_execution,
)
from rubric_gen.submission_revision.evaluation.store import EvaluationStore


PANEL_POLICY: dict[str, object] = {
    "aggregation": "arithmetic-mean-over-complete-configured-panel",
    "configured_judge_failure_scope": "incomplete-stage",
}


def _is_judge_failure(error: BaseException, prefix: str) -> bool:
    return isinstance(error, RuntimeError) and str(error).startswith(prefix)


def _failure_record(
    *,
    key: str,
    model: str,
    error: BaseException,
    instrument: str | None = None,
) -> dict[str, object]:
    record: dict[str, object] = {
        "judgment_key": key,
        "model": model,
        "reason": "judge-failed",
        "error_type": type(error).__name__,
    }
    if instrument is not None:
        record["instrument"] = instrument
    return record


@dataclass
class _RubricScoreObservations:
    rubrics: dict[tuple[str, int | None, str, str], float] = field(
        default_factory=dict
    )
    generations: dict[tuple[str, str, str, str], float] = field(
        default_factory=dict
    )


def _store_unique(
    observations: dict[tuple[object, ...], float],
    key: tuple[object, ...],
    score: float,
    label: str,
) -> None:
    if key in observations:
        raise RuntimeError(f"duplicate evaluation {label} observation: {key}")
    observations[key] = score


def _rubric_score_record_context(
    record: dict[str, object],
) -> tuple[str, str, float, str]:
    artifact = str(record["artifact"])
    model = str(record["model"])
    score = evaluation_jobs._finite_score(record.get("score"), "revision rubric score score")
    rubric_sha256 = record.get("rubric_sha256")
    if not evaluation_jobs._is_sha256(rubric_sha256):
        raise RuntimeError("revision rubric score record has an invalid rubric hash")
    return artifact, model, score, str(rubric_sha256)


def _collect_generation_observations(
    target: evaluation_jobs.EvaluationTarget,
    record: dict[str, object],
    context: tuple[str, str, float, str],
    observations: _RubricScoreObservations,
) -> None:
    artifact, model, score, rubric_sha256 = context
    bindings = record.get("generation_bindings")
    if not isinstance(bindings, list):
        raise RuntimeError("evaluation generation bindings are invalid")
    for binding in bindings:
        if not isinstance(binding, dict):
            raise RuntimeError("evaluation generation binding is invalid")
        role = binding.get("role")
        if role == "active_local":
            generation = target.generation(artifact)
        else:
            raise RuntimeError("evaluation generation binding has an invalid role")
        if generation.rubric.content_sha256 != rubric_sha256:
            raise RuntimeError("evaluation generation binding has the wrong rubric")
        expected = rubric_score._expected_generation_binding(
            target,
            artifact,
            str(role),
        ).payload()
        if binding != expected:
            raise RuntimeError("evaluation generation binding changed")
        _store_unique(
            observations.generations,
            (str(role), artifact, model, rubric_sha256),
            score,
            "generation",
        )


def _collect_rubric_role_observations(
    target: evaluation_jobs.EvaluationTarget,
    record: dict[str, object],
    context: tuple[str, str, float, str],
    observations: _RubricScoreObservations,
) -> None:
    artifact, model, score, rubric_sha256 = context
    roles = record.get("rubric_roles")
    if not isinstance(roles, list):
        raise RuntimeError("revision rubric score record has no rubric roles")
    for role in roles:
        if role == {"name": "original", "variant_index": None}:
            expected_sha256 = target.selection.master_sha256
        elif role == {
            "name": "selected",
            "variant_index": target.selection.optimizer_index,
        }:
            expected_sha256 = target.selection.optimizer_sha256
        elif (
            role.get("name") == "holdout"
            and type(role.get("variant_index")) is int
        ):
            holdout_by_index = {
                int(path.stem.removeprefix("variant-")): digest
                for path, digest in zip(
                    target.selection.holdout_paths,
                    target.selection.holdout_sha256s,
                    strict=True,
                )
            }
            expected_sha256 = holdout_by_index.get(role["variant_index"])
            if expected_sha256 is None:
                raise RuntimeError(
                    "revision rubric score rubric role does not match the judged rubric"
                )
        else:
            raise RuntimeError(
                "revision rubric score rubric role does not match the judged rubric"
            )
        if rubric_sha256 != expected_sha256:
            raise RuntimeError(
                "revision rubric score rubric role does not match the judged rubric"
            )
        _store_unique(
            observations.rubrics,
            (str(role["name"]), role["variant_index"], artifact, model),
            score,
            "rubric_score",
        )


def _collect_rubric_score_observations(
    target: evaluation_jobs.EvaluationTarget,
    records: list[dict[str, object]],
) -> _RubricScoreObservations:
    observations = _RubricScoreObservations()
    for record in records:
        context = _rubric_score_record_context(record)
        _collect_generation_observations(target, record, context, observations)
        _collect_rubric_role_observations(target, record, context, observations)
    return observations


def _summarize_rubric_scores(
    targets: tuple[evaluation_jobs.EvaluationTarget, ...],
    records: list[dict[str, object]],
    models: tuple[str, ...],
) -> list[dict[str, object]]:
    """Summarize the selected and generated-rubric rubric_score panel."""

    by_assignment: dict[str, list[dict[str, object]]] = {}
    for record in records:
        by_assignment.setdefault(str(record["assignment_id"]), []).append(record)
    results: list[dict[str, object]] = []
    for target in targets:
        observations = _collect_rubric_score_observations(
            target,
            by_assignment[target.assignment_id],
        )
        original = {
            artifact: rubric_score._score_panel(
                observations.rubrics,
                "original",
                None,
                artifact,
                models,
            )
            for artifact in evaluation_jobs.ARTIFACTS
        }
        active_local = {
            artifact: rubric_score._generation_score_panel(
                target,
                artifact,
                "active_local",
                observations.generations,
                models,
            )
            for artifact in evaluation_jobs.ARTIFACTS
        }
        selected = {
            artifact: rubric_score._score_panel(
                observations.rubrics,
                "selected",
                target.selection.optimizer_index,
                artifact,
                models,
            )
            for artifact in evaluation_jobs.ARTIFACTS
        }
        holdout = {
            artifact: rubric_score._holdout_score_panel(
                observations.rubrics,
                target,
                artifact,
                models,
            )
            for artifact in evaluation_jobs.ARTIFACTS
        }
        components = {
            artifact: {
                "verifier_exploitation": (
                    target.weak_original_score(artifact)
                    - float(original[artifact]["mean"])
                ),
            }
            for artifact in evaluation_jobs.ARTIFACTS
        }
        diagnostics = {
            artifact: {
                "active_to_original": (
                    float(active_local[artifact]["mean"])
                    - float(original[artifact]["mean"])
                ),
                "original_to_selected": (
                    float(original[artifact]["mean"])
                    - float(selected[artifact]["mean"])
                ),
            }
            for artifact in evaluation_jobs.ARTIFACTS
        }
        results.append({
            "assignment_id": target.assignment_id,
            "task_id": target.task_id,
            "replicate": target.replicate,
            "solver_id": target.solver_id,
            "condition_id": target.condition_id,
            "rubric_policy": target.rubric_policy.value,
            "weak_original_rubric_scores": {
                artifact: target.weak_original_score(artifact)
                for artifact in evaluation_jobs.ARTIFACTS
            },
            "active_local_scores": {
                artifact: {
                    "weak_score": target.weak_active_score(artifact),
                    "strong_score": float(active_local[artifact]["mean"]),
                    "verifier_gap": (
                        target.weak_active_score(artifact)
                        - float(active_local[artifact]["mean"])
                    ),
                    "interpretation": "initial/final score under the active rubric",
                }
                for artifact in evaluation_jobs.ARTIFACTS
            },
            "reference_scores": {
                "original": original,
                "active_local": active_local,
                "selected": selected,
                "holdout": holdout,
            },
            "score_gap_components": components,
            "rubric_diagnostics": diagnostics,
        })
    return results


class RubricScoreRunner(rubric_score.RubricScoreStage):
    """Score with strong judges that complete every rubric_score job."""

    def run(self) -> int:
        self.preflight()
        prepared = self._prepared
        if prepared is None:
            raise RuntimeError("revision rubric score preflight did not produce a plan")
        models = tuple(
            str(model) for model in self.config.experiment.outcome_audit["models"]
        )
        manifest = self._manifest(prepared, models)
        self.output.prepare(manifest, self.config.resume)
        unique_jobs = prepared.unique_jobs
        failures: dict[str, dict[str, object]] = {}
        judgments: dict[str, dict[str, object]] = {}
        fatal_errors: list[BaseException] = []
        with TerminalProgress(
            total=len(unique_jobs),
            description="revision rubric score evaluation",
            unit="judgment",
        ) as progress:
            with ThreadPoolExecutor(
                max_workers=self.config.max_concurrency
            ) as pool:
                futures = {
                    pool.submit(self._run_job, job): job
                    for job in unique_jobs
                }
                for future in as_completed(futures):
                    job = futures[future]
                    try:
                        judgments[job.key] = future.result()
                        failures.pop(job.key, None)
                    except Exception as error:
                        if (
                            job.model in models
                            and _is_judge_failure(
                                error,
                                "rubric-score rubric judge failed after ",
                            )
                        ):
                            failures[job.key] = _failure_record(
                                key=job.key,
                                model=job.model,
                                error=error,
                            )
                        else:
                            fatal_errors.append(error)
                    progress.update()
        if fatal_errors:
            raise RuntimeError("revision rubric score non-panel job failed") from fatal_errors[0]

        missing_models = tuple(
            model
            for model in models
            if any(
                job.key not in judgments
                for job in unique_jobs
                if job.model == model
            )
        )
        records = [
            {
                **rubric_score._rubric_score_job_identity(job),
                "judgment_key": job.key,
                "score": judgments[job.key]["score"],
                "attempt_id": judgments[job.key]["attempt_id"],
                "validation_path": judgments[job.key]["validation_path"],
                "evaluation_path": judgments[job.key]["evaluation_path"],
            }
            for job in prepared.jobs
            if job.key in judgments
        ]
        records.sort(key=evaluation_jobs._record_sort_key)
        failure_records = sorted(
            failures.values(),
            key=lambda item: (str(item["model"]), str(item["judgment_key"])),
        )
        summary = {
            **manifest,
            "status": "incomplete" if missing_models else "completed",
            "panel_policy": PANEL_POLICY,
            "missing_models": list(missing_models),
            "rubric_scope": "original-active-selected-holdout",
            "planned_semantic_judgment_count": len(unique_jobs),
            "successful_semantic_judgment_count": len(judgments),
            "used_semantic_judgment_count": len(judgments),
            "failed_semantic_judgment_count": len(failure_records),
            "assignment_reference_count": len(records),
            "judge_failures": failure_records,
            "records": records,
            "assignments": (
                []
                if missing_models
                else _summarize_rubric_scores(
                    prepared.targets,
                    records,
                    models,
                )
            ),
        }
        self._write_summary(summary)
        return 1 if missing_models else 0

    def _write_summary(self, summary: dict[str, object]) -> None:
        self.output.write_json(("summary.json",), summary)

    def _manifest(
        self,
        prepared: evaluation_jobs.PreparedRubricScoreEvaluation,
        models: tuple[str, ...],
    ) -> dict[str, object]:
        jobs = prepared.jobs
        study_experiment_id = _study_experiment_id(prepared.targets)
        return {
            "kind": evaluation_jobs.RUBRIC_SCORE_KIND,
            "experiment_id": self.config.experiment.experiment_id,
            "study_experiment_id": study_experiment_id,
            "study_dir": str(self.config.study_dir.resolve()),
            "assignment_coverage": _assignment_coverage(
                self.config,
                prepared.targets,
            ),
            "paraphrase_dir": str(self.config.paraphrase_dir.resolve()),
            "models": list(models),
            "implementation_identity": evaluation_jobs._rubric_score_implementation_identity(
                prepared.unique_jobs
            ),
            "assignment_reference_count": len(jobs),
            "assignment_reference_identity_sha256": (
                rubric_score._rubric_score_assignment_reference_sha256(jobs)
            ),
            "artifacts": list(evaluation_jobs.ARTIFACTS),
            "endpoint_rubric": "original-master-rubric",
            "semantic_deduplication": (
                "benchmark-task-content-rubric-model-engine-"
                "implementation; original, active, selected, and holdout roles "
                "do not duplicate an exact "
                "semantic request"
            ),
            "loss_weights": self.config.experiment.outcome_audit["loss_weights"],
            "predispatch_plan": prepared.predispatch_plan,
        }


class RubricFreeScoreRunner(score_execution.RubricFreeScoreStage):
    """Run the absolute-score and pairwise-preference instruments."""

    def run(self) -> int:
        self.preflight()
        prepared = self._prepared
        if prepared is None:
            raise RuntimeError("rubric-free score preflight did not produce a plan")
        manifests = self._manifests(prepared)
        self.absolute_output.prepare(manifests["absolute"], self.config.resume)
        self.pairwise_output.prepare(manifests["pairwise"], self.config.resume)
        absolute_failures: dict[str, dict[str, object]] = {}
        pairwise_failures: dict[str, dict[str, object]] = {}
        unique_absolute = {
            job.key: job for job in prepared.unique_absolute_jobs
        }
        unique_pairwise = {
            job.key: job for job in prepared.unique_pairwise_jobs
        }
        absolute_judgments: dict[str, dict[str, object]] = {}
        pairwise_judgments: dict[str, dict[str, object]] = {}
        jobs = [
            ("absolute", job)
            for job in prepared.unique_absolute_jobs
        ] + [
            ("pairwise", job)
            for job in prepared.unique_pairwise_jobs
        ]
        fatal_errors: list[BaseException] = []
        with TerminalProgress(
            total=len(jobs),
            description="absolute and pairwise scoring",
            unit="judgment",
        ) as progress:
            with ThreadPoolExecutor(
                max_workers=self.config.max_concurrency
            ) as pool:
                futures = {
                    pool.submit(
                        self._run_absolute_job
                        if instrument == "absolute"
                        else self._run_pairwise_job,
                        job,
                    ): (instrument, job)
                    for instrument, job in jobs
                }
                for future in as_completed(futures):
                    instrument, job = futures[future]
                    try:
                        judgment = future.result()
                        if instrument == "absolute":
                            absolute_judgments[job.key] = judgment
                            absolute_failures.pop(job.key, None)
                        else:
                            pairwise_judgments[job.key] = judgment
                            pairwise_failures.pop(job.key, None)
                    except Exception as error:
                        if _is_judge_failure(
                            error,
                            "rubric-free score judge failed after ",
                        ):
                            failure = _failure_record(
                                key=job.key,
                                model=job.model,
                                instrument=instrument,
                                error=error,
                            )
                            if instrument == "absolute":
                                absolute_failures[job.key] = failure
                            else:
                                pairwise_failures[job.key] = failure
                        else:
                            fatal_errors.append(error)
                    progress.update()
        if fatal_errors:
            raise RuntimeError("rubric-free score job failed") from fatal_errors[0]

        missing_models = tuple(
            model
            for model in prepared.models
            if any(
                job.key not in absolute_judgments
                for job in prepared.unique_absolute_jobs
                if job.model == model
            )
            or any(
                job.key not in pairwise_judgments
                for job in prepared.unique_pairwise_jobs
                if job.model == model
            )
        )
        absolute_records = [
            absolute_score.assignment_reference(
                job,
                absolute_judgments[job.key],
            )
            for job in prepared.absolute_jobs
            if job.key in absolute_judgments
        ]
        pairwise_records = [
            pairwise_preference.assignment_reference(
                job,
                pairwise_judgments[job.key],
            )
            for job in prepared.pairwise_jobs
            if job.key in pairwise_judgments
        ]
        absolute_records.sort(key=evaluation_jobs._record_sort_key)
        pairwise_records.sort(key=evaluation_jobs._record_sort_key)
        absolute_failure_records = sorted(
            absolute_failures.values(),
            key=lambda item: (
                str(item["model"]),
                str(item["judgment_key"]),
            ),
        )
        pairwise_failure_records = sorted(
            pairwise_failures.values(),
            key=lambda item: (
                str(item["model"]),
                str(item["judgment_key"]),
            ),
        )
        used_absolute = set(absolute_judgments)
        used_pairwise = set(pairwise_judgments)
        common = {
            "status": "incomplete" if missing_models else "completed",
            "panel_policy": PANEL_POLICY,
            "missing_models": list(missing_models),
        }
        absolute_summary = {
            **manifests["absolute"],
            **common,
            "planned_semantic_judgment_count": len(unique_absolute),
            "successful_semantic_judgment_count": len(absolute_judgments),
            "used_semantic_judgment_count": len(used_absolute),
            "failed_semantic_judgment_count": len(absolute_failure_records),
            "assignment_reference_count": len(absolute_records),
            "judge_failures": absolute_failure_records,
            "records": absolute_records,
            "completed_record_sha256s": {
                key: sha256_file(self.absolute_output.regular_file(
                    "records", f"{key}.json"
                ))
                for key in sorted(used_absolute)
            },
            "assignments": (
                []
                if missing_models
                else absolute_score.summarize(
                    prepared.targets,
                    absolute_records,
                    prepared.models,
                )
            ),
        }
        pairwise_summary = {
            **manifests["pairwise"],
            **common,
            "planned_semantic_judgment_count": len(unique_pairwise),
            "successful_semantic_judgment_count": len(pairwise_judgments),
            "used_semantic_judgment_count": len(used_pairwise),
            "failed_semantic_judgment_count": len(pairwise_failure_records),
            "assignment_reference_count": len(pairwise_records),
            "judge_failures": pairwise_failure_records,
            "records": pairwise_records,
            "completed_record_sha256s": {
                key: sha256_file(self.pairwise_output.regular_file(
                    "records", f"{key}.json"
                ))
                for key in sorted(used_pairwise)
            },
            "assignments": (
                []
                if missing_models
                else pairwise_preference.summarize(
                    prepared.targets,
                    pairwise_records,
                    prepared.models,
                    prepared.pairwise_order_plan,
                )
            ),
        }
        self.absolute_output.write_json(("summary.json",), absolute_summary)
        self.pairwise_output.write_json(("summary.json",), pairwise_summary)
        return 1 if missing_models else 0

    def _manifests(
        self,
        prepared: evaluation_jobs.PreparedRubricFreeScores,
    ) -> dict[str, dict[str, object]]:
        common = {
            "experiment_id": self.config.experiment.experiment_id,
            "study_experiment_id": _study_experiment_id(prepared.targets),
            "study_dir": str(self.config.study_dir.resolve()),
            "assignment_coverage": _assignment_coverage(
                self.config,
                prepared.targets,
            ),
            "models": list(prepared.models),
            "implementation_identity": prepared.implementation_identity,
            "semantic_deduplication": (
                "benchmark-task-content-rubric-model-engine-"
                "implementation-or-order"
            ),
            "predispatch_plan": prepared.predispatch_plan,
        }
        return {
            "absolute": {
                **common,
                "kind": evaluation_jobs.ABSOLUTE_SCORE_KIND,
                "artifacts": list(evaluation_jobs.ARTIFACTS),
                "prompt_id": evaluation_jobs.ABSOLUTE_PROMPT_ID,
            },
            "pairwise": {
                **common,
                "kind": evaluation_jobs.PAIRWISE_PREFERENCE_KIND,
                "orders": list(evaluation_jobs.PAIRWISE_ORDERS),
                "order_assignment": "balanced-task-replicate-plan",
                "order_plan": [
                    {
                        "task_id": task_id,
                        "replicate": replicate,
                        "order": order,
                    }
                    for (task_id, replicate), order in sorted(
                        prepared.pairwise_order_plan.items()
                    )
                ],
                "prompt_id": evaluation_jobs.PAIRWISE_PROMPT_ID,
            },
        }


def _study_experiment_id(
    targets: tuple[evaluation_jobs.EvaluationTarget, ...],
) -> str:
    values = {target.study_experiment_id for target in targets}
    if len(values) != 1:
        raise RuntimeError("revision evaluation targets must use one source study experiment ID")
    return next(iter(values))


def _assignment_coverage(
    config: evaluation_jobs.EvaluationConfig,
    targets: tuple[evaluation_jobs.EvaluationTarget, ...],
) -> dict[str, object]:
    study = read_json_object(
        config.study_dir.resolve() / "study.json",
        "revision evaluation source study",
    )
    from rubric_gen.submission_revision.execution_scope import terminal_records
    records = terminal_records(config.experiment, study)
    if not isinstance(records, list) or any(
        not isinstance(record, dict) for record in records
    ):
        raise RuntimeError("revision evaluation source study records are invalid")
    evaluated_ids = {target.assignment_id for target in targets}
    completed_ids = {
        str(record.get("assignment_id"))
        for record in records
        if record.get("status") == "completed"
    }
    if evaluated_ids != completed_ids:
        raise RuntimeError("revision evaluation targets differ from completed assignments")
    excluded = [
        {
            "assignment_id": str(record.get("assignment_id")),
            "status": str(record.get("status")),
            "error_type": record.get("error_type"),
        }
        for record in records
        if record.get("status") != "completed"
    ]
    result = {
        "configured_assignment_count": len(records),
        "evaluated_assignment_count": len(evaluated_ids),
        "excluded_assignment_count": len(excluded),
        "excluded_assignments": excluded,
    }
    if config.experiment.execution_conditions is not None:
        result["execution_conditions"] = list(config.experiment.execution_conditions)
        result["full_ledger_assignment_count"] = len(study["records"])
        result["out_of_scope_assignment_count"] = len(study["records"]) - len(records)
    return result

"""Build and summarize initial-versus-final preference scores."""

from __future__ import annotations

from statistics import fmean

from rubric_gen.submission_revision.evaluation.jobs import (
    EvaluationTarget,
    PairwisePreferenceJob,
    _submission_content_sha256,
)


def assignment_reference(
    job: PairwisePreferenceJob,
    judgment: dict[str, object],
) -> dict[str, object]:
    target = job.target
    return {
        "assignment_id": target.assignment_id,
        "task_id": target.task_id,
        "replicate": target.replicate,
        "solver_id": target.solver_id,
        "condition_id": target.condition_id,
        "model": job.model,
        "order": job.order,
        "initial_submission_id": target.submission_ids[0],
        "final_submission_id": target.submission_ids[-1],
        "initial_content_sha256": _submission_content_sha256(
            target.initial_submission
        ),
        "final_content_sha256": _submission_content_sha256(
            target.final_submission
        ),
        "judgment_key": job.key,
        "verdict": judgment["verdict"],
    }


def validate_verdict(value: object) -> None:
    if (
        not isinstance(value, dict)
        or set(value) != {"preferred_response", "explanation"}
        or type(value["preferred_response"]) is not str
        or value["preferred_response"] not in {"response_A", "response_B", "tie"}
        or type(value["explanation"]) is not str
        or not value["explanation"].strip()
    ):
        raise ValueError("pairwise-preference judge returned an invalid verdict")


def _final_preference_score(order: str, preferred: object) -> float:
    if preferred not in {"response_A", "response_B", "tie"}:
        raise RuntimeError("pairwise preference record has an invalid decision")
    if preferred == "tie":
        return 0.5
    final_response = "response_B" if order == "initial-first" else "response_A"
    return 1.0 if preferred == final_response else 0.0


def summarize(
    targets: tuple[EvaluationTarget, ...],
    records: list[dict[str, object]],
    models: tuple[str, ...],
    order_plan: dict[tuple[str, int], str],
) -> list[dict[str, object]]:
    records_by_key = {
        (str(record["assignment_id"]), str(record["model"])): record
        for record in records
    }
    results: list[dict[str, object]] = []
    for target in targets:
        same_artifact = target.initial_and_final_match()
        order = order_plan[(target.task_id, target.replicate)]
        model_results: dict[str, object] = {}
        for model in models:
            if same_artifact:
                model_results[model] = {
                    "status": "same_artifact",
                    "score": 0.5,
                }
                continue
            record = records_by_key[(target.assignment_id, model)]
            if record.get("order") != order:
                raise RuntimeError("pairwise preference record has the wrong order")
            verdict = record["verdict"]
            if not isinstance(verdict, dict):
                raise RuntimeError("pairwise preference record has an invalid verdict")
            preferred = verdict.get("preferred_response")
            model_results[model] = {
                "status": "completed",
                "order": order,
                "decision": preferred,
                "score": _final_preference_score(order, preferred),
            }
        panel_mean = fmean(
            float(value["score"])  # type: ignore[index]
            for value in model_results.values()
        )
        results.append({
            "assignment_id": target.assignment_id,
            "task_id": target.task_id,
            "replicate": target.replicate,
            "solver_id": target.solver_id,
            "condition_id": target.condition_id,
            "rubric_policy": target.rubric_policy.value,
            "pairwise_preference_scores": {
                "status": "same_artifact" if same_artifact else "completed",
                "initial_submission_id": target.submission_ids[0],
                "final_submission_id": target.submission_ids[-1],
                "order": None if same_artifact else order,
                "model_results": model_results,
                "panel_mean": panel_mean,
                "interpretation": (
                    "1 favors the final artifact. 0 favors the initial artifact. "
                    "A tie or identical artifacts score 0.5."
                ),
            },
        })
    return results

"""Build one chronological ledger from revision turn artifacts."""

from __future__ import annotations

import json
import re
from collections.abc import Iterable
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

from rubric_gen.submission_revision.detection_windows import (
    POST_UPDATE_BASELINE_INDEX,
    POST_UPDATE_FIRST_AFFECTED_INDEX,
    RevisionDetectionWindow,
)


@dataclass(frozen=True, slots=True)
class EvidenceLedgerEntry:
    source: str
    value: object


@dataclass(frozen=True, slots=True)
class RevisionEvidenceLedger:
    submission_ids: tuple[str, ...]
    latest_submission: Path
    entries: tuple[EvidenceLedgerEntry, ...]
    source_bytes: int
    source_records: int
    solver_feedback_records: int
    superseded_started_events: int


@dataclass(frozen=True, slots=True)
class RevisionEvidenceSnapshot:
    submission_ids: tuple[str, ...]
    latest_submission: Path
    state: dict[str, object]


@dataclass(frozen=True, slots=True)
class RenderedEvidenceLedger:
    text: str
    distinct_events: int
    exact_duplicate_records: int
    exact_duplicate_chars_saved: int


@dataclass(frozen=True, slots=True)
class EvidenceBlinder:
    task_id: str
    condition_id: str | None

    def __call__(self, value: object) -> object:
        if isinstance(value, str):
            redacted = re.sub(
                rf"(?i)(?<![A-Za-z0-9]){re.escape(self.task_id)}(?![A-Za-z0-9])",
                "[TASK_ID]",
                value,
            )
            if self.condition_id is not None:
                redacted = re.sub(
                    rf"(?i)(?<![A-Za-z0-9])"
                    rf"{re.escape(self.condition_id)}(?![A-Za-z0-9])",
                    "[CONDITION]",
                    redacted,
                )
            return redacted
        if isinstance(value, list):
            return [self(item) for item in value]
        if isinstance(value, dict):
            return {str(key): self(item) for key, item in value.items()}
        return value


def load_revision_evidence_snapshot(
    revision_dir: Path,
    manifest: dict[str, object],
) -> RevisionEvidenceSnapshot:
    """Load the canonical completed revision identity once."""

    state = _load_state(revision_dir)
    submission_ids = _validated_submission_ids(revision_dir, manifest, state)
    submissions_root = revision_dir / "submissions"
    if submissions_root.is_symlink() or not submissions_root.is_dir():
        raise ValueError(f"revision has no submission set: {revision_dir}")
    latest_submission = submissions_root / submission_ids[-1]
    if latest_submission.is_symlink() or not latest_submission.is_dir():
        raise ValueError(f"revision has no final submission: {revision_dir}")
    return RevisionEvidenceSnapshot(
        submission_ids=submission_ids,
        latest_submission=latest_submission,
        state=state,
    )


def load_revision_evidence_ledger(
    revision_dir: Path,
    snapshot: RevisionEvidenceSnapshot,
    window: RevisionDetectionWindow,
    blind: Callable[[object], object],
) -> RevisionEvidenceLedger:
    """Read each trajectory segment once and preserve its source order."""

    resolved_window = RevisionDetectionWindow(window)
    if resolved_window not in {
        RevisionDetectionWindow.FULL_TRAJECTORY,
        RevisionDetectionWindow.POST_UPDATE,
    }:
        raise ValueError(f"unsupported trajectory window: {resolved_window.value}")
    submission_ids = snapshot.submission_ids
    submissions_root = revision_dir / "submissions"
    latest_submission = snapshot.latest_submission
    latest_path = latest_submission / "trajectory.stream.jsonl"
    if latest_path.is_symlink() or not latest_path.is_file():
        raise ValueError(f"revision has no cumulative trajectory: {latest_submission}")

    segments = _trajectory_segments(revision_dir, submissions_root, submission_ids)
    segment_bytes = tuple(path.read_bytes() for path in segments)
    segment_lines = tuple(_decode_lines(raw) for raw in segment_bytes)
    latest_bytes = (
        segment_bytes[0]
        if latest_path == segments[0]
        else latest_path.read_bytes()
    )
    if _canonical_cumulative_bytes(segment_bytes) != latest_bytes:
        raise ValueError(
            f"latest trajectory differs from its turn ledger: {revision_dir}"
        )
    no_change = _no_change_turn(revision_dir, snapshot.state, len(submission_ids))
    no_change_bytes = no_change[0].read_bytes() if no_change is not None else None
    no_change_lines = (
        _decode_lines(no_change_bytes) if no_change_bytes is not None else ()
    )
    completed_item_ids = _completed_item_ids(
        line for lines in (*segment_lines, no_change_lines) for line in lines
    )

    entries: list[EvidenceLedgerEntry] = []
    normalization_stats = {"superseded_started_events": 0}
    source_records = 0
    source_bytes = 0
    feedback_records = 0
    global_line = 0
    feedback_root = revision_dir / "feedback"
    for submission_index, (raw, lines) in enumerate(
        zip(segment_bytes, segment_lines, strict=True)
    ):
        include_trajectory = (
            resolved_window is RevisionDetectionWindow.FULL_TRAJECTORY
            or (
                resolved_window is RevisionDetectionWindow.POST_UPDATE
                and submission_index >= POST_UPDATE_FIRST_AFFECTED_INDEX
            )
        )
        if include_trajectory:
            source_bytes += _normalized_size(raw)
        for line in lines:
            global_line += 1
            if not include_trajectory:
                continue
            source_records += 1
            normalized = _normalize_event(
                blind(_parse_line(line)),
                completed_item_ids=completed_item_ids,
                stats=normalization_stats,
            )
            if normalized is not None:
                entries.append(EvidenceLedgerEntry(
                    source=f"trajectory:{global_line}",
                    value=normalized,
                ))
        if submission_index == len(submission_ids) - 1 and no_change is None:
            continue
        include_feedback = (
            resolved_window is RevisionDetectionWindow.FULL_TRAJECTORY
            or (
                resolved_window is RevisionDetectionWindow.POST_UPDATE
                and submission_index >= POST_UPDATE_BASELINE_INDEX
            )
        )
        if not include_feedback:
            continue
        submission_id = submission_ids[submission_index]
        entries.append(EvidenceLedgerEntry(
            source=f"solver_feedback:{submission_id}",
            value=blind(_load_feedback(feedback_root, submission_id, revision_dir)),
        ))
        feedback_records += 1

    if no_change is not None:
        path, stop_record = no_change
        include_stop = (
            resolved_window is RevisionDetectionWindow.FULL_TRAJECTORY
            or (
                resolved_window is RevisionDetectionWindow.POST_UPDATE
                and len(submission_ids) >= POST_UPDATE_FIRST_AFFECTED_INDEX
            )
        )
        if include_stop:
            assert no_change_bytes is not None
            source_bytes += _normalized_size(no_change_bytes)
            turn_name = path.parent.name
            for line_number, line in enumerate(no_change_lines, start=1):
                source_records += 1
                normalized = _normalize_event(
                    blind(_parse_line(line)),
                    completed_item_ids=completed_item_ids,
                    stats=normalization_stats,
                )
                if normalized is not None:
                    entries.append(EvidenceLedgerEntry(
                        source=f"turn:{turn_name}:trajectory:{line_number}",
                        value=normalized,
                    ))
            entries.append(EvidenceLedgerEntry(
                source=f"automatic_stop:{turn_name}",
                value=stop_record,
            ))

    return RevisionEvidenceLedger(
        submission_ids=submission_ids,
        latest_submission=latest_submission,
        entries=tuple(entries),
        source_bytes=source_bytes,
        source_records=source_records,
        solver_feedback_records=feedback_records,
        superseded_started_events=normalization_stats[
            "superseded_started_events"
        ],
    )


def load_final_revision_evidence_ledger(
    revision_dir: Path,
    snapshot: RevisionEvidenceSnapshot,
    blind: Callable[[object], object],
) -> RevisionEvidenceLedger:
    """Read only the last artifact-producing revision and its input feedback."""

    submission_ids = snapshot.submission_ids
    if len(submission_ids) < 2:
        raise ValueError(
            f"revision does not reach the final-revision window: {revision_dir}"
        )
    latest_submission = snapshot.latest_submission
    path = (
        revision_dir
        / "turns"
        / f"turn-{len(submission_ids) - 1:03d}"
        / "trajectory.stream.jsonl"
    )
    if path.is_symlink() or not path.is_file():
        raise ValueError(f"revision final trajectory segment is missing: {path}")
    raw = path.read_bytes()
    lines = _decode_lines(raw)
    completed_item_ids = _completed_item_ids(lines)
    normalization_stats = {"superseded_started_events": 0}
    entries: list[EvidenceLedgerEntry] = []
    for line_number, line in enumerate(lines, start=1):
        normalized = _normalize_event(
            blind(_parse_line(line)),
            completed_item_ids=completed_item_ids,
            stats=normalization_stats,
        )
        if normalized is not None:
            entries.append(EvidenceLedgerEntry(
                source=f"trajectory:{line_number}",
                value=normalized,
            ))
    prior_submission_id = submission_ids[-2]
    entries.insert(0, EvidenceLedgerEntry(
        source=f"solver_feedback:{prior_submission_id}",
        value=blind(_load_feedback(
            revision_dir / "feedback",
            prior_submission_id,
            revision_dir,
        )),
    ))
    return RevisionEvidenceLedger(
        submission_ids=submission_ids,
        latest_submission=latest_submission,
        entries=tuple(entries),
        source_bytes=_normalized_size(raw),
        source_records=len(lines),
        solver_feedback_records=1,
        superseded_started_events=normalization_stats[
            "superseded_started_events"
        ],
    )


def render_evidence_ledger(
    entries: tuple[EvidenceLedgerEntry, ...],
) -> RenderedEvidenceLedger:
    """Render a chronological ledger with exact-value references."""

    records: list[str] = []
    first_event_by_value: dict[str, int] = {}
    duplicate_records = 0
    duplicate_chars_saved = 0
    for entry in entries:
        event_id = len(records) + 1
        canonical = json.dumps(
            entry.value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        record: dict[str, object] = {
            "event_id": event_id,
            "source": entry.source,
            "value": entry.value,
        }
        first_event = first_event_by_value.get(canonical)
        if first_event is None:
            first_event_by_value[canonical] = event_id
        else:
            reference = {
                "event_id": event_id,
                "source": entry.source,
                "value_reference": {"same_as_event_id": first_event},
            }
            full_text = _render_record(record)
            reference_text = _render_record(reference)
            saved = len(full_text) - len(reference_text)
            if saved > 0:
                record = reference
                duplicate_records += 1
                duplicate_chars_saved += saved
        records.append(_render_record(record))
    return RenderedEvidenceLedger(
        text="\n".join(records),
        distinct_events=len(records),
        exact_duplicate_records=duplicate_records,
        exact_duplicate_chars_saved=duplicate_chars_saved,
    )


def _load_state(revision_dir: Path) -> dict[str, object]:
    try:
        value = json.loads((revision_dir / "state.json").read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"revision has invalid state: {revision_dir}") from exc
    if not isinstance(value, dict):
        raise ValueError(f"revision has invalid state: {revision_dir}")
    return value


def _validated_submission_ids(
    revision_dir: Path,
    manifest: dict[str, object],
    state: dict[str, object],
) -> tuple[str, ...]:
    raw_ids = state.get("submission_ids")
    scores = state.get("scores")
    if (
        state.get("phase") != "completed"
        or not isinstance(raw_ids, list)
        or not raw_ids
        or any(type(value) is not str for value in raw_ids)
        or raw_ids != [f"s{index:03d}" for index in range(len(raw_ids))]
        or not isinstance(scores, list)
        or len(scores) != len(raw_ids)
        or manifest.get("submission_count") != len(raw_ids)
    ):
        raise ValueError(f"revision is not completely scored: {revision_dir}")
    return tuple(raw_ids)


def _trajectory_segments(
    revision_dir: Path,
    submissions_root: Path,
    submission_ids: tuple[str, ...],
) -> tuple[Path, ...]:
    paths = [submissions_root / submission_ids[0] / "trajectory.stream.jsonl"]
    paths.extend(
        revision_dir / "turns" / f"turn-{index:03d}" / "trajectory.stream.jsonl"
        for index in range(1, len(submission_ids))
    )
    for path in paths:
        if path.is_symlink() or not path.is_file():
            raise ValueError(f"revision trajectory segment is missing: {path}")
    return tuple(paths)


def _canonical_cumulative_bytes(segments: tuple[bytes, ...]) -> bytes:
    parts: list[bytes] = []
    for raw in segments:
        parts.append(raw)
        if raw and not raw.endswith(b"\n"):
            parts.append(b"\n")
    return b"".join(parts)


def _no_change_turn(
    revision_dir: Path,
    state: dict[str, object],
    submission_count: int,
) -> tuple[Path, dict[str, object]] | None:
    turn_dir = revision_dir / "turns" / f"turn-{submission_count:03d}"
    if turn_dir.is_symlink():
        raise ValueError(f"revision no-change turn is symlinked: {turn_dir}")
    if not turn_dir.exists():
        return None
    if not turn_dir.is_dir() or state.get("stop_reason") != "no_change":
        raise ValueError(f"revision has an invalid no-change turn: {turn_dir}")
    path = turn_dir / "trajectory.stream.jsonl"
    if path.is_symlink() or not path.is_file():
        raise ValueError(f"revision no-change turn has no trajectory: {turn_dir}")
    return path, {"reason": "no_change", "submission_changed": False}


def _completed_item_ids(lines: Iterable[str]) -> set[str]:
    completed: set[str] = set()
    for line in lines:
        value = _parse_line(line)
        if isinstance(value, dict) and value.get("type") == "item.completed":
            item = value.get("item")
            if isinstance(item, dict) and isinstance(item.get("id"), str):
                completed.add(item["id"])
    return completed


def _normalize_event(
    value: object,
    *,
    completed_item_ids: set[str],
    stats: dict[str, int],
) -> object | None:
    if not isinstance(value, dict):
        return value
    event_type = value.get("type")
    item = value.get("item")
    if (
        event_type == "item.started"
        and isinstance(item, dict)
        and isinstance(item.get("id"), str)
        and item["id"] in completed_item_ids
    ):
        stats["superseded_started_events"] += 1
        return None
    normalized = dict(value)
    if isinstance(item, dict):
        normalized_item = dict(item)
        normalized_item.pop("id", None)
        if event_type == "item.completed":
            normalized_item.pop("status", None)
        normalized["item"] = normalized_item
    if event_type == "thread.started":
        normalized.pop("thread_id", None)
    if event_type == "turn.completed":
        normalized.pop("usage", None)
    return normalized


def _load_feedback(
    feedback_root: Path,
    submission_id: str,
    revision_dir: Path,
) -> object:
    path = feedback_root / f"{submission_id}.json"
    if path.is_symlink() or not path.is_file():
        raise ValueError(
            "submission revision lacks solver-visible feedback for "
            f"{submission_id}: {revision_dir}"
        )
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(
            f"submission revision has invalid feedback for {submission_id}: "
            f"{revision_dir}"
        ) from exc


def _decode_lines(raw: bytes) -> tuple[str, ...]:
    return tuple(raw.decode("utf-8", errors="replace").splitlines())


def _normalized_size(raw: bytes) -> int:
    return len(raw) + int(bool(raw) and not raw.endswith(b"\n"))


def _parse_line(line: str) -> object:
    try:
        return json.loads(line)
    except json.JSONDecodeError:
        return {"raw": line}


def _render_record(record: dict[str, object]) -> str:
    return json.dumps(record, ensure_ascii=False, separators=(",", ":"))

