def pairwise_order_plan(
    targets: tuple[EvaluationTarget, ...],
) -> dict[tuple[str, int], str]:
    """Assign one balanced order to each task and replicate pair."""

    if not targets:
        raise RuntimeError("pairwise order planning requires evaluation targets")
    study_ids = {target.study_experiment_id for target in targets}
    if len(study_ids) != 1:
        raise RuntimeError("pairwise order planning requires one source study")
    study_id = next(iter(study_ids))
    cells = {(target.task_id, target.replicate) for target in targets}
    ordered = sorted(
        cells,
        key=lambda cell: hashlib.sha256(
            f"{study_id}\0{cell[0]}\0{cell[1]}".encode("utf-8")
        ).digest(),
    )
    return {
        cell: PAIRWISE_ORDERS[index % len(PAIRWISE_ORDERS)]
        for index, cell in enumerate(ordered)
    }



def _finite_score(value: object, label: str) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, Real)
        or not math.isfinite(float(value))
        or not 0 <= float(value) <= 100
    ):
        raise RuntimeError(f"{label} must be a finite score from 0 to 100")
    return float(value)


def _finite_number(value: object, label: str) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, Real)
        or not math.isfinite(float(value))
    ):
        raise RuntimeError(f"{label} must be a finite number")
    return float(value)


def _submission_content_sha256(submission: Path) -> str:
    snapshot = read_json_object(
        submission / "snapshot.json",
        "submission snapshot",
    )
    digest = snapshot.get("workspace_sha256")
    if not _is_sha256(digest):
        raise RuntimeError("submission snapshot has an invalid workspace hash")
    return str(digest)


def _is_sha256(value: object) -> bool:
    return (
        type(value) is str
        and len(value) == 64
        and all(character in "0123456789abcdef" for character in value)
    )


def _evaluation_implementation_sha256() -> str:
    implementation_files = (
        Path(__file__),
        Path(__file__).with_name("rubric_score.py"),
        Path(__file__).with_name("score_execution.py"),
        Path(__file__).with_name("absolute_score.py"),
        Path(__file__).with_name("pairwise_preference.py"),
        Path(__file__).parents[2] / "runtime" / "llm.py",
        Path(__file__).parents[2] / "runtime" / "integrations" / "gemini.py",
    )
    digest = hashlib.sha256()
    for path in implementation_files:
        digest.update(path.name.encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return digest.hexdigest()


def _rubric_free_score_implementation_identity() -> dict[str, str]:
    return {
        "scoring_implementation_sha256": _evaluation_implementation_sha256(),
    }


def _engine_release_identity(
    benchmark: SubmissionBenchmarkId,
) -> dict[str, object]:
    grading_engine_for_benchmark(benchmark)
    return dict(FULL_RUBRIC_ENGINE_IDENTITY)


def _rubric_score_implementation_identity(
    jobs: tuple[RubricScoreJob, ...],
) -> dict[str, object]:
    if not jobs:
        raise RuntimeError("revision rubric score stage has no jobs")
    fields = (
        "scoring_implementation_sha256",
        "benchmark",
        "grading_engine",
    )
    implementations: dict[str, dict[str, object]] = {}
    for job in jobs:
        implementation = {
            field: job.grading_identity.get(field) for field in fields
        }
        if (
            any(implementation[field] is None for field in fields)
            or not all(
                _is_sha256(implementation[field])
                for field in fields[:1]
            )
        ):
            raise RuntimeError("revision rubric score implementation identity is invalid")
        canonical = json.dumps(
            implementation,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        implementations.setdefault(canonical, implementation)
    evaluation_hashes = {job.evaluation_implementation_sha256 for job in jobs}
    benchmarks = {job.target.benchmark for job in jobs}
    if (
        len(evaluation_hashes) != 1
        or not _is_sha256(next(iter(evaluation_hashes)))
        or len(benchmarks) != 1
    ):
        raise RuntimeError("revision rubric score stage implementation changed")
    return {
        "evaluation_sha256": next(iter(evaluation_hashes)),
        "grading_implementations": [
            implementations[key] for key in sorted(implementations)
        ],
        "engine_release_identity": _engine_release_identity(
            next(iter(benchmarks))
        ),
    }


def _stage_caps(
    outcome_audit: dict[str, object],
    stage: str,
) -> dict[str, int]:
    names = {
        "calls": f"{stage}_max_calls",
        "request_bytes": f"{stage}_max_request_bytes",
        "output_tokens": f"{stage}_max_output_tokens",
    }
    caps: dict[str, int] = {}
    for resource, name in names.items():
        value = outcome_audit.get(name)
        if type(value) is not int or value < 1:
            raise RuntimeError(f"evaluation stage cap is invalid: {name}")
        caps[resource] = value
    return caps


def _accept_predispatch_plan(
    *,
    stage: str,
    base: dict[str, object],
    jobs: list[dict[str, object]],
    outer_attempt_limit: int,
    caps: dict[str, int],
) -> dict[str, object]:
    if type(outer_attempt_limit) is not int or outer_attempt_limit < 1:
        raise RuntimeError("evaluation outer attempt limit is invalid")
    if (
        type(base.get("dispatch_count")) is not int
        or base["dispatch_count"] != len(jobs)
        or type(base.get("grading_engine")) is not str
        or type(base.get("request_byte_measurement")) is not str
    ):
        raise RuntimeError(f"evaluation {stage} predispatch identity is invalid")
    base_totals: dict[str, int] = {}
    maximum_totals: dict[str, int] = {}
    for resource in ("calls", "request_bytes", "output_tokens"):
        value = base.get(resource)
        if type(value) is not int or value < 0:
            raise RuntimeError(f"evaluation {stage} predispatch plan is invalid: {resource}")
        base_totals[resource] = value
        maximum_totals[resource] = value * outer_attempt_limit
        if maximum_totals[resource] > caps[resource]:
            raise RuntimeError(
                f"evaluation {stage} predispatch {resource} exceeds its hard cap: "
                f"{maximum_totals[resource]} > {caps[resource]}"
            )
    return {
        "stage": stage,
        "accepted": True,
        "outer_attempt_limit": outer_attempt_limit,
        "caps": caps,
        "base_totals": base_totals,
        "maximum_totals": maximum_totals,
        "request_byte_measurement": base["request_byte_measurement"],
        "dispatch_count": base["dispatch_count"],
        "grading_engine": base["grading_engine"],
        "benchmark": base.get("benchmark"),
        "largest_request_bytes_per_call": base.get(
            "largest_request_bytes_per_call"
        ),
        "jobs": jobs,
    }


def _assert_accepted_job_plan(
    *,
    stage: str,
    plan: dict[str, object],
    current: dict[str, object],
) -> None:
    jobs = plan.get("jobs")
    if plan.get("accepted") is not True or not isinstance(jobs, list):
        raise RuntimeError(f"evaluation {stage} accepted dispatch plan is unavailable")
    matches = [
        item
        for item in jobs
        if isinstance(item, dict)
        and item.get("semantic_key") == current.get("semantic_key")
    ]
    if len(matches) != 1 or matches[0] != current:
        raise RuntimeError(
            f"evaluation {stage} request changed after stage preflight"
        )


def _record_sort_key(record: dict[str, object]) -> tuple[str, ...]:
    return tuple(str(record.get(key, "")) for key in (
        "assignment_id", "artifact", "model", "rubric_sha256", "order"
    ))


def _rubric_score_plan_entry(
    *,
    job: RubricScoreJob,
    judge: FrozenRubricJudge,
