        "task_id": job.target.task_id,
        "task_instruction_sha256": sha256_file(
            job.target.task_dir / "instruction.md"
        ),
        "submission_content_sha256": _submission_content_sha256(job.submission),
        "rubric_sha256": sha256_file(job.rubric_path),
        "model": job.model,
        "engine": grading_engine_for_benchmark(job.target.benchmark).value,
        "grading_identity": job.grading_identity,
        "review_input_sha256": job.review_input_sha256,
        "answer_input_sha256": job.answer_input_sha256,
        "engine_release_identity": _engine_release_identity(
            job.target.benchmark
        ),
        "evaluation_implementation_sha256": job.evaluation_implementation_sha256,
        "review": job.target.review,
        "max_review_chars": job.target.max_review_chars,
    }



def _rubric_free_absolute_score_request(job: RubricFreeAbsoluteScoreJob) -> StructuredRequest:
    target = job.target
    instruction = (target.task_dir / "instruction.md").read_text(encoding="utf-8")
    evidence = json.dumps(
        {
            "response": _rubric_free_review_material(target, job.submission),
            "task_instruction": instruction,
        },
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    )
    return StructuredRequest(
        instructions=_RUBRIC_FREE_ABSOLUTE_SCORE_INSTRUCTIONS,
        evidence=evidence,
        schema_name="rubric_free_absolute_artifact_quality",
        schema=_ABSOLUTE_SCHEMA,
        max_output_tokens=2_048,
    )


def _pairwise_preference_request(
    job: PairwisePreferenceJob,
) -> StructuredRequest:
    target = job.target
    if job.order == "initial-first":
        first = _rubric_free_review_material(target, target.initial_submission)
        second = _rubric_free_review_material(target, target.final_submission)
    elif job.order == "final-first":
        first = _rubric_free_review_material(target, target.final_submission)
        second = _rubric_free_review_material(target, target.initial_submission)
    else:
        raise ValueError(f"invalid pairwise order: {job.order}")
    instruction = (target.task_dir / "instruction.md").read_text(encoding="utf-8")
    evidence = json.dumps(
        {
            "response_A": first,
            "response_B": second,
            "task_instruction": instruction,
        },
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    )
    return StructuredRequest(
        instructions=_PAIRWISE_INSTRUCTIONS,
        evidence=evidence,
        schema_name="rubric_free_pairwise_artifact_preference",
        schema=_PAIRWISE_SCHEMA,
        max_output_tokens=2_048,
    )


def _rubric_free_review_material(
    target: EvaluationTarget,
    submission: Path,
) -> str:
    benchmark = get_submission_benchmark(target.benchmark)
    workspace = submission / "workspace"
    if target.review == "workspace":
        return benchmark.render_workspace_review(target.task_dir, workspace)
    evidence = benchmark.final_evidence(workspace)
    if not evidence:
        raise ValueError(
            f"{target.benchmark.value} submission has no final evidence: "
            f"{submission}"
        )
    parts = ["# Exact submitted files"]
    for artifact in evidence:
        parts.append(
            f"## Exact submitted file: /app/{artifact.artifact}\n\n"
            f"{artifact.content}"
        )
    return "\n\n".join(parts)


def _prompt_sha256(request: StructuredRequest) -> str:
    return sha256_text(json.dumps(
        {
            "instructions": request.instructions,
            "evidence": request.evidence,
            "schema_name": request.schema_name,
            "schema": request.schema,
            "max_output_tokens": request.max_output_tokens,
        },
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ))


def _semantic_judgment_key(identity: dict[str, object]) -> str:
    return hashlib.sha256(
        json.dumps(identity, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()[:32]


def _absolute_judgment_identity(
    job: RubricFreeAbsoluteScoreJob,
    request: StructuredRequest,
) -> dict[str, object]:
    return {
        "instrument": "rubric-free-absolute",
        "prompt_id": ABSOLUTE_PROMPT_ID,
        "benchmark": job.target.benchmark.value,
        "task_id": job.target.task_id,
        "task_instruction_sha256": sha256_file(
            job.target.task_dir / "instruction.md"
        ),
        "submission_content_sha256": _submission_content_sha256(job.submission),
        "rubric_sha256": None,
        "model": job.model,
        "engine": "structured-generation",
        "implementation_identity": job.implementation_identity,
        "review": job.target.review,
        "max_review_chars": job.target.max_review_chars,
        "prompt_sha256": _prompt_sha256(request),
    }


def _pairwise_judgment_identity(
    job: PairwisePreferenceJob,
    request: StructuredRequest,
) -> dict[str, object]:
    if job.order == "initial-first":
        first = job.target.initial_submission
        second = job.target.final_submission
    elif job.order == "final-first":
        first = job.target.final_submission
        second = job.target.initial_submission
    else:
        raise ValueError(f"invalid pairwise order: {job.order}")
    return {
        "instrument": "rubric-free-pairwise-preference",
        "prompt_id": PAIRWISE_PROMPT_ID,
        "benchmark": job.target.benchmark.value,
        "task_id": job.target.task_id,
        "task_instruction_sha256": sha256_file(
            job.target.task_dir / "instruction.md"
        ),
        "response_A_content_sha256": _submission_content_sha256(first),
        "response_B_content_sha256": _submission_content_sha256(second),
        "rubric_sha256": None,
        "model": job.model,
        "engine": "structured-generation",
        "implementation_identity": job.implementation_identity,
        "order": job.order,
        "review": job.target.review,
        "max_review_chars": job.target.max_review_chars,
        "prompt_sha256": _prompt_sha256(request),
    }

"""Identify binary panel outcomes and bounds with missing decisions."""

from __future__ import annotations

from collections.abc import Mapping, Sequence


PANEL_RULES = frozenset({"majority", "any_detect", "unanimous_detects"})


def detection_bounds(
    *,
    decisions: Mapping[str, str],
    models: Sequence[str],
    positive_decision: str,
    negative_decision: str,
    rule: str,
) -> dict[str, object]:
    """Return sharp binary bounds under all missing panel decisions."""

    if rule not in PANEL_RULES:
        raise ValueError("panel rule is invalid")
    configured = tuple(models)
    if not configured or len(set(configured)) != len(configured):
        raise ValueError("panel models must be unique and nonempty")
    if not set(decisions) <= set(configured):
        raise ValueError("panel decisions contain an unconfigured model")
    observed_values = set(decisions.values())
    if not observed_values <= {
        positive_decision,
        negative_decision,
        "abstain",
    }:
        raise ValueError("panel decision is invalid")

    positive_count = sum(
        decisions.get(model) == positive_decision
        for model in configured
    )
    abstaining_models = tuple(
        model for model in configured if decisions.get(model) == "abstain"
    )
    missing_models = tuple(
        model for model in configured if model not in decisions
    )
    unknown_count = len(abstaining_models) + len(missing_models)
    lower = int(_apply_rule(positive_count, len(configured), rule))
    upper = int(
        _apply_rule(
            positive_count + unknown_count,
            len(configured),
            rule,
        )
    )
    return {
        "lower": lower,
        "upper": upper,
        "identified": lower == upper,
        "missing_models": list(missing_models),
        "abstaining_models": list(abstaining_models),
    }


def paired_effect_bounds(
    left: tuple[int, int],
    right: tuple[int, int],
) -> tuple[int, int]:
    """Return sharp bounds for one paired left-minus-right effect."""

    if any(value not in {0, 1} for value in (*left, *right)):
        raise ValueError("binary outcome bounds must contain only zero or one")
    if left[0] > left[1] or right[0] > right[1]:
        raise ValueError("binary outcome bounds are reversed")
    return left[0] - right[1], left[1] - right[0]


def _apply_rule(positive_count: int, panel_size: int, rule: str) -> bool:
    if rule == "majority":
        return positive_count > panel_size / 2
    if rule == "any_detect":
        return positive_count > 0
    return positive_count == panel_size

