"""Agent stream event helpers."""

from __future__ import annotations

from typing import Any


def event_text(event: Any) -> str | None:
    """Return a compact human-readable view of one provider stream event."""
    if not isinstance(event, dict):
        return None

    candidates: list[str] = []
    stack: list[Any] = [event]
    interesting_keys = {
        "text",
        "content",
        "message",
        "thought",
        "name",
        "command",
        "status",
        "type",
    }
    while stack:
        value = stack.pop()
        if isinstance(value, dict):
            for key, child in value.items():
                if key in interesting_keys and isinstance(child, str) and child.strip():
                    candidates.append(f"{key}={child.strip()}")
                elif isinstance(child, (dict, list)):
                    stack.append(child)
        elif isinstance(value, list):
            stack.extend(value)
    return " | ".join(candidates[:6]) if candidates else None

src/rubric_gen/runtime/agents/codex_even:
"""Translate Codex app-server notifications into benchmark trajectory events."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def notification_event(
    notification: Any,
    latest_usage: dict[str, object] | None,
    *,
    session_id: str,
) -> tuple[dict[str, object] | None, dict[str, object] | None]:
    method = getattr(notification, "method", "")
    payload = _json_payload(getattr(notification, "payload", {}))
    if method == "turn/started":
        return None, None
    if method in {"item/started", "item/completed"}:
        return _item_event(method, payload, session_id), None
    if method == "thread/tokenUsage/updated":
        return None, _usage(payload)
    if method == "error":
        return _error_event(payload), None
    if method == "turn/completed":
        return _completed_event(payload, latest_usage, session_id), None
    if not method:
        return None, None
    return (
        {
            "type": f"codex.{method.replace('/', '.')}",
            "payload": payload,
        },
        None,
    )


def trajectory_errors(stream_path: Path) -> list[str]:
    errors: list[str] = []
    for line in stream_path.read_text(errors="replace").splitlines():
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(event, dict):
            continue
        event_type = event.get("type")
        status = event.get("status")
        if event_type == "error":
            errors.append(f"trajectory_error: {event.get('message') or 'unknown'}")
        if event_type == "turn.completed" and status != "completed":
            errors.append(f"trajectory_turn_status: {status}")
    return errors


def _item_event(
    method: str,
    payload: dict[str, object],
    session_id: str,
) -> dict[str, object]:
    item = payload.get("item")
    if isinstance(item, dict):
        item = _normalize_item(item)
    return {
        "type": method.replace("/", "."),
        "thread_id": payload.get("thread_id", session_id),
        "turn_id": payload.get("turn_id"),
        "item": item,
    }


def _usage(payload: dict[str, object]) -> dict[str, object] | None:
    token_usage = payload.get("token_usage")
    total = token_usage.get("total") if isinstance(token_usage, dict) else None
    return total if isinstance(total, dict) else None


def _error_event(payload: dict[str, object]) -> dict[str, object]:
    error = payload.get("error")
    message = error.get("message") if isinstance(error, dict) else error
    will_retry = payload.get("will_retry") is True
    return {
        "type": "transport.retry" if will_retry else "error",
        "phase": "provider",
        "message": str(message or "unknown Codex error"),
        "will_retry": will_retry,
    }


def _completed_event(
    payload: dict[str, object],
    latest_usage: dict[str, object] | None,
    session_id: str,
) -> dict[str, object]:
    value = payload.get("turn")
    turn = value if isinstance(value, dict) else {}
    event: dict[str, object] = {
        "type": "turn.completed",
        "thread_id": payload.get("thread_id", session_id),
        "turn_id": turn.get("id"),
        "status": turn.get("status"),
    }
    if latest_usage is not None:
        event["usage"] = latest_usage
    if turn.get("error") is not None:
        event["error"] = turn["error"]
    return event


def _json_payload(payload: Any) -> dict[str, object]:
    if isinstance(payload, dict):
        return payload
    dump = getattr(payload, "model_dump", None)
    if dump is None:
        params = getattr(payload, "params", None)
        return params if isinstance(params, dict) else {}
    value = dump(mode="json", by_alias=False, exclude_none=True)
    return value if isinstance(value, dict) else {}


def _normalize_item(item: dict[str, object]) -> dict[str, object]:
    root = item.get("root")
    if isinstance(root, dict):
        item = root
    normalized = dict(item)
    item_type = normalized.get("type")
    if isinstance(item_type, str):
        normalized["type"] = _snake_case(item_type)
    return normalized


def _snake_case(value: str) -> str:
    result: list[str] = []
    for char in value:
        if char.isupper():
            result.extend(("_", char.lower()))
        else:
            result.append(char)
    return "".join(result).lstrip("_")

"""Strict JSON-RPC boundary for the Codex app-server proxy."""

from __future__ import annotations

import json
import threading
from typing import TypeAlias

from openai_codex.generated.notification_registry import NOTIFICATION_MODELS


RpcId: TypeAlias = str | int
_SERVER_REQUEST_METHODS = frozenset(
    {
        "item/commandExecution/requestApproval",
        "item/fileChange/requestApproval",
    }
)
_SERVER_NOTIFICATION_METADATA = frozenset({"emittedAtMs"})


class CodexRpcGuard:
    """Allow only correlated messages from the current Codex SDK protocol."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._client_requests: set[RpcId] = set()
        self._server_requests: set[RpcId] = set()

    def client_message(self, raw: str) -> str:
        """Validate one trusted SDK message and record its request identity."""
        message = _object(raw)
        with self._lock:
            if "method" in message:
                _validate_method_message(message)
                if "id" in message:
                    request_id = _message_id(message)
                    if request_id in self._client_requests:
                        raise ValueError("duplicate client request id")
                    self._client_requests.add(request_id)
            else:
                request_id = _validate_response(message)
                if request_id not in self._server_requests:
                    raise ValueError("client response has no pending server request")
                self._server_requests.remove(request_id)
        return _canonical(message)

    def server_message(self, raw: str) -> tuple[str | None, str | None]:
        """Return a validated server message or its rejection reason."""
        try:
            message = _object(raw)
            with self._lock:
                if "method" in message:
                    _validate_method_message(
                        message,
                        allowed_metadata=(
                            _SERVER_NOTIFICATION_METADATA
                            if "id" not in message
                            else frozenset()
                        ),
                    )
                    method = message["method"]
                    if "id" in message:
                        if method not in _SERVER_REQUEST_METHODS:
                            raise ValueError("unknown server request method")
                        request_id = _message_id(message)
                        if request_id in self._server_requests:
                            raise ValueError("duplicate server request id")
                        self._server_requests.add(request_id)
                    else:
                        model = NOTIFICATION_MODELS.get(method)
                        if model is None:
                            raise ValueError("unknown server notification method")
                        params = message.get("params", {})
                        model.model_validate(params if params is not None else {})
                else:
                    request_id = _validate_response(message)
                    if request_id not in self._client_requests:
                        raise ValueError("server response has no pending client request")
                    self._client_requests.remove(request_id)
            return _canonical(message), None
        except Exception as exc:
            return None, f"{type(exc).__name__}: {exc}"


def _object(raw: str) -> dict[str, object]:
    try:
        value = json.loads(
            raw,
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
    except json.JSONDecodeError as exc:
        raise ValueError("message is not JSON") from exc
    if type(value) is not dict:
        raise ValueError("message is not a JSON object")
    return value


def _unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            raise ValueError(f"duplicate JSON key: {key}")
        value[key] = item
    return value


def _reject_constant(value: str) -> None:
    raise ValueError(f"invalid JSON constant: {value}")


def _validate_method_message(
    message: dict[str, object],
    *,
    allowed_metadata: frozenset[str] = frozenset(),
) -> None:
    expected = {"method"}
    if "params" in message:
        expected.add("params")
    if "id" in message:
        expected.add("id")
    unexpected = set(message) - expected
    if not unexpected <= allowed_metadata:
        raise ValueError("method message has an invalid shape")
    method = message.get("method")
    if type(method) is not str or not method:
        raise ValueError("method must be a non-empty string")
    if "params" in message and message["params"] is not None:
        if type(message["params"]) is not dict:
            raise ValueError("params must be an object or null")
    if "id" in message:
        _message_id(message)
    if "emittedAtMs" in message:
        emitted_at_ms = message["emittedAtMs"]
        if type(emitted_at_ms) is not int or emitted_at_ms < 0:
            raise ValueError("emittedAtMs must be a non-negative integer")


def _validate_response(message: dict[str, object]) -> RpcId:
    result = "result" in message
    error = "error" in message
    if result == error:
        raise ValueError("response must contain exactly one result or error")
    expected = {"id", "result" if result else "error"}
    if set(message) != expected:
        raise ValueError("response has an invalid shape")
    if error and type(message["error"]) is not dict:
        raise ValueError("response error must be an object")
    return _message_id(message)


def _message_id(message: dict[str, object]) -> RpcId:
    value = message.get("id")
    if type(value) not in {str, int} or value == "":
        raise ValueError("id must be a non-empty string or an integer")
    return value


def _canonical(message: dict[str, object]) -> str:
    return json.dumps(
        message,
        allow_nan=False,
        ensure_ascii=False,
        separators=(",", ":"),
    )

