"""Execution runners for benchmark agent experiments."""

from __future__ import annotations

import json
import os
import re
import signal
import shutil
import subprocess
import threading
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, TextIO

from rubric_gen.runtime.agents.adapters import AgentAdapterRegistry
from rubric_gen.runtime.agents.contracts import OutputValidator
from rubric_gen.runtime.agents.costs import RunCost
from rubric_gen.runtime.agents.models import AgentRunConfig, RunPaths
from rubric_gen.runtime.agents.workspaces import (
    TaskWorkspace,
    ensure_artifacts_dir,
)


@dataclass(frozen=True)
class RunValidation:
    errors: tuple[str, ...] = field(default_factory=tuple)
    suspicious_files: tuple[str, ...] = field(default_factory=tuple)

    @property
    def ok(self) -> bool:
        return not self.errors

    @property
    def has_transient_stream_error(self) -> bool:
        return any(
            error.startswith("trajectory_error:")
            or error.startswith("trajectory_result_status:")
            or error.startswith("trajectory_invalid_json:")
            for error in self.errors
        )

    def effective_exit_code(self, process_exit_code: int) -> int:
        if process_exit_code != 0:
            return process_exit_code
        return 0 if self.ok else 1

    def fields(self) -> dict[str, list[str] | bool]:
        return {
            "validation_ok": self.ok,
            "validation_errors": list(self.errors),
            "suspicious_files": list(self.suspicious_files),
        }

    @classmethod
    def from_status(cls, status_path: Path) -> "RunValidation | None":
        if not status_path.is_file():
            return None
        try:
            status = json.loads(status_path.read_text())
        except json.JSONDecodeError:
            return None
        if "validation_errors" not in status and "suspicious_files" not in status:
            return None
        return cls(
            errors=tuple(status.get("validation_errors") or ()),
            suspicious_files=tuple(status.get("suspicious_files") or ()),
        )


class AgentRunner:
    def __init__(
        self,
        config: AgentRunConfig | None = None,
        *,
        registry: AgentAdapterRegistry | None = None,
        prompt: str,
        output_errors: OutputValidator,
    ) -> None:
        if not prompt.strip():
            raise ValueError("agent prompt must not be empty")
        if not callable(output_errors):
            raise TypeError("agent output validator must be callable")
        self.config = config or AgentRunConfig()
        self.registry = registry or AgentAdapterRegistry()
        self.adapter = self.registry.get(self.config.provider)
        self.prompt = prompt
        self.output_errors = output_errors

    @property
    def provider(self) -> str:
        return self.adapter.name

    def ensure_executable(self) -> None:
        executable = self.adapter.executable(self.config)
        if shutil.which(executable) is None:
            raise SystemExit(
                f"Could not find `{executable}` on PATH. {self.adapter.install_hint()}"
            )

    def build_command(self, paths: RunPaths) -> list[str]:
        return self.adapter.build_command(paths, self.config, self.prompt)

    def stream(self, paths: RunPaths) -> int:
        self.adapter.prepare_run(paths, self.config, self.prompt)
        command = self.build_command(paths)
        env = self.adapter.build_environment(paths, self.config)

        if not self.config.quiet:
            print(f"Provider: {self.provider}")
            print(f"Run dir: {paths.run_dir}")
            print(f"Workspace: {paths.workspace_dir}")
            print(f"Trajectory log: {paths.stream_path}")
            print("Starting agent CLI...\n", flush=True)

        with (
            paths.prompt_path.open() as prompt_input,
            paths.stream_path.open("w") as log,
            self.stderr_path(paths).open("w") as diagnostics,
        ):
            proc = subprocess.Popen(
                command,
                cwd=paths.workspace_dir,
                env=env,
                text=True,
                stdin=(
                    prompt_input
                    if self.adapter.prompt_via_stdin
                    else subprocess.DEVNULL
                ),
                stdout=subprocess.PIPE,
                stderr=diagnostics,
                bufsize=1,
                start_new_session=os.name == "posix",
            )
            timed_out = threading.Event()

            def terminate_on_timeout() -> None:
                timed_out.set()
                self._terminate_process(proc)

            timer = threading.Timer(self.config.timeout_seconds, terminate_on_timeout)
            timer.daemon = True
            timer.start()
            try:
                assert proc.stdout is not None
                self._tee_stream(proc.stdout, log)
                exit_code = proc.wait()
                return 124 if timed_out.is_set() else exit_code
            finally:
                timer.cancel()
                if proc.poll() is None:
                    self._terminate_process(proc)

    @staticmethod
    def _terminate_process(process: subprocess.Popen[str]) -> None:
        try:
            if os.name == "posix":
                os.killpg(process.pid, signal.SIGTERM)
            else:  # pragma: no cover
                process.terminate()
            process.wait(timeout=5)
        except (OSError, subprocess.TimeoutExpired):
            try:
                if os.name == "posix":
                    os.killpg(process.pid, signal.SIGKILL)
                else:  # pragma: no cover
                    process.kill()
            except OSError:
                pass
            try:
                process.wait(timeout=5)
            except (OSError, subprocess.TimeoutExpired):
                pass

    def _tee_stream(self, stdout: TextIO, log: TextIO) -> None:
        for line in stdout:
            log.write(line)
            log.flush()
            if not self.config.quiet:
                self.adapter.print_line(line, raw=self.config.raw)

    def validate_outputs(self, paths: RunPaths) -> RunValidation:
        errors = self.output_errors(paths.workspace_dir)
        errors.extend(self.trajectory_errors(paths.stream_path))
        suspicious_files = self.find_cross_run_references(paths)
        return RunValidation(tuple(errors), tuple(suspicious_files))

    def trajectory_errors(self, stream_path: Path) -> list[str]:
        if not stream_path.is_file():
            return []

        errors = []
        with stream_path.open() as stream:
            for line_number, line in enumerate(stream, start=1):
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    errors.append(f"trajectory_invalid_json: line {line_number}")
                    continue
                if not isinstance(event, dict):
                    continue
                event_type = event.get("type")
                status = event.get("status")
                if event_type == "error":
                    message = event.get("message") or event.get("error") or "unknown"
                    errors.append(f"trajectory_error: {message}")
                if event_type == "result" and status not in (
                    None,
                    "success",
                    "completed",
                ):
                    errors.append(f"trajectory_result_status: {status}")
        return errors

    def find_cross_run_references(self, paths: RunPaths) -> list[str]:
        suspicious = []
        for text_path in self.workspace_text_files(paths.workspace_dir):
            try:
                content = text_path.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            if self.has_cross_run_reference(content, paths):
                suspicious.append(str(text_path.relative_to(paths.workspace_dir)))
        return suspicious

    def workspace_text_files(self, workspace_dir: Path) -> list[Path]:
        suffixes = {".py", ".r", ".R", ".sh", ".md", ".txt", ".json", ".jsonl", ".toml"}
        files = []
        for path in workspace_dir.rglob("*"):
            if not path.is_file():
                continue
            if any(
                name in path.parts for name in (".agent-tmp", ".venv", "data")
            ):
                continue
            if path.suffix in suffixes:
                files.append(path)
        return files

    def has_cross_run_reference(self, content: str, paths: RunPaths) -> bool:
        runs_root = self.runs_root(paths)
        allowed_prefixes = {
            str(paths.run_dir.resolve()),
            str(paths.run_dir),
            str(paths.workspace_dir.resolve()),
            str(paths.workspace_dir),
        }
        if paths.run_dir.parent.name == "tasks":
            allowed_prefixes.add(str(paths.run_dir.parents[1].resolve()))
            allowed_prefixes.add(str(paths.run_dir.parents[1]))

        for root in {str(runs_root.resolve()), str(runs_root)}:
            root_pattern = re.escape(root)
            path_pattern = re.compile(rf"{root_pattern}(?:[^\s\"'`),;\]]*)?")
            for match in path_pattern.finditer(content):
                referenced = match.group(0).rstrip(".")
                if any(referenced.startswith(prefix) for prefix in allowed_prefixes):
                    continue
                return True
        return False

    def runs_root(self, paths: RunPaths) -> Path:
        if paths.run_dir.parent.name == "tasks":
            return paths.run_dir.parents[2]
        return paths.run_dir.parent

    def run(
        self,
        task_dir: Path,
        runs_dir: Path | None = None,
        *,
        paths: RunPaths | None = None,
    ) -> tuple[int, RunPaths]:
        self.ensure_executable()
        if paths is None:
            if runs_dir is None:
                raise ValueError("runs_dir is required when paths is not provided")
            paths = RunPaths.for_task(task_dir, runs_dir, provider=self.provider)
        paths.run_dir.mkdir(parents=True, exist_ok=True)
        TaskWorkspace(task_dir, paths.workspace_dir).create()
        ensure_artifacts_dir(paths.workspace_dir)

        attempts = []
        max_attempts = self.config.retries + 1
        for attempt in range(1, max_attempts + 1):
            process_exit_code = self.stream(paths)
            validation = self.validate_outputs(paths)
            exit_code = validation.effective_exit_code(process_exit_code)
            attempt_record = {
                "attempt": attempt,
                "process_exit_code": process_exit_code,
                "exit_code": exit_code,
                **validation.fields(),
            }
            attempts.append(attempt_record)
            if exit_code == 0 or not self.should_retry(
                attempt, max_attempts, validation, process_exit_code
            ):
                break
            self.archive_attempt(paths, attempt, attempt_record)
            self._recreate_workspace(task_dir, paths.workspace_dir)

        cost = RunCost.from_stream(
            paths.stream_path,
            model=self.config.model,
            service_tier=self.config.service_tier,
        )
        status = {
            "provider": self.provider,
            "requested_model": self.config.model,
            "task": task_dir.name,
            "task_dir": str(task_dir),
            "workspace_dir": str(paths.workspace_dir),
            "attempt_count": len(attempts),
            "max_retries": self.config.retries,
            "timeout_seconds": self.config.timeout_seconds,
            "service_tier": self.config.service_tier,
            "stderr": str(self.stderr_path(paths)),
            "attempts": attempts,
            "process_exit_code": process_exit_code,
            "exit_code": exit_code,
            **validation.fields(),
            **cost.fields(),
        }
        paths.status_path.write_text(json.dumps(status, indent=2) + "\n")
        return exit_code, paths

    @staticmethod
    def _recreate_workspace(task_dir: Path, workspace: Path) -> None:
        if workspace.is_symlink() or not workspace.is_dir():
            raise RuntimeError(f"retry workspace is invalid: {workspace}")
        shutil.rmtree(workspace)
        TaskWorkspace(task_dir, workspace).create()
        ensure_artifacts_dir(workspace)

    def should_retry(
        self,
        attempt: int,
        max_attempts: int,
        validation: RunValidation,
        process_exit_code: int,
    ) -> bool:
        return attempt < max_attempts and (
            process_exit_code != 0 or validation.has_transient_stream_error
        )

    @staticmethod
    def stderr_path(paths: RunPaths) -> Path:
        return paths.run_dir / "stderr.log"

    def archive_attempt(
        self,
        paths: RunPaths,
        attempt: int,
        attempt_record: dict[str, Any],
    ) -> None:
        attempts_dir = paths.run_dir / "attempts"
        attempts_dir.mkdir(parents=True, exist_ok=True)
        if paths.stream_path.is_file():
            shutil.copy2(
                paths.stream_path,
                attempts_dir / f"attempt-{attempt}.trajectory.stream.jsonl",
            )
        stderr_path = self.stderr_path(paths)
        if stderr_path.is_file():
            shutil.copy2(
                stderr_path,
                attempts_dir / f"attempt-{attempt}.stderr.log",
            )
        for filename in ("trace.md", "answer.txt"):
            output_path = paths.workspace_dir / filename
            if output_path.is_file():
                shutil.copy2(
                    output_path, attempts_dir / f"attempt-{attempt}.{filename}"
                )
        (attempts_dir / f"attempt-{attempt}.status.json").write_text(
            json.dumps(attempt_record, indent=2) + "\n"
        )

src/rubric_gen/runtime/agents/costs.py:
"""Reported and estimated terminal-agent run costs."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from rubric_gen.runtime.pricing import (
    GEMINI_TERMINAL_PRICES_PER_MILLION,
    OPENAI_PRICES_PER_MILLION,
    OPENAI_PRIORITY_MULTIPLIER,
    PRICING_AS_OF,
    PRICING_SOURCES,
)

GEMINI_API_PRICING_SOURCE = PRICING_SOURCES["google"]
GEMINI_PRICING_AS_OF = PRICING_AS_OF
GEMINI_COST_SOURCE = "estimated_google_gemini_api_standard"
OPENAI_COST_SOURCE = "estimated_openai_api_lower_bound"
OPENAI_FAST_MODE_MULTIPLIER = OPENAI_PRIORITY_MULTIPLIER
OPENAI_STANDARD_PRICES_PER_MILLION = OPENAI_PRICES_PER_MILLION
GEMINI_STANDARD_PRICES_PER_MILLION = GEMINI_TERMINAL_PRICES_PER_MILLION


@dataclass(frozen=True)
class RunCost:
    cost_usd: float | None = None
    estimated_cost_usd: float | None = None
    source: str | None = None

    @classmethod
    def from_stream(
        cls,
        stream_path: Path,
        *,
        model: str | None = None,
        service_tier: str | None = None,
    ) -> "RunCost":
        terminal_reported: dict[str, float] = {}
        terminal_estimated: dict[str, float] = {}
        fallback_reported: list[float] = []
        fallback_estimated: list[float] = []
        session_key = "stream"
        anonymous_session_index = 0
        if not stream_path.is_file():
            return cls()
        with stream_path.open() as stream:
            for line in stream:
                try:
                    event = json.loads(line)
                except json.JSONDecodeError:
                    continue
                detected_session = _session_identity(event)
                if detected_session is not None:
                    if detected_session == "anonymous-session":
                        anonymous_session_index += 1
                        session_key = f"anonymous-session:{anonymous_session_index}"
                    else:
                        # Codex reports cumulative usage for a persistent thread.
                        # The same thread.started record can occur once per resumed
                        # CLI invocation, so key by the provider identity and retain
                        # only its largest terminal total.
                        session_key = detected_session
                event_cost = cls.from_event(
                    event,
                    model=model,
                    service_tier=service_tier,
                )
                if event_cost.cost_usd is not None:
                    fallback_reported.append(event_cost.cost_usd)
                if event_cost.estimated_cost_usd is not None:
                    fallback_estimated.append(event_cost.estimated_cost_usd)
                if _is_terminal_usage_event(event):
                    if event_cost.cost_usd is not None:
                        terminal_reported[session_key] = max(
                            terminal_reported.get(session_key, 0.0),
                            event_cost.cost_usd,
                        )
                    if event_cost.estimated_cost_usd is not None:
                        terminal_estimated[session_key] = max(
                            terminal_estimated.get(session_key, 0.0),
                            event_cost.estimated_cost_usd,
                        )
        cost_usd = (
            round(sum(terminal_reported.values()), 6)
            if terminal_reported
            else max(fallback_reported, default=None)
        )
        estimated_cost_usd = (
            round(sum(terminal_estimated.values()), 6)
            if terminal_estimated
            else max(fallback_estimated, default=None)
        )
        source = "reported" if cost_usd is not None else None
        if source is None and estimated_cost_usd is not None:
            source = (
                OPENAI_COST_SOURCE
                if model in OPENAI_STANDARD_PRICES_PER_MILLION
                else GEMINI_COST_SOURCE
            )
        return cls(cost_usd, estimated_cost_usd, source)

    @classmethod
    def from_status(cls, status_path: Path) -> "RunCost":
        if not status_path.is_file():
            return cls()
        try:
            status = json.loads(status_path.read_text())
        except json.JSONDecodeError:
            return cls()
        cost_usd = _parse_cost_value(status.get("cost_usd"))
        estimated_cost_usd = _parse_cost_value(status.get("estimated_cost_usd"))
        return cls(cost_usd, estimated_cost_usd, status.get("cost_source"))

    @classmethod
    def for_run_dir(cls, run_dir: Path) -> "RunCost":
        status_cost = cls.from_status(run_dir / "status.json")
        if status_cost.cost_usd is not None or status_cost.estimated_cost_usd is not None:
            return status_cost
        model = None
        try:
            status = json.loads((run_dir / "status.json").read_text())
        except (OSError, json.JSONDecodeError):
            status = {}
        if isinstance(status, dict):
            value = status.get("model") or status.get("requested_model")
            model = value if isinstance(value, str) else None
        service_tier = (
            status.get("service_tier")
            if isinstance(status.get("service_tier"), str)
            else None
        )
        return cls.from_stream(
            run_dir / "trajectory.stream.jsonl",
            model=model,
            service_tier=service_tier,
        )

    @classmethod
    def from_event(
        cls,
        event: Any,
        *,
        model: str | None = None,
        service_tier: str | None = None,
    ) -> "RunCost":
        cost_usd = _find_cost_usd(event)
        estimated_cost_usd = (
            _estimate_openai_event_cost(event, model, service_tier=service_tier)
            if model in OPENAI_STANDARD_PRICES_PER_MILLION
            else _estimate_gemini_event_cost(event)
        )
        source = "reported" if cost_usd is not None else None
        if source is None and estimated_cost_usd is not None:
            source = (
                OPENAI_COST_SOURCE
                if model in OPENAI_STANDARD_PRICES_PER_MILLION
                else GEMINI_COST_SOURCE
            )
        return cls(cost_usd, estimated_cost_usd, source)

    def fields(self) -> dict[str, float | str | None]:
        return {
            "cost_usd": self.cost_usd,
            "estimated_cost_usd": self.estimated_cost_usd,
            "cost_source": self.source,
        }


def _find_cost_usd(value: Any) -> float | None:
    if isinstance(value, dict):
        for key, child in value.items():
            if _is_usd_cost_key(key):
                cost = _parse_cost_value(child)
                if cost is not None:
                    return cost
            cost = _find_cost_usd(child)
            if cost is not None:
                return cost
    elif isinstance(value, list):
        for child in value:
            cost = _find_cost_usd(child)
            if cost is not None:
                return cost
    return None


def _is_terminal_usage_event(event: Any) -> bool:
    if not isinstance(event, dict):
        return False
    event_type = event.get("type")
    if event_type in {"result", "turn.completed", "session.completed"}:
        return True
    return event_type == "assistant" and event.get("subtype") == "result"


def _session_identity(event: Any) -> str | None:
    if not isinstance(event, dict) or event.get("type") not in {
        "thread.started", "session.started", "conversation.started",
    }:
        return None
    for key in ("thread_id", "session_id", "conversation_id"):
        value = event.get(key)
        if isinstance(value, str) and value:
            return value
    return "anonymous-session"


def _is_usd_cost_key(key: str) -> bool:
    normalized = "".join(char for char in key.lower() if char.isalnum())
    return "cost" in normalized and "usd" in normalized


def _parse_cost_value(value: Any) -> float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip().removeprefix("$"))
        except ValueError:
            return None
    return None


def _estimate_gemini_event_cost(event: Any) -> float | None:
    if not isinstance(event, dict):
        return None
    stats = event.get("stats")
    models = stats.get("models") if isinstance(stats, dict) else None
    if not isinstance(models, dict):
        return None

    total = 0.0
    matched = False
    for model_name, model_stats in models.items():
        if not isinstance(model_name, str) or not isinstance(model_stats, dict):
            continue
        prices = GEMINI_STANDARD_PRICES_PER_MILLION.get(model_name)
        if prices is None:
            continue
        matched = True
        cached_tokens = _parse_token_count(model_stats.get("cached")) or 0
        input_tokens = _parse_token_count(model_stats.get("input"))
        if input_tokens is None:
            total_input = _parse_token_count(model_stats.get("input_tokens")) or 0
            input_tokens = max(total_input - cached_tokens, 0)
        output_tokens = _parse_token_count(model_stats.get("output_tokens")) or 0
        total += (
            input_tokens * prices["input"]
            + cached_tokens * prices["cached"]
            + output_tokens * prices["output"]
        ) / 1_000_000
    return round(total, 6) if matched else None


def _estimate_openai_event_cost(
    event: Any,
    model: str | None,
    *,
    service_tier: str | None,
) -> float | None:
    if not isinstance(event, dict) or model not in OPENAI_STANDARD_PRICES_PER_MILLION:
        return None
    usage = event.get("usage")
    if not isinstance(usage, dict):
        return None
    total_input = _parse_token_count(usage.get("input_tokens"))
    output = _parse_token_count(usage.get("output_tokens"))
    if total_input is None or output is None:
        return None
    cached = _parse_token_count(usage.get("cached_input_tokens")) or 0
    cache_write = _parse_token_count(usage.get("cache_write_input_tokens")) or 0
    if cached + cache_write > total_input:
        return None
    uncached = total_input - cached - cache_write
    prices = OPENAI_STANDARD_PRICES_PER_MILLION[model]
    multiplier = OPENAI_FAST_MODE_MULTIPLIER if service_tier == "priority" else 1.0
    return round(
        (
            uncached * prices["input"]
            + cached * prices["cached"]
            + cache_write * prices["cache_write"]
            + output * prices["output"]
        )
        * multiplier / 1_000_000,
        6,
    )


def _parse_token_count(value: Any) -> int | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    return None

"""Small runtime contracts supplied by benchmark integrations."""

from __future__ import annotations

import os
import stat
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol


class SessionContract(Protocol):
    """Recovery and output rules for a persistent solver session."""

    recovery_prompt: str
    output_recovery_prompt: str

    def output_errors(self, workspace: Path) -> list[str]: ...


class OutputValidator(Protocol):
    """Validate the completed outputs in one agent workspace."""

    def __call__(self, workspace: Path) -> list[str]: ...


@dataclass(frozen=True)
class RegularFileOutputs:
    """Require a fixed set of regular, non-empty output files."""

    names: tuple[str, ...]

    def __post_init__(self) -> None:
        if not self.names or any(
            not name or Path(name).name != name for name in self.names
        ):
            raise ValueError("required output files must have safe names")

    def __call__(self, workspace: Path) -> list[str]:
        errors: list[str] = []
        for name in self.names:
            try:
                value = os.lstat(workspace / name)
            except OSError:
                errors.append(f"missing_or_empty: {name}")
                continue
            if not stat.S_ISREG(value.st_mode) or value.st_size == 0:
                errors.append(f"missing_or_empty: {name}")
        return errors

