tests/test_contrasts.py:
from __future__ import annotations

from pathlib import Path
from types import SimpleNamespace

import pytest

from rubric_gen.runtime.agents.models import AgentRunConfig
from rubric_gen.submission_revision import contrasts as contrast_module
from rubric_gen.submission_revision.rubric_generation import RubricPolicy


class _Benchmark:
    benchmark = "biomnibench-da"

    @staticmethod
    def render_user_review(workspace: Path) -> str:
        return (workspace / "review.txt").read_text(encoding="utf-8")

    @staticmethod
    def render_submission(_workspace: Path) -> str:
        raise AssertionError("elicitation must use complete public review evidence")


def _workspace(root: Path, name: str, text: str) -> Path:
    workspace = root / name / "workspace"
    workspace.mkdir(parents=True)
    (workspace / "artifact.txt").write_text(text, encoding="utf-8")
    (workspace / "review.txt").write_text(
        "public review: " + text,
        encoding="utf-8",
    )
    return workspace


def _seed_resolver(root: Path, *, duplicate_attacks: bool = False):
    seeds = {
        replicate: (
            _workspace(root, f"seed-{replicate}", f"seed {replicate}\n"),
            _workspace(root, f"attack-{replicate}", f"attack {replicate}\n"),
        )
        for replicate in (1, 2, 3)
    }

    def resolve_seed(
        _seed_set: Path,
        _task_dir: Path,
        replicate: int,
        *,
        seed_generator: AgentRunConfig,
        prompt_profile: str,
        benchmark: str,
    ) -> SimpleNamespace:
        assert seed_generator.provider == "codex"
        assert seed_generator.model == "gpt-5.6-luna"
        assert prompt_profile == "base"
        assert benchmark == "biomnibench-da"
        clean, adversarial = seeds[replicate]
        if duplicate_attacks:
            adversarial = clean
        return SimpleNamespace(elicitation_artifacts=(
            ("clean", clean),
            ("adversarial", adversarial),
        ))

    return resolve_seed


def _arguments(tmp_path: Path) -> dict[str, object]:
    return {
        "seed_set": tmp_path / "seeds",
        "task_dir": tmp_path / "task",
        "benchmark": _Benchmark(),
        "seed_generator": AgentRunConfig(
            provider="codex",
            model="gpt-5.6-luna",
        ),
        "prompt_profile": "base",
        "seed_replicates": 3,
        "blinding_scope": "shared-task-rubric",
    }


def test_offline_history_uses_three_ordinary_and_one_shared_adversarial_seed(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))

    history = contrast_module.build_offline_artifact_history(
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )

    assert {item.source_id for item in history.artifacts} == {
        *(f"sealed-seed:rep-{index:03d}:clean" for index in (1, 2, 3)),
        "sealed-seed:rep-001:adversarial",
    }
    assert len(history.artifacts) == 4
    assert len(history.pairs) == 3
    adversarial_id = next(
        item.artifact_id for item in history.artifacts
        if item.source_id.endswith(":adversarial")
    )
    assert all(adversarial_id in pair.artifact_ids for pair in history.pairs)
    assert all("public review:" in item.content for item in history.artifacts)
    assert set(history.model_record()) == {"artifacts", "pairs"}
    assert "source_id" not in str(history.model_record())


def test_offline_history_deduplicates_exact_attempt_copies(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(
        contrast_module,
        "resolve_seed",
        _seed_resolver(tmp_path, duplicate_attacks=True),
    )

    history = contrast_module.build_offline_artifact_history(
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )

    assert len(history.artifacts) == 3
    assert len(history.pairs) == 2
    assert all(item.source_id.endswith(":clean") for item in history.artifacts)


def test_online_history_includes_seed_and_adjacent_revision_pairs(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))
    experiment = tmp_path / "experiment"
    for index in range(6):
        _workspace(experiment / "submissions", f"s{index:03d}", f"live {index}\n")

    history = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=5,
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )

    assert {item.source_id for item in history.artifacts} == {
        *(f"sealed-seed:rep-{index:03d}:clean" for index in (1, 2, 3)),
        "sealed-seed:rep-001:adversarial",
        *(f"live:s{index:03d}" for index in range(6)),
    }
    assert len(history.artifacts) == 10
    assert len(history.pairs) == 9
    assert all("public review:" in item.content for item in history.artifacts)


def test_online_first_update_pairs_only_adjacent_revisions(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))
    experiment = tmp_path / "experiment"
    for index in range(2):
        _workspace(experiment / "submissions", f"s{index:03d}", f"live {index}\n")

    history = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=1,
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )
    current_id = next(
        item.artifact_id for item in history.artifacts if item.source_id == "live:s001"
    )
    current_pairs = [
        pair for pair in history.pairs if current_id in pair.artifact_ids
    ]

    assert len(history.artifacts) == 6
    assert len(history.pairs) == 4
    assert len(current_pairs) == 1
    assert any(current_id not in pair.artifact_ids for pair in history.pairs)


def test_online_history_replaces_the_old_initial_current_anchor(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))
    experiment = tmp_path / "experiment"
    for index in range(4):
        _workspace(experiment / "submissions", f"s{index:03d}", f"live {index}\n")

    second = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=2,
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )
    third = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=3,
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )
    second_ids = {
        item.source_id: item.artifact_id for item in second.artifacts
    }
    third_ids = {
        item.source_id: item.artifact_id for item in third.artifacts
    }
    old_anchor = contrast_module.ArtifactPair.create(
        second_ids["live:s000"],
        second_ids["live:s002"],
    )
    new_anchor = contrast_module.ArtifactPair.create(
        third_ids["live:s000"],
        third_ids["live:s003"],
    )
    latest_adjacent = contrast_module.ArtifactPair.create(
        third_ids["live:s002"],
        third_ids["live:s003"],
    )

    assert old_anchor in second.pairs
    assert old_anchor not in third.pairs
    assert new_anchor in third.pairs
    assert latest_adjacent in third.pairs


def test_red_team_history_adds_one_sidecar_pair_and_private_trace(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))
    experiment = tmp_path / "experiment"
    for index in range(2):
        _workspace(experiment / "submissions", f"s{index:03d}", f"live {index}\n")
    sidecar = _workspace(tmp_path, "sidecar-1", "online attack 1\n")
    (sidecar.parent / "trajectory.stream.jsonl").write_text(
        '{"type":"item.completed","item":{"type":"reasoning","text":"probe"}}\n',
        encoding="utf-8",
    )

    def load_sidecar(*_args, **kwargs):
        assert kwargs["expected_generator"] == {"model": "red-team"}
        return SimpleNamespace(included=True, root=sidecar.parent)

    monkeypatch.setattr(
        contrast_module,
        "load_red_team_artifact",
        load_sidecar,
    )
    history = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=1,
        red_team_policy=RubricPolicy.RED_TEAM_ARTIFACT,
        red_team_generator_identity={"model": "red-team"},
        **_arguments(tmp_path),  # type: ignore[arg-type]
    )

    assert len(history.artifacts) == 7
    assert len(history.pairs) == 5
    ids_by_source = {
        item.source_id: item.artifact_id for item in history.artifacts
    }
    sidecar_pair = contrast_module.ArtifactPair.create(
        ids_by_source["live:s001"],
        ids_by_source["red-team:s001"],
    )
    assert sidecar_pair in history.pairs
    assert len(history.red_team_evidence) == 1
    evidence = history.red_team_evidence[0]
    assert evidence.pair_id == sidecar_pair.pair_id
    assert evidence.observed_artifact_id == ids_by_source["live:s001"]
    assert evidence.adversarial_artifact_id == ids_by_source["red-team:s001"]
    assert '"text":"probe"' in evidence.trajectory_excerpt
    assert "red-team" not in str(history.model_record())
    assert "trajectory_excerpt" in str(history.artifact_record())


def test_blinded_artifact_ids_stay_stable_as_online_history_grows(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(contrast_module, "resolve_seed", _seed_resolver(tmp_path))
    experiment = tmp_path / "experiment"
    for index in range(3):
        _workspace(experiment / "submissions", f"s{index:03d}", f"live {index}\n")
    arguments = _arguments(tmp_path)
    first = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=1,
        **arguments,  # type: ignore[arg-type]
    )
    second = contrast_module.build_online_artifact_history(
        experiment_dir=experiment,
        source_checkpoint=2,
        **arguments,  # type: ignore[arg-type]
    )

    first_ids = {item.content_sha256: item.artifact_id for item in first.artifacts}
    second_ids = {item.content_sha256: item.artifact_id for item in second.artifacts}
    assert first_ids == {digest: second_ids[digest] for digest in first_ids}
    assert set(first.pairs) < set(second.pairs)

tests/test_rubric_evolution.py:
from __future__ import annotations

import json
from dataclasses import replace
from itertools import product
from pathlib import Path

import pytest

import rubric_gen.submission_revision.evolution as evolution_module
import rubric_gen.submission_revision.evolution_assessment as assessment_module
import rubric_gen.submission_revision.evolution_protocol as protocol_module
from rubric_gen.artifacts.hashing import sha256_text
from rubric_gen.benchmarks import SubmissionBenchmarkId
from rubric_gen.submission_revision.autorubric import parse_autorubric_rubric
from rubric_gen.submission_revision.evolution import RubricProposer
from rubric_gen.submission_revision.evolution_artifacts import (
    ArtifactHistory,
    ArtifactPair,
    BlindedArtifact,
    RedTeamEvidence,
)
from rubric_gen.submission_revision.evolution_provider import (
    ProviderContract,
    RubricProposerProviderError,
    StructuredProviderOutput,
)
from rubric_gen.submission_revision.rubric_generation import (
    CompleteRubric,
    ElicitedCriterion,
    RubricGeneration,
    RubricPolicy,
    render_augmented_rubric,
)
from rubric_gen.submission_revision.pretreatment_rubrics import (
    install_pretreatment_rubric,
    validate_installed_pretreatment_rubric,
)


def _rubric() -> CompleteRubric:
    return CompleteRubric.from_content(
        "RUBRIC: Analysis\n\n"
        "Criterion 1: Correct answer\n"
        "Description: Produce a correct answer.\n"
        "Levels: A=60 B=30 C=0\n"
        "[A]: Complete and correct.\n"
        "[B]: Partly correct.\n"
        "[C]: Missing or incorrect.\n\n"
        "Criterion 2: Evidence\n"
        "Description: Save reproducible evidence.\n"
        "Levels: A=40 B=20 C=0\n"
        "[A]: Complete and reproducible.\n"
        "[B]: Partly reproducible.\n"
        "[C]: Missing or unusable.\n"
    )


def _development_rubric() -> CompleteRubric:
    return CompleteRubric.from_content(
        _rubric().content
        .replace("Criterion 1: Correct answer", "Criterion 1: Answer accuracy")
        .replace(
            "Description: Produce a correct answer.",
            "Description: Give an accurate answer.",
        )
    )


def _initial_generation() -> RubricGeneration:
    rubric = _rubric()
    return RubricGeneration(
        generation_round=0,
        source_checkpoint=None,
        rubric=rubric,
        elicited_criteria=(),
        proposer_call_budget=0,
    )


def _history() -> ArtifactHistory:
    contents = ("artifact one", "artifact two", "artifact three", "artifact four")
    artifacts = tuple(
        BlindedArtifact(
            artifact_id=f"artifact_{index:016x}",
            source_id=f"hidden:source:{index}",
            content_sha256=sha256_text(content),
            content=content,
        )
        for index, content in enumerate(contents, start=1)
    )
    pairs = tuple(
        ArtifactPair.create(artifacts[index].artifact_id, artifacts[index + 1].artifact_id)
        for index in range(len(artifacts) - 1)
    )
    return ArtifactHistory(
        artifacts=artifacts,
        pairs=pairs,
        red_team_evidence=(),
    )


def _parsed_assessment(
    relation: str,
    view: assessment_module.AssessmentView,
    current_generation: RubricGeneration | None = None,
):
    current = current_generation or _initial_generation()
    schema = assessment_module.assessment_schema(
        _history(),
        view=view,
        current_generation=current,
    )
    return assessment_module.validated_assessment_response(
        json.dumps(_assessment_value(relation=relation, schema=schema)),
        artifact_history=_history(),
        view=view,
        current_generation=current,
    )


def _comparisons():
    return assessment_module.pair_comparisons(
        _parsed_assessment(
            "preferred", assessment_module.AssessmentView.RUBRIC_FREE
        ),
        _parsed_assessment("tie", assessment_module.AssessmentView.ACTIVE_RUBRIC),
        _parsed_assessment(
            "tie", assessment_module.AssessmentView.DEVELOPMENT_RUBRIC
        ),
        _history(),
    )


def _induction_pair_ids() -> list[str]:
    induction, _validation = assessment_module.partition_gaps(_comparisons())
    return [item.pair_id for item in induction]


def _cost() -> dict[str, float | str | None]:
    return {
        "cost_usd": None,
        "estimated_cost_usd": 0.01,
        "cost_source": "test",
    }


def _generation(model: str, response_id: str) -> dict[str, object]:
    return {
        "provider": "openai",
        "requested_model": model,
        "effective_model": model,
        "response_id": response_id,
        "request_parameters": {"max_output_tokens": 1},
        "usage": {"input_tokens": 1, "output_tokens": 1},
    }


def _proposer_output(value: object, response_id: str) -> StructuredProviderOutput:
    return StructuredProviderOutput(
        response_text=json.dumps(value),
        cost=_cost(),
        generation=_generation("proposer", response_id),
    )


def _assessment_value(
    *,
    relation: str,
    schema: dict[str, object] | None = None,
    base_scores: dict[str, int] | None = None,
) -> dict[str, object]:
    if relation not in {"preferred", "rejected", "tie"}:
        raise AssertionError("invalid test assessment relation")

    def preference(pair: ArtifactPair) -> str:
        if relation == "tie":
            return "tie"
        presented = assessment_module.assessment_artifact_ids(pair)
        artifact_id = pair.artifact_ids[0 if relation == "preferred" else 1]
        return "artifact_A" if artifact_id == presented[0] else "artifact_B"

    result: dict[str, object] = {
        "assessments": [
            {
                "pair_id": pair.pair_id,
                "assessment_A": "This artifact has inspectable task evidence.",
                "assessment_B": "This artifact has weaker task evidence.",
                **(
                    {"preference": preference(pair)}
                    if schema is None or "rubric_scores" not in schema["properties"]
                    else {}
                ),
                "reason": "The preferred artifact has stronger task evidence.",
            }
            for pair in _history().pairs
        ]
    }
    if schema is None or "rubric_scores" not in schema["properties"]:  # type: ignore[operator]
        return result
    score_schema = schema["properties"]["rubric_scores"]["items"]  # type: ignore[index]
    score_properties = score_schema["properties"]
    artifact_ids = score_properties["artifact_id"]["enum"]
    maximum = score_properties["base_score"]["maximum"]
    criterion_schema = score_properties["criterion_levels"]["items"]["properties"]
    criterion_ids = criterion_schema["criterion_id"].get("enum", [])
    level_labels = criterion_schema["level"].get("enum", [])
    resolved_base_scores = base_scores or {
        artifact_id: (
            maximum // 2
            if relation == "tie"
            else maximum - index
            if relation == "preferred"
            else index
        )
        for index, artifact_id in enumerate(artifact_ids)
    }
    result["rubric_scores"] = [
        {
            "artifact_id": artifact_id,
            "base_score": resolved_base_scores[artifact_id],
            "criterion_levels": [
                {
                    "criterion_id": criterion_id,
                    "level": level_labels[0],
                }
                for criterion_id in criterion_ids
            ],
            "reason": "The score follows the supplied rubric.",
        }
        for artifact_id in artifact_ids
    ]
    return result


def _criterion_value(
    *,
    title: str = "Robustness",
    provenance: list[str] | None = None,
    replaces: list[str] | None = None,
) -> dict[str, object]:
    return {
        "criteria": [{
            "title": title,
            "requirement": "Test the result under a task-relevant perturbation.",
            "levels": [
                {"label": "A", "description": "The check is complete and valid."},
                {"label": "B", "description": "The check is incomplete."},
                {"label": "C", "description": "The check is absent or invalid."},
            ],
            "provenance_pair_ids": (
                _induction_pair_ids()[:1] if provenance is None else provenance
            ),
            "replaces": [] if replaces is None else replaces,
        }]
    }


def _validation_value(
    schema: dict[str, object],
    *,
    positive_pair_ids: tuple[str, ...] | None = None,
    reverse_pair_ids: tuple[str, ...] = (),
    tie_pair_ids: tuple[str, ...] = (),
    penalize_preferred: bool = False,
):
    item = schema["properties"]["validations"]["items"]  # type: ignore[index]
    properties = item["properties"]
    candidate_ids = properties["criterion_id"]["enum"]
    application_item = properties["artifact_applications"]["items"]
    application_properties = application_item["properties"]
    artifact_ids = application_properties["artifact_id"]["enum"]
    level_labels = application_properties["level"]["enum"]
    comparisons_by_id = {item.pair_id: item for item in _comparisons()}
    positive_pair_ids = (
        (_induction_pair_ids()[0],)
        if positive_pair_ids is None
        else positive_pair_ids
    )
    constrained_ids = {
        *positive_pair_ids,
        *reverse_pair_ids,
        *tie_pair_ids,
    }
    if not constrained_ids <= comparisons_by_id.keys():
        raise AssertionError("validation helper received an unknown pair ID")

    levels_by_artifact = None
    fixture_ids = assessment_module.validation_artifact_ids(_comparisons())
    for ranks in product(range(len(level_labels)), repeat=len(fixture_ids)):
        ranks_by_artifact = dict(zip(fixture_ids, ranks, strict=True))

        def pair_ranks(pair_id: str) -> tuple[int, int]:
            comparison = comparisons_by_id[pair_id]
            return (
                ranks_by_artifact[comparison.preferred_artifact_id],
                ranks_by_artifact[comparison.rejected_artifact_id],
            )

        if any(
            preferred >= rejected
            for preferred, rejected in map(pair_ranks, positive_pair_ids)
        ):
            continue
        if any(
            preferred <= rejected
            for preferred, rejected in map(pair_ranks, reverse_pair_ids)
        ):
            continue
        if any(
            preferred != rejected
            for preferred, rejected in map(pair_ranks, tie_pair_ids)
        ):
            continue
        if any(
            preferred > rejected
            for pair_id in comparisons_by_id
            if pair_id not in reverse_pair_ids
            for preferred, rejected in (pair_ranks(pair_id),)
        ):
            continue
        if penalize_preferred:
            support = comparisons_by_id[positive_pair_ids[0]]
            if ranks_by_artifact[support.preferred_artifact_id] == 0:
                continue
        levels_by_artifact = {
            artifact_id: level_labels[ranks_by_artifact[artifact_id]]
            for artifact_id in artifact_ids
        }
        break
    if levels_by_artifact is None:
        raise AssertionError("validation helper constraints are inconsistent")
    return {
        "validations": [
            {
                "criterion_id": criterion_id,
                "observable": True,
                "nonredundant": True,
                "artifact_applications": [
                    {
                        "artifact_id": artifact_id,
                        "level": levels_by_artifact[artifact_id],
                        "reason": "The artifact supports this criterion level.",
                    }
                    for artifact_id in artifact_ids
                ],
                "reason": "The candidate is observable and distinct.",
            }
            for criterion_id in candidate_ids
        ]
    }


def _proposer(run_proposer=None, *, retries: int = 1) -> RubricProposer:
    counters: dict[str, int] = {}

    def default_proposer(**kwargs):
        stage = kwargs["stage"]
        counters[stage] = counters.get(stage, 0) + 1
        if stage == "assessment_rubric_free":
            value = _assessment_value(
                relation="preferred",
                schema=kwargs["response_schema"],
            )
        elif stage in {
            "assessment_active_rubric",
            "assessment_development_rubric",
        }:
            value = _assessment_value(
                relation="tie",
                schema=kwargs["response_schema"],
            )
        elif stage == "induction":
            value = _criterion_value()
        elif stage == "validation":
            value = _validation_value(kwargs["response_schema"])
        else:
            raise AssertionError(f"unexpected stage: {stage}")
        return _proposer_output(value, f"{stage}-{counters[stage]}")

    return RubricProposer(
        benchmark=SubmissionBenchmarkId.BIOMNIBENCH_DA,
        model="proposer",
        max_retries=retries,
        run_proposer=run_proposer or default_proposer,
    )


def _replace(
    proposer: RubricProposer,
    root: Path,
    *,
    policy: RubricPolicy = RubricPolicy.OFFLINE_ELICITATION,
) -> RubricGeneration:
    return proposer.elicit_rubric(
        instruction="Solve the analysis task.",
        original_rubric=_rubric(),
        development_rubric=_development_rubric(),
        current_generation=_initial_generation(),
        policy=policy,
        generation_round=1,
        output_dir=root,
        artifact_history=_history(),
        source_checkpoint=None,
    )


def _next_online_generation(
    proposer: RubricProposer,
    root: Path,
    current: RubricGeneration,
) -> RubricGeneration:
    return proposer.elicit_rubric(
        instruction="Solve the analysis task.",
        original_rubric=_rubric(),
        development_rubric=_development_rubric(),
        current_generation=current,
        policy=RubricPolicy.ONLINE_ELICITATION,
        generation_round=current.generation_round + 1,
        output_dir=root,
        artifact_history=_history(),
        source_checkpoint=current.generation_round,
    )


